css:
.apk-sprint {
  position: relative; width: 100%; height: var(--apk-sprint-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate;
  -webkit-tap-highlight-color: transparent; box-sizing: border-box;
  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & .apk-sprint-layer { position: absolute; inset: 0; z-index: 90; pointer-events: none; overflow: clip; }
  & .apk-sprint-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .apk-sprint-list { position: relative; }
  & .apk-sprint-card {
    user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;
    touch-action: manipulation; cursor: grab;
    &.is-src { display: none; }
  }
  & .apk-sprint-card.is-ghost {
    position: absolute; left: 0; top: 0; margin: 0; z-index: 2; cursor: grabbing;
    scale: 1.04; will-change: translate, rotate;
    transition: scale .3s var(--apk-sprint-spring), box-shadow .3s ease-out, opacity .2s;
    @starting-style { scale: 1; }
    &.is-over-zone { scale: .9; opacity: .8; }
  }
  & .apk-sprint-card.is-flyer { z-index: 1; }
  & .apk-sprint-ph { transition: opacity .18s ease-out; @starting-style { opacity: 0; } }
  &.is-dragging, &.is-dragging * { cursor: grabbing; }
  & .apk-sprint-toast {
    position: absolute; z-index: 95; left: 50%; bottom: 16px; translate: -50% 140%;
    display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
    opacity: 0; pointer-events: none;
    transition: translate .45s var(--apk-sprint-spring), opacity .2s ease-out;
    & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
    & [data-undo] { display: none; flex: none; }
    &.has-undo [data-undo] { display: inline-flex; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }
}

@property --apk-sprint-n { syntax: '<integer>'; inherits: false; initial-value: 0; }
@keyframes apk-sprint-hazard { to { background-position: 22.6px 0; } }
@keyframes apk-sprint-in { from { opacity: 0; translate: 0 10px; scale: .97; } }
@keyframes apk-sprint-pop { 0% { opacity: 0; scale: .86; filter: blur(6px); } 60% { opacity: 1; filter: blur(0); } }
@keyframes apk-sprint-draw { from { stroke-dashoffset: 1; } }
@keyframes apk-sprint-pulse { 50% { opacity: .35; } }

.apk-sprint {
  --apk-sprint-bg: oklch(0.185 0.008 262);
  --apk-sprint-ink: oklch(0.95 0.004 262);
  --apk-sprint-accent: oklch(0.76 0.165 56);
  --apk-sprint-warn: oklch(0.67 0.2 27);
  --apk-sprint-panel: color-mix(in oklch, var(--apk-sprint-bg), white 3.5%);
  --apk-sprint-raise: color-mix(in oklch, var(--apk-sprint-bg), white 7.5%);
  --apk-sprint-line: color-mix(in oklch, var(--apk-sprint-ink) 11%, transparent);
  --apk-sprint-line2: color-mix(in oklch, var(--apk-sprint-ink) 18%, transparent);
  --apk-sprint-mute: color-mix(in oklch, var(--apk-sprint-ink) 56%, var(--apk-sprint-bg));
  --apk-sprint-faint: color-mix(in oklch, var(--apk-sprint-ink) 34%, var(--apk-sprint-bg));
  --apk-sprint-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  --apk-sprint-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  background: var(--apk-sprint-bg); color: var(--apk-sprint-ink);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
  border-radius: 14px; color-scheme: dark; accent-color: var(--apk-sprint-accent);

  & kbd {
    font: 600 10.5px/1 var(--apk-sprint-mono); padding: 3px 5px 2px; border-radius: 5px;
    border: 1px solid var(--apk-sprint-line2); border-bottom-width: 2px; color: var(--apk-sprint-mute);
    background: color-mix(in oklch, var(--apk-sprint-ink) 4%, transparent);
  }
  & h3 { margin: 0; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apk-sprint-mute); }
  & :focus-visible { outline: 2px solid var(--apk-sprint-accent); outline-offset: 2px; }

  & .apk-sprint-app {
    height: 100%; display: grid;
    grid-template: "side top" auto "side main" 1fr / 252px minmax(0, 1fr);
  }

  /* ── sidebar ── */
  & .apk-sprint-side {
    grid-area: side; min-height: 0; overflow-y: auto; padding: 16px 16px 20px;
    display: flex; flex-direction: column; gap: 22px;
    border-right: 1px solid var(--apk-sprint-line); background: var(--apk-sprint-panel);
    border-radius: 14px 0 0 14px; scrollbar-width: thin;
  }
  & .apk-sprint-brand {
    display: flex; gap: 10px; align-items: center;
    & svg { width: 30px; height: 30px; padding: 6px; border-radius: 8px; background: var(--apk-sprint-accent); stroke: var(--apk-sprint-bg); fill: none; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
    & b { display: block; font-size: 14px; letter-spacing: -.01em; }
    & span { color: var(--apk-sprint-mute); font-size: 12px; }
  }
  & .apk-sprint-goal p { margin: 8px 0 0; color: color-mix(in oklch, var(--apk-sprint-ink) 82%, var(--apk-sprint-bg)); text-wrap: pretty; line-height: 1.5; }
  & .apk-sprint-burn header { display: flex; justify-content: space-between; align-items: baseline; }
  & .apk-sprint-status { font-size: 11px; font-weight: 600; color: var(--apk-sprint-accent); }
  & .apk-sprint-status[data-tone="ok"] { color: oklch(0.8 0.14 150); }
  & .apk-sprint-chart {
    width: 100%; height: auto; margin-top: 8px; overflow: visible;
    & .apk-sprint-grid path { stroke: var(--apk-sprint-line); stroke-width: 1; fill: none; }
    & .apk-sprint-ideal { stroke: var(--apk-sprint-faint); stroke-width: 1.25; stroke-dasharray: .015 .02; fill: none; }
    & .apk-sprint-area { fill: color-mix(in oklch, var(--apk-sprint-accent) 16%, transparent); transition: d .6s var(--apk-sprint-spring); }
    & .apk-sprint-line { stroke: var(--apk-sprint-accent); stroke-width: 2.25; fill: none; stroke-linejoin: round; stroke-linecap: round;
      stroke-dasharray: 1; animation: apk-sprint-draw 1.2s cubic-bezier(.6,0,.2,1) both .2s; transition: d .6s var(--apk-sprint-spring); }
    & .apk-sprint-today { transition: translate .6s var(--apk-sprint-spring); }
    & .apk-sprint-today line { stroke: color-mix(in oklch, var(--apk-sprint-accent) 40%, transparent); stroke-dasharray: 2 3; }
    & .apk-sprint-today circle { fill: var(--apk-sprint-bg); stroke: var(--apk-sprint-accent); stroke-width: 2.25; }
    & .apk-sprint-days text { font: 600 8.5px var(--apk-sprint-mono); fill: var(--apk-sprint-faint); text-anchor: middle; }
    & .apk-sprint-days text.is-today { fill: var(--apk-sprint-accent); }
  }
  & .apk-sprint-stats {
    display: grid; grid-template-columns: repeat(3, 1fr); margin: 10px 0 0; gap: 6px;
    & div { padding: 8px 9px; border-radius: 8px; background: color-mix(in oklch, var(--apk-sprint-ink) 4%, transparent); }
    & dt { font-size: 10px; color: var(--apk-sprint-mute); }
    & dd { margin: 2px 0 0; font: 650 17px/1.1 system-ui; font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
    & small { font-size: 11px; color: var(--apk-sprint-faint); font-weight: 500; }
  }
  & .apk-sprint-epics { display: grid; gap: 4px; margin-top: 8px; }
  & .apk-sprint-epic-f {
    display: grid; grid-template-columns: 10px 1fr auto; gap: 9px; align-items: center;
    padding: 6px 8px; border: 0; border-radius: 7px; background: none; text-align: left;
    transition: background .15s;
    & i { width: 10px; height: 10px; border-radius: 3px; background: oklch(0.74 0.12 var(--h)); }
    & em { font-style: normal; color: var(--apk-sprint-faint); font-variant-numeric: tabular-nums; font-size: 12px; }
    &:hover { background: color-mix(in oklch, var(--apk-sprint-ink) 6%, transparent); }
    &[aria-pressed="true"] { background: color-mix(in oklch, oklch(0.74 0.12 var(--h)) 16%, transparent); }
    &[aria-pressed="true"] em { color: var(--apk-sprint-ink); }
  }
  & .apk-sprint-keys ul { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 7px; color: var(--apk-sprint-mute); font-size: 12px; }
  & .apk-sprint-keys kbd { margin-right: 4px; }

  /* ── header ── */
  & .apk-sprint-top {
    grid-area: top; display: flex; flex-wrap: wrap; align-items: center; gap: 12px 20px;
    padding: 14px 18px 12px; border-bottom: 1px solid var(--apk-sprint-line);
  }
  & .apk-sprint-title {
    flex: 1 1 260px; min-width: 0;
    & h2 { margin: 0; font-size: clamp(16px, 1.1cqi + 8px, 20px); font-weight: 700; letter-spacing: -.02em; text-wrap: balance; }
    & h2 span { font-weight: 450; color: var(--apk-sprint-mute); margin-left: 4px; }
    & p { margin: 4px 0 0; display: flex; flex-wrap: wrap; gap: 4px 14px; color: var(--apk-sprint-mute); font-size: 12px; font-variant-numeric: tabular-nums; }
    & p b { color: var(--apk-sprint-ink); font-weight: 600; }
  }
  & .apk-sprint-pct {
    --apk-sprint-n: 0; counter-reset: p var(--apk-sprint-n); transition: --apk-sprint-n 1s cubic-bezier(.3,.7,.2,1);
    color: var(--apk-sprint-accent); font-weight: 650;
    &::after { content: counter(p) "%"; }
  }
  & .apk-sprint-stack {
    display: flex; height: 4px; gap: 2px; margin-top: 9px; max-width: 420px;
    & i { height: 100%; border-radius: 2px; flex: var(--w) 1 0; transition: flex-grow .6s var(--apk-sprint-spring); }
    & [data-k="done"] { background: var(--apk-sprint-accent); }
    & [data-k="rev"] { background: color-mix(in oklch, var(--apk-sprint-accent) 55%, var(--apk-sprint-bg)); }
    & [data-k="prog"] { background: color-mix(in oklch, var(--apk-sprint-accent) 30%, var(--apk-sprint-bg)); }
    & [data-k="todo"] { background: var(--apk-sprint-line2); }
  }
  & .apk-sprint-tools { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
  & .apk-sprint-people { display: flex; padding-left: 6px; }
  & .apk-sprint-pf {
    width: 30px; height: 30px; margin-left: -6px; border-radius: 50%; border: 2px solid var(--apk-sprint-bg); padding: 0;
    background: oklch(0.74 0.11 var(--h)); color: oklch(0.22 0.04 var(--h)); font-size: 10.5px; font-weight: 700;
    transition: translate .25s var(--apk-sprint-spring), box-shadow .2s, opacity .2s; position: relative;
    &:hover { translate: 0 -3px; z-index: 1; }
    &[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--apk-sprint-accent); z-index: 2; }
  }
  & .apk-sprint-people:has([aria-pressed="true"]) .apk-sprint-pf:not([aria-pressed="true"]) { opacity: .42; }
  & .apk-sprint-search {
    display: flex; align-items: center; gap: 7px; height: 32px; padding: 0 8px 0 10px; border-radius: 8px;
    background: color-mix(in oklch, var(--apk-sprint-ink) 5%, transparent); border: 1px solid var(--apk-sprint-line);
    transition: border-color .15s, background .15s;
    & svg { width: 15px; height: 15px; fill: none; stroke: var(--apk-sprint-mute); stroke-width: 2; stroke-linecap: round; flex: none; }
    & input { border: 0; background: none; outline: none; width: 130px; min-width: 0; }
    & input::placeholder { color: var(--apk-sprint-faint); }
    &:focus-within { border-color: color-mix(in oklch, var(--apk-sprint-accent) 60%, transparent); background: color-mix(in oklch, var(--apk-sprint-ink) 8%, transparent); }
    &:focus-within kbd { opacity: 0; }
  }
  & .apk-sprint-seg {
    display: flex; padding: 3px; border-radius: 9px; background: color-mix(in oklch, var(--apk-sprint-ink) 5%, transparent);
    & button { border: 0; background: none; padding: 5px 10px; border-radius: 6px; font-size: 12px; font-weight: 550; color: var(--apk-sprint-mute); transition: background .2s, color .2s; }
    & [aria-selected="true"] { background: var(--apk-sprint-raise); color: var(--apk-sprint-ink); box-shadow: 0 1px 2px rgb(0 0 0 / .3); }
  }
  & .apk-sprint-new {
    display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 8px 0 10px; border-radius: 8px; border: 0;
    background: var(--apk-sprint-accent); color: oklch(0.2 0.03 56); font-weight: 650; font-size: 12.5px;
    transition: scale .2s var(--apk-sprint-spring), filter .2s;
    & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; }
    & kbd { color: inherit; border-color: color-mix(in oklch, currentColor 25%, transparent); background: none; }
    &:hover { filter: brightness(1.08); }
    &:active { scale: .96; }
  }
  & .apk-sprint-tabs { display: none; }

  /* ── board ── */
  & .apk-sprint-main { grid-area: main; min-height: 0; position: relative; }
  & .apk-sprint-board {
    height: 100%; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(200px, 1fr);
    gap: 12px; padding: 14px 16px 16px; overflow-x: auto; overscroll-behavior-x: contain; scrollbar-width: thin;
  }
  & .apk-sprint-col {
    display: flex; flex-direction: column; min-height: 0;
    border-radius: 12px; background: var(--apk-sprint-panel); border: 1px solid var(--apk-sprint-line);
    transition: border-color .2s, background .2s;
  }
  & .apk-sprint-colhead {
    display: flex; align-items: center; gap: 8px; padding: 11px 12px 8px; border-radius: 12px 12px 0 0;
    & h3 { color: var(--apk-sprint-ink); flex: 1; }
    & .apk-sprint-dot { width: 8px; height: 8px; border-radius: 50%; border: 2px solid var(--apk-sprint-mute); }
    & .apk-sprint-count { font: 600 11.5px var(--apk-sprint-mono); font-variant-numeric: tabular-nums; color: var(--apk-sprint-mute); }
    & .apk-sprint-colpts { font-size: 11px; color: var(--apk-sprint-faint); font-variant-numeric: tabular-nums; }
  }
  & .apk-sprint-col[data-k="prog"] .apk-sprint-dot { border-color: var(--apk-sprint-accent); border-right-color: transparent; }
  & .apk-sprint-col[data-k="rev"] .apk-sprint-dot { border-color: var(--apk-sprint-accent); background: conic-gradient(var(--apk-sprint-accent) 0 75%, transparent 0); }
  & .apk-sprint-col[data-k="done"] .apk-sprint-dot { border-color: var(--apk-sprint-accent); background: var(--apk-sprint-accent); }
  & .apk-sprint-wipbar {
    display: flex; gap: 3px; margin: 0 12px 4px; height: 3px;
    & i { flex: 1; border-radius: 2px; background: var(--apk-sprint-line); transition: background .3s; }
    & i.on { background: var(--apk-sprint-accent); }
    & i.x { background: var(--apk-sprint-warn); animation: apk-sprint-pulse 1.4s ease-in-out infinite; }
  }
  & .apk-sprint-wipnote { display: none; margin: 0 12px 6px; font-size: 11px; font-weight: 600; color: var(--apk-sprint-warn); }
  & .apk-sprint-col[data-wip="at"] .apk-sprint-count { color: var(--apk-sprint-accent); }
  & .apk-sprint-col[data-wip="over"] {
    border-color: color-mix(in oklch, var(--apk-sprint-warn) 55%, transparent);
    & .apk-sprint-colhead {
      background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--apk-sprint-warn) 20%, transparent) 0 8px, transparent 8px 16px);
      background-size: 22.6px 22.6px; animation: apk-sprint-hazard 1.1s linear infinite;
    }
    & .apk-sprint-count { color: var(--apk-sprint-warn); }
    & .apk-sprint-wipnote.is-over { display: block; }
  }
  /* :has() previews the WIP breach while a card hovers a full column */
  & .apk-sprint-col[data-wip="at"]:has(.apk-sprint-ph):not(:has(.is-src)) {
    border-color: color-mix(in oklch, var(--apk-sprint-warn) 55%, transparent);
    & .apk-sprint-wipnote.is-would { display: block; }
    & .apk-sprint-ph { border-color: var(--apk-sprint-warn); background: color-mix(in oklch, var(--apk-sprint-warn) 10%, transparent); }
  }
  &.is-dragging .apk-sprint-col:has(.apk-sprint-ph) { background: color-mix(in oklch, var(--apk-sprint-panel), var(--apk-sprint-accent) 4%); border-color: color-mix(in oklch, var(--apk-sprint-accent) 35%, transparent); }
  & .apk-sprint-hidden { font-size: 11px; color: var(--apk-sprint-faint); padding: 0 12px 8px; }
  & .apk-sprint-hidden:empty { display: none; }
  & .apk-sprint-list {
    flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 4px 8px 10px; display: flex; flex-direction: column; gap: 7px;
    scrollbar-width: thin; overscroll-behavior: contain;
    &:empty::after { content: "Drop issues here"; display: grid; place-items: center; height: 72px; border: 1px dashed var(--apk-sprint-line2); border-radius: 10px; color: var(--apk-sprint-faint); font-size: 12px; }
  }

  /* ── composer ── */
  & .apk-sprint-composer {
    display: none; margin: 0 8px 8px; padding: 10px; border-radius: 10px; gap: 8px;
    background: var(--apk-sprint-raise); border: 1px solid color-mix(in oklch, var(--apk-sprint-accent) 50%, transparent);
    box-shadow: 0 0 0 4px color-mix(in oklch, var(--apk-sprint-accent) 12%, transparent);
    transition: opacity .25s, translate .35s var(--apk-sprint-spring);
    & textarea { width: 100%; resize: none; border: 0; background: none; outline: none; font-weight: 500; line-height: 1.35; }
    & .apk-sprint-crow { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; }
    & select { font-size: 11.5px; padding: 3px 4px; border-radius: 6px; border: 1px solid var(--apk-sprint-line2); background: var(--apk-sprint-panel); }
    & .apk-sprint-hint { margin-left: auto; font-size: 11px; color: var(--apk-sprint-faint); }
  }
  & .apk-sprint-col.is-composing .apk-sprint-composer { display: grid; @starting-style { opacity: 0; translate: 0 -8px; } }

  /* ── cards ── */
  & .apk-sprint-card {
    position: relative; display: grid; gap: 7px; padding: 10px 11px 10px 12px; border-radius: 10px;
    background: var(--apk-sprint-raise); border: 1px solid var(--apk-sprint-line);
    box-shadow: 0 1px 0 rgb(255 255 255 / .03) inset, 0 1px 2px rgb(0 0 0 / .25);
    transition: border-color .15s, background .15s, translate .25s var(--apk-sprint-spring), box-shadow .2s;
    &:hover { border-color: var(--apk-sprint-line2); background: color-mix(in oklch, var(--apk-sprint-raise), white 2.5%); translate: 0 -1px; }
    &.is-open { border-color: color-mix(in oklch, var(--apk-sprint-accent) 70%, transparent); }
    &.is-blocked::before { content: ""; position: absolute; left: -1px; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--apk-sprint-warn); }
    &.is-done .apk-sprint-c-title { color: var(--apk-sprint-mute); }
    &.is-done .apk-sprint-key { text-decoration: line-through; text-decoration-color: var(--apk-sprint-faint); }
    &.is-new { animation: apk-sprint-pop .7s var(--apk-sprint-spring) both; }
    &.is-lifted {
      outline: 2px dashed var(--apk-sprint-accent); outline-offset: 2px; translate: 0 -3px;
      box-shadow: 0 14px 30px -10px rgb(0 0 0 / .6);
    }
    &.is-ghost {
      border-color: color-mix(in oklch, var(--apk-sprint-accent) 60%, transparent);
      box-shadow: 0 26px 50px -14px rgb(0 0 0 / .7), 0 0 0 1px color-mix(in oklch, var(--apk-sprint-accent) 40%, transparent), 0 0 32px -8px color-mix(in oklch, var(--apk-sprint-accent) 45%, transparent);
    }
    &.is-ghost.is-landing { box-shadow: 0 1px 2px rgb(0 0 0 / .25); }
  }
  &.is-mounting .apk-sprint-card { animation: apk-sprint-in .55s var(--apk-sprint-spring) both; animation-delay: calc(var(--i, 0) * 32ms); }
  & .apk-sprint-ph { border-radius: 10px; border: 1.5px dashed color-mix(in oklch, var(--apk-sprint-accent) 60%, transparent); background: color-mix(in oklch, var(--apk-sprint-accent) 7%, transparent); }
  & .apk-sprint-c-top { display: flex; align-items: center; gap: 7px; }
  & .apk-sprint-key { font: 600 11px var(--apk-sprint-mono); color: var(--apk-sprint-mute); letter-spacing: .01em; }
  & .apk-sprint-flag { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--apk-sprint-warn); }
  & .apk-sprint-prio { margin-left: auto; display: inline-flex; }
  & .apk-sprint-prio svg { width: 14px; height: 14px; }
  & .apk-sprint-prio rect { fill: var(--apk-sprint-line2); }
  & .apk-sprint-prio rect.on { fill: var(--apk-sprint-mute); }
  & .apk-sprint-prio[data-p="urgent"] rect { fill: var(--apk-sprint-warn); }
  & .apk-sprint-c-title { margin: 0; font-size: 13px; font-weight: 520; line-height: 1.38; text-wrap: pretty; }
  & .apk-sprint-c-meta { display: flex; align-items: center; gap: 8px; min-width: 0; }
  & .apk-sprint-epic { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; color: var(--apk-sprint-mute); min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .apk-sprint-epic::before { content: ""; flex: none; width: 7px; height: 7px; border-radius: 2px; background: oklch(0.74 0.12 var(--h)); }
