/* ── board kit · keyed nodes, FLIP, undo/redo, pointer + keyboard drag ── */
const doc = root.ownerDocument;
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1)';
const EASE = 'cubic-bezier(.2,.8,.2,1)';
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => [...(el || root).querySelectorAll(s)];
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const uid = 'apk-sprint' + Math.random().toString(36).slice(2, 8);
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl+';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });

function boardKit(o) {
  const CARD = '.apk-sprint-card', LIST = '.apk-sprint-list', COL = '.apk-sprint-col';
  const els = new Map();
  const mk = (cls, tag) => { const n = doc.createElement(tag || 'div'); n.className = cls; return n; };
  const layer = $('.apk-sprint-layer') || root.appendChild(mk('apk-sprint-layer'));
  layer.setAttribute('aria-hidden', 'true');
  const live = root.appendChild(mk('apk-sprint-sr')); live.setAttribute('aria-live', 'assertive');
  const hint = root.appendChild(mk('apk-sprint-sr')); hint.id = uid + '-hint';
  hint.textContent = 'Space picks the card up, arrow keys move it, Space drops it, Escape cancels. Enter opens it.';
  const toastEl = $('.apk-sprint-toast');
  const past = [], future = [];
  let lift = null, st = null, raf = 0, quiet = 0, tt = 0, stepping = false;

  const say = m => { live.textContent = ''; requestAnimationFrame(() => { if (!root.isConnected) return; live.textContent = m; }); };
  const cardsIn = l => l ? [...l.children].filter(n => n.matches(CARD) && !n.classList.contains('is-src')) : [];

  /* keyed card nodes: the same element survives every re-render, so focus,
     running animations and FLIP all keep working */
  function card(id, cls, html, label) {
    let n = els.get(id);
    if (!n) {
      n = mk('', 'article'); n.dataset.id = id; n.tabIndex = 0;
      n.setAttribute('role', 'listitem'); n.setAttribute('aria-describedby', hint.id);
      els.set(id, n);
    }
    const c = 'apk-sprint-card' + (cls ? ' ' + cls : '') + (lift && lift.id === id ? ' is-lifted' : '');
    if (n.className !== c) n.className = c;
    if (n._h !== html) { n.innerHTML = html; n._h = html; }
    if (label && n.getAttribute('aria-label') !== label) n.setAttribute('aria-label', label);
    return n;
  }
  function place(list, nodes) {
    nodes.forEach((n, i) => { if (list.children[i] !== n) list.insertBefore(n, list.children[i] || null); });
    while (list.children.length > nodes.length) list.lastElementChild.remove();
  }

  /* FLIP every keyed card across a state change; cards that change list fly
     in the overlay layer so the destination column's overflow can't clip them */
  function flip(run) {
    if (RM.matches || !root.isConnected) { run(); return; }
    const before = new Map();
    els.forEach(n => { if (n.isConnected && n.offsetParent) before.set(n, [n.getBoundingClientRect(), n.parentNode]); });
    run();
    const rr = root.getBoundingClientRect();
    els.forEach(n => {
      const b0 = before.get(n);
      if (!b0 || !n.isConnected || !n.offsetParent) return;
      const a = b0[0], b = n.getBoundingClientRect();
      const dx = a.left - b.left, dy = a.top - b.top;
      if (Math.abs(dx) < 1 && Math.abs(dy) < 1) return;
      if (b0[1] !== n.parentNode && Math.abs(dx) > 8) { fly(n, a, b, rr); return; }
      n.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' }, { transform: 'none' }], { duration: 420, easing: SPRING });
    });
  }
  function fly(n, a, b, rr) {
    const c = n.cloneNode(true);
    ['data-id', 'tabindex', 'id', 'aria-describedby'].forEach(k => c.removeAttribute(k));
    c.classList.add('is-flyer'); c.classList.remove('is-lifted');
    Object.assign(c.style, { position: 'absolute', margin: '0', left: (b.left - rr.left) + 'px', top: (b.top - rr.top) + 'px', width: b.width + 'px', height: b.height + 'px' });
    layer.append(c); n.style.opacity = '0';
    const dx = a.left - b.left, dy = a.top - b.top;
    const an = c.animate([
      { transform: 'translate(' + dx + 'px,' + dy + 'px)' },
      { transform: 'translate(' + dx * .42 + 'px,' + (dy * .42 - 22) + 'px) scale(1.05) rotate(' + (dx > 0 ? 2.5 : -2.5) + 'deg)', offset: .42 },
      { transform: 'none' }], { duration: 560, easing: 'cubic-bezier(.3,.7,.15,1)' });
    an.onfinish = an.oncancel = () => { c.remove(); n.style.opacity = ''; };
  }

  /* history: snapshots of the component's data, so undo is exact */
  function record(label, snap) {
    past.push({ label, snap }); if (past.length > 80) past.shift();
    future.length = 0; toast(label, true); say(label);
  }
  function apply(fn) {
    const snap = structuredClone(o.get());
    const label = fn();
    if (!label) return false;
    record(label, snap); flip(o.render); return label;
  }
  function undo() {
    if (st || lift) return;
    const u = past.pop();
    if (!u) { toast('Nothing to undo'); return; }
    future.push({ label: u.label, snap: structuredClone(o.get()) });
    o.set(u.snap); flip(o.render); toast('Undone · ' + u.label); say('Undone: ' + u.label);
  }
  function redo() {
    if (st || lift) return;
    const r = future.pop();
    if (!r) { toast('Nothing to redo'); return; }
    past.push({ label: r.label, snap: structuredClone(o.get()) });
    o.set(r.snap); flip(o.render); toast('Redone · ' + r.label, true);
  }
  /* external events (a new order, a new report) are rebased onto every snapshot so undo never erases them */
  function amend(fn) { fn(o.get()); past.forEach(p => fn(p.snap)); future.forEach(f => fn(f.snap)); if (lift) fn(lift.snap); }
  function toast(msg, undoable) {
    if (!toastEl) return;
    toastEl.querySelector('[data-msg]').textContent = msg;
    toastEl.classList.toggle('has-undo', !!undoable);
    toastEl.classList.remove('is-on'); void toastEl.offsetWidth; toastEl.classList.add('is-on');
    clearTimeout(tt); tt = setTimeout(() => toastEl.classList.remove('is-on'), 4200);
  }
  if (toastEl) toastEl.addEventListener('click', e => { if (e.target.closest('[data-undo]')) undo(); });

  /* scroll an element into view inside the component only — never the page */
  function reveal(n) {
    for (let p = n.parentElement; p && p !== root; p = p.parentElement) {
      const cs = getComputedStyle(p);
      const sy = /auto|scroll/.test(cs.overflowY) && p.scrollHeight > p.clientHeight;
      const sx = /auto|scroll/.test(cs.overflowX) && p.scrollWidth > p.clientWidth;
      if (!sx && !sy) continue;
      const pr = p.getBoundingClientRect(), r = n.getBoundingClientRect();
      if (sy) { if (r.top < pr.top + 8) p.scrollTop -= pr.top + 8 - r.top; else if (r.bottom > pr.bottom - 8) p.scrollTop += r.bottom - pr.bottom + 8; }
      if (sx) { if (r.left < pr.left) p.scrollLeft -= pr.left - r.left; else if (r.right > pr.right) p.scrollLeft += r.right - pr.right; }
    }
  }

  /* lists form a grid: data-row / data-col on each list element */
  const gridOf = () => (o.lists ? o.lists() : $$(LIST)).map(l => ({ l, r: +l.dataset.row || 0, c: +l.dataset.col || 0 }));
  function neighbor(l, dr, dc) {
    const g = gridOf(), me = g.find(x => x.l === l);
    if (!me) return null;
    const pool = g.filter(x => dc ? x.r === me.r && Math.sign(x.c - me.c) === dc : x.c === me.c && Math.sign(x.r - me.r) === dr)
      .sort((a, b) => dc ? Math.abs(a.c - me.c) - Math.abs(b.c - me.c) : Math.abs(a.r - me.r) - Math.abs(b.r - me.r));
    return pool.length ? pool[0].l : null;
  }
  function focusCard(n) {
    if (!n) return;
    if (o.show) o.show(n.closest(LIST));
    n.focus({ preventScroll: true }); reveal(n);
  }
  function nav(cardEl, key) {
    const l = cardEl.closest(LIST), k = cardsIn(l), i = k.indexOf(cardEl);
    if (key === 'ArrowUp' || key === 'ArrowDown') {
      const d = key === 'ArrowUp' ? -1 : 1;
      if (k[i + d]) return focusCard(k[i + d]);
      for (let t = neighbor(l, d, 0); t; t = neighbor(t, d, 0)) { const kk = cardsIn(t); if (kk.length) return focusCard(d < 0 ? kk[kk.length - 1] : kk[0]); }
      return;
    }
    const d = key === 'ArrowLeft' ? -1 : 1;
    for (let t = neighbor(l, 0, d); t; t = neighbor(t, 0, d)) { const kk = cardsIn(t); if (kk.length) return focusCard(kk[Math.min(i, kk.length - 1)]); }
  }

  /* keyboard drag: Space lifts, arrows move live, Space drops, Escape restores */
  function pick(n) {
    if (o.canDrag && !o.canDrag(n.dataset.id)) { say(o.name(n.dataset.id) + ' can\u2019t be moved from here.'); return; }
    lift = { id: n.dataset.id, snap: structuredClone(o.get()) };
    n.classList.add('is-lifted'); root.classList.add('is-kbd-drag');
    say('Picked up ' + o.name(lift.id) + '. ' + o.where(lift.id) + '. Arrow keys move, Space drops, Escape cancels.');
  }
  function step(key) {
