    '<div class="apk-sprint-c-meta"><span class="apk-sprint-epic" style="--h:' + EPICS[it.epic][1] + '">' + EPICS[it.epic][0] + '</span>' +
    (it.sub.length ? '<span class="apk-sprint-subs' + (done === it.sub.length ? ' is-full' : '') + '">' + CHECK + done + '/' + it.sub.length + '</span>' : '') +
    '<span class="apk-sprint-c-pts" title="Story points">' + it.pts + '</span>' + avatar(it.who) + '</div>';
  const n = K.card(id, (k === 'done' ? 'is-done' : '') + (it.blocked ? ' is-blocked' : '') + (fresh === id ? ' is-new' : '') + (openId === id ? ' is-open' : ''), html,
    id + ', ' + it.title + ', ' + it.pts + ' points, ' + PEOPLE[it.who][0] + ', ' + colName(k) + (it.blocked ? ', blocked' : ''));
  n.style.setProperty('--i', i);
  return n;
}

function render() {
  root.dataset.view = view;
  table.hidden = view !== 'table';
  let shownIdx = 0;
  COLS.forEach(c => {
    const ids = data.cells[c.k], shown = ids.filter(visible), ce = colEl[c.k];
    K.place(ce.list, shown.map(id => cardNode(id, c.k, shownIdx++)));
    const n = ids.length;
    ce.count.textContent = c.lim ? n + '/' + c.lim : n;
    ce.pts.textContent = sum(ids) + ' pts';
    ce.el.dataset.wip = c.lim ? (n > c.lim ? 'over' : n === c.lim ? 'at' : 'ok') : '';
    if (ce.bar) ce.bar.innerHTML = Array.from({ length: Math.max(c.lim, n) }, (_, j) => '<i class="' + (j >= c.lim ? 'x' : j < n ? 'on' : '') + '"></i>').join('');
    ce.hidden.textContent = n - shown.length ? (n - shown.length) + ' hidden by filters' : '';
    const tb = tabs.querySelector('[data-k="' + c.k + '"]');
    tb.innerHTML = c.t + '<span>' + (c.lim ? n + '/' + c.lim : n) + '</span>'; tb.dataset.wip = ce.el.dataset.wip;
  });
  syncTabs();

  const all = Object.keys(data.items), total = sum(all), done = sum(data.cells.done);
  $('[data-done]').textContent = done; $('[data-total]').textContent = total;
  $('[data-pct]').style.setProperty('--apk-sprint-n', Math.round(done / total * 100));
  $('[data-stack]').innerHTML = ['done', 'rev', 'prog', 'todo'].map(k => '<i data-k="' + k + '" style="--w:' + sum(data.cells[k]) + '" title="' + colName(k) + ': ' + sum(data.cells[k]) + ' pts"></i>').join('');
  burndown(total);
  $$('.apk-sprint-pf').forEach(b => b.setAttribute('aria-pressed', String(who.has(b.dataset.who))));
  $('.apk-sprint-epics').innerHTML = Object.keys(EPICS).map(k => '<button type="button" class="apk-sprint-epic-f" data-epic="' + k + '" aria-pressed="' + epic.has(k) + '" style="--h:' + EPICS[k][1] + '"><i></i>' + EPICS[k][0] + '<em>' + all.filter(id => data.items[id].epic === k).length + '</em></button>').join('');
  $$('.apk-sprint-seg [data-view]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.view === view)));
  if (view === 'table') renderTable();
  if (openId) renderDrawer();
}

function burndown(total) {
  const items = Object.values(data.items);
  const rem = d => total - items.reduce((s, it) => s + (it.doneDay != null && it.doneDay <= d ? it.pts : 0), 0);
  const X = d => 10 + d * 22, Y = v => 104 - v / total * 92;
  const pts = Array.from({ length: TODAY + 1 }, (_, d) => X(d) + ',' + Y(rem(d)).toFixed(1));
  const line = 'M' + pts.join('L');
  const area = line + 'L' + X(TODAY) + ',104L10,104Z';
  [['[data-line]', line], ['[data-area]', area]].forEach(([s, d]) => { const p = $(s); p.setAttribute('d', d); p.style.d = 'path("' + d + '")'; });
  $('[data-today]').style.translate = X(TODAY) + 'px ' + Y(rem(TODAY)).toFixed(1) + 'px';
  $('[data-today] line').setAttribute('y1', -Y(rem(TODAY)) + 8); $('[data-today] line').setAttribute('y2', 104 - Y(rem(TODAY)));
  const r = rem(TODAY), ideal = Math.round(total * (1 - TODAY / DAYS)), diff = r - ideal;
  $('[data-remaining]').textContent = r; $('[data-ideal]').textContent = ideal;
  const s = $('[data-burnstatus]');
  s.textContent = diff > 0 ? diff + ' pts behind' : diff < 0 ? -diff + ' pts ahead' : 'On the line';
  s.dataset.tone = diff > 0 ? 'warn' : 'ok';
}

function renderTable() {
  const ths = [['key', 'Key'], ['title', 'Title'], ['who', 'Assignee', 1], ['epic', 'Epic', 1], ['pts', 'Pts']];
  let h = '<table><thead><tr>' + ths.map(([k, t, s]) => '<th scope="col"' + (s ? ' class="apk-sprint-hide-s"' : '') + (k === 'pts' ? ' style="text-align:right"' : '') +
    ' aria-sort="' + (sort.k === k ? (sort.d > 0 ? 'ascending' : 'descending') : 'none') + '"><button type="button" data-sort="' + k + '">' + t + '</button></th>').join('') + '</tr></thead><tbody>';
  COLS.forEach(c => {
    let ids = data.cells[c.k].filter(visible);
    if (sort.k !== 'rank') ids = ids.slice().sort((a, b) => {
      const A = sort.k === 'key' ? a : sort.k === 'pts' ? data.items[a].pts : sort.k === 'who' ? PEOPLE[data.items[a].who][0] : sort.k === 'epic' ? EPICS[data.items[a].epic][0] : data.items[a].title;
      const B = sort.k === 'key' ? b : sort.k === 'pts' ? data.items[b].pts : sort.k === 'who' ? PEOPLE[data.items[b].who][0] : sort.k === 'epic' ? EPICS[data.items[b].epic][0] : data.items[b].title;
      return (A > B ? 1 : A < B ? -1 : 0) * sort.d;
    });
    h += '<tr class="apk-sprint-grp"><td colspan="5">' + c.t + '<span>' + ids.length + ' issues · ' + sum(ids) + ' pts</span></td></tr>';
    h += ids.map(id => { const it = data.items[id]; return '<tr tabindex="0" data-open="' + id + '" data-vt="' + id + '"><td class="apk-sprint-tk">' + id + '</td><td class="apk-sprint-tt">' + esc(it.title) + '</td><td class="apk-sprint-hide-s"><span class="apk-sprint-tw">' + avatar(it.who) + PEOPLE[it.who][0] + '</span></td><td class="apk-sprint-hide-s"><span class="apk-sprint-epic" style="--h:' + EPICS[it.epic][1] + '">' + EPICS[it.epic][0] + '</span></td><td class="apk-sprint-num">' + it.pts + '</td></tr>'; }).join('');
  });
  table.innerHTML = h + '</tbody></table>';
}

/* ── drawer ── */
function renderDrawer() {
  const id = openId, it = data.items[id]; if (!it) return;
  const sig = JSON.stringify([id, it, statusOf(id)]);
  if (sig === drawerSig) return;
  drawerSig = sig;
  const f = doc.activeElement && drawer.contains(doc.activeElement) ? doc.activeElement.dataset.f : null;
  const done = it.sub.filter(s => s[1]).length;
  const opt = (o, v) => Object.keys(o).map(k => '<option value="' + k + '"' + (k === v ? ' selected' : '') + '>' + (Array.isArray(o[k]) ? o[k][0] : o[k]) + '</option>').join('');
  drawer.innerHTML = '<header class="apk-sprint-dhead"><span class="apk-sprint-key">' + id + '</span>' + avatar(it.who) +
    '<button type="button" class="apk-sprint-x" data-act="close" aria-label="Close details"><kbd>Esc</kbd><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></header>' +
    '<div class="apk-sprint-dbody">' +
    '<textarea class="apk-sprint-dtitle" data-f="title" rows="2" aria-label="Title" style="--i:0">' + esc(it.title) + '</textarea>' +
    '<dl class="apk-sprint-props" style="--i:1">' +
    '<dt>Status</dt><dd><select data-f="status" aria-label="Status">' + COLS.map(c => '<option value="' + c.k + '"' + (c.k === statusOf(id) ? ' selected' : '') + '>' + c.t + '</option>').join('') + '</select></dd>' +
    '<dt>Assignee</dt><dd><select data-f="who" aria-label="Assignee">' + opt(PEOPLE, it.who) + '</select></dd>' +
    '<dt>Points</dt><dd class="apk-sprint-ptsseg" role="group" aria-label="Story points">' + [1, 2, 3, 5, 8].map(n => '<button type="button" data-f="pts' + n + '" data-pts="' + n + '" aria-pressed="' + (it.pts === n) + '">' + n + '</button>').join('') + '</dd>' +
    '<dt>Epic</dt><dd><select data-f="epic" aria-label="Epic">' + opt(EPICS, it.epic) + '</select></dd>' +
    '<dt>Priority</dt><dd><select data-f="prio" aria-label="Priority">' + opt(PRIO, it.prio) + '</select><button type="button" class="apk-sprint-blk" data-f="blk" data-act="block" aria-pressed="' + !!it.blocked + '">' + (it.blocked ? 'Blocked' : 'Mark blocked') + '</button></dd>' +
    '</dl>' +
    '<p class="apk-sprint-desc" style="--i:2">' + esc(it.desc) + '</p>' +
    '<section style="--i:3"><h3>Subtasks · ' + done + '/' + it.sub.length + '</h3>' + (it.sub.length ? '<div class="apk-sprint-meter" style="--p:' + (done / it.sub.length) + '"><i></i></div>' : '') +
    '<ul class="apk-sprint-checks">' + it.sub.map((s, i) => '<li><label><input type="checkbox" data-f="sub' + i + '" data-sub="' + i + '"' + (s[1] ? ' checked' : '') + '><span>' + esc(s[0]) + '</span></label></li>').join('') +
    '<li><input class="apk-sprint-addsub" data-f="addsub" placeholder="Add a subtask and press Enter" aria-label="Add subtask"></li></ul></section>' +
    '<section style="--i:4"><h3>Activity</h3><ul class="apk-sprint-log">' + it.log.slice().reverse().map(l => '<li><span>' + l[0] + '</span><time>' + l[1] + '</time></li>').join('') + '</ul></section>' +
    '</div>';
  if (f) { const el = drawer.querySelector('[data-f="' + f + '"]'); if (el) el.focus({ preventScroll: true }); }
}
function openDrawer(id) {
  const first = !openId; openId = id; drawerSig = ''; render();
  drawer.classList.add('is-open');
  if (first) { drawer.classList.add('is-entering'); setTimeout(() => drawer.classList.remove('is-entering'), 900); }
  $('.apk-sprint-dtitle', drawer).focus({ preventScroll: true });
}
function closeDrawer() {
  const id = openId; if (!id) return;
  openId = null; drawerSig = ''; drawer.classList.remove('is-open'); render();
  const n = K.els.get(id); if (n && n.isConnected) n.focus({ preventScroll: true }); else root.focus({ preventScroll: true });
}
const mutate = (fn) => K.apply(() => { const it = data.items[openId]; return fn(it, openId); });
drawer.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  if (b.dataset.act === 'close') return closeDrawer();
  if (b.dataset.pts) mutate((it, id) => { const n = +b.dataset.pts; if (it.pts === n) return false; it.log.push(['Estimate ' + it.pts + ' → ' + n + ' pts', 'Today']); it.pts = n; return id + ' re-estimated to ' + n + ' pts'; });
  if (b.dataset.act === 'block') mutate((it, id) => { it.blocked = !it.blocked; it.log.push([it.blocked ? 'Marked blocked' : 'Unblocked', 'Today']); return id + (it.blocked ? ' marked blocked' : ' unblocked'); });
});
drawer.addEventListener('change', e => {
  const t = e.target, f = t.dataset.f; if (!f) return;
  if (f === 'status') K.apply(() => move(openId, t.value, null));
  else if (f === 'who') mutate((it, id) => { it.who = t.value; it.log.push(['Assigned to ' + PEOPLE[t.value][0], 'Today']); return id + ' assigned to ' + PEOPLE[t.value][0]; });
  else if (f === 'epic') mutate((it, id) => { it.epic = t.value; return id + ' moved to epic ' + EPICS[t.value][0]; });
  else if (f === 'prio') mutate((it, id) => { it.prio = t.value; return id + ' priority ' + PRIO[t.value]; });
  else if (f === 'title') mutate((it, id) => { const v = t.value.trim(); if (!v || v === it.title) return false; it.title = v; it.log.push(['Renamed', 'Today']); return 'Renamed ' + id; });
  else if (t.dataset.sub) mutate((it, id) => { const s = it.sub[+t.dataset.sub]; s[1] = t.checked; return (s[1] ? 'Checked off “' : 'Reopened “') + s[0] + '”'; });
});
drawer.addEventListener('keydown', e => {
  const t = e.target;
  if (t.dataset.f === 'title' && e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); t.blur(); }
  if (t.dataset.f === 'addsub' && e.key === 'Enter' && t.value.trim()) { e.preventDefault(); const v = t.value.trim(); mutate((it) => { it.sub.push([v, false]); return 'Added subtask “' + v + '”'; }); const n = $('[data-f="addsub"]', drawer); if (n) n.focus(); }
});

/* ── moves: the one place status changes ── */
function move(id, key, beforeId) {
  const from = statusOf(id), arr = data.cells[from], oi = arr.indexOf(id);
  arr.splice(oi, 1);
  const to = data.cells[key];
  let ni = beforeId ? to.indexOf(beforeId) : to.length;
  if (ni < 0) ni = to.length;
  to.splice(ni, 0, id);
  if (from === key && ni === oi) return false;
  const it = data.items[id];
  if (key === 'done' && from !== 'done') it.doneDay = TODAY;
  if (key !== 'done') delete it.doneDay;
  if (from !== key) it.log.push(['Moved to <b>' + colName(key) + '</b>', 'Today']);
  const c = COLS.find(x => x.k === key);
  const over = from !== key && c.lim && to.length > c.lim;
  return from === key ? 'Reordered ' + id + ' in ' + colName(key) : id + ' → ' + colName(key) + (over ? ' · over WIP limit (' + to.length + '/' + c.lim + ')' : '');
}
const name = id => id + ' ' + data.items[id].title;
const where = id => { const k = statusOf(id), a = data.cells[k].filter(visible); return colName(k) + ', position ' + (a.indexOf(id) + 1) + ' of ' + a.length; };

/* ── composer ── */
const todoCol = colEl.todo.el, composer = $('.apk-sprint-composer', todoCol);
function compose(on) {
  todoCol.classList.toggle('is-composing', on);
  if (on) {
    board.scrollTo({ left: 0, behavior: RM.matches ? 'auto' : 'smooth' });
    if (view !== 'board') swapView('board');
    const t = $('[data-ct]', composer); t.value = ''; t.focus({ preventScroll: true });
  }
}
composer.addEventListener('keydown', e => {
  if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); compose(false); $('.apk-sprint-new').focus(); return; }
  if (e.key === 'Enter' && !e.shiftKey && e.target.matches('[data-ct]')) {
    e.preventDefault();
    const title = e.target.value.trim(); if (!title) return;
    K.apply(() => {
      const id = 'LDG-' + (++data.seq);
      data.items[id] = I(title, $('[data-ce]', composer).value, +$('[data-cp]', composer).value, $('[data-cw]', composer).value, 'med', 'No description yet.');
      data.items[id].log.push(['Created', 'Today']);
      data.cells.todo.unshift(id); fresh = id;
      setTimeout(() => { fresh = null; }, 900);
      return 'Created ' + id;
    });
    e.target.value = '';
  }
});
composer.addEventListener('submit', e => e.preventDefault());

/* ── view switch with a view transition: cards morph into table rows ── */
function names(on) {
  const set = (el, id) => { el.style.viewTransitionName = on ? 'apk-sprint-' + id.toLowerCase() : ''; };
  if (view === 'board') K.els.forEach((n, id) => { if (n.isConnected && n.offsetParent) set(n, id); });
  else $$('tr[data-vt]', table).forEach(r => set(r, r.dataset.vt));
}
function swapView(v) {
  if (v === view) return;
  const go = () => { view = v; render(); };
  if (!doc.startViewTransition || RM.matches) { go(); return; }
  names(true);
  const t = doc.startViewTransition(() => { names(false); go(); names(true); });
  t.finished.finally(() => names(false));
}

/* ── events ── */
root.addEventListener('click', e => {
  const t = e.target;
  const pf = t.closest('[data-who]'); if (pf) { who.has(pf.dataset.who) ? who.delete(pf.dataset.who) : who.add(pf.dataset.who); K.flip(render); return; }
  const ef = t.closest('[data-epic]'); if (ef) { epic.has(ef.dataset.epic) ? epic.delete(ef.dataset.epic) : epic.add(ef.dataset.epic); K.flip(render); return; }
  const vb = t.closest('[data-view]'); if (vb && vb.closest('.apk-sprint-seg')) { swapView(vb.dataset.view); return; }
  if (t.closest('[data-act="new"]')) { compose(true); return; }
  const sb = t.closest('[data-sort]'); if (sb) { const k = sb.dataset.sort; sort = sort.k === k ? (sort.d > 0 ? { k, d: -1 } : { k: 'rank', d: 1 }) : { k, d: k === 'pts' ? -1 : 1 }; renderTable(); $('[data-sort="' + k + '"]', table).focus(); return; }
  const row = t.closest('tr[data-open]'); if (row) { openDrawer(row.dataset.open); return; }
  const c = t.closest('.apk-sprint-card'); if (c && board.contains(c)) { openDrawer(c.dataset.id); return; }
});
$('[data-q]').addEventListener('input', e => { q = e.target.value.trim().toLowerCase(); K.flip(render); });
$('[data-q]').addEventListener('keydown', e => { if (e.key === 'Escape') { e.stopPropagation(); e.target.value = ''; q = ''; K.flip(render); root.focus(); } });
const K = boardKit({ get: () => data, set: d => { data = d; drawerSig = ''; }, render, move, name, where, open: openDrawer, keys, hscroll: () => board, short: id => id });
const syncTabs = K.pager(board, tabs);

function keys(e, typing) {
  if (e.key === 'Escape') { if (todoCol.classList.contains('is-composing')) return compose(false); if (openId) { e.preventDefault(); return closeDrawer(); } return; }
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key.toLowerCase();
  if (e.key === '/') { e.preventDefault(); $('[data-q]').focus(); }
  else if (k === 'c') { e.preventDefault(); compose(true); }
  else if (k === 'b') swapView('board');
  else if (k === 't') swapView('table');
  else if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && e.target.matches('tr[data-open]')) {
    e.preventDefault(); const rows = $$('tr[data-open]', table), i = rows.indexOf(e.target);
    const n = rows[i + (e.key === 'ArrowDown' ? 1 : -1)]; if (n) n.focus();
  } else if (e.key === 'Enter' && e.target.matches('tr[data-open]')) openDrawer(e.target.dataset.open);
}

root.classList.add('is-mounting');
render();
setTimeout(() => root.classList.remove('is-mounting'), 1400);

