.apk-swim {
  position: relative; width: 100%; height: var(--apk-swim-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate;
  -webkit-tap-highlight-color: transparent; box-sizing: border-box;
  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & .apk-swim-layer { position: absolute; inset: 0; z-index: 90; pointer-events: none; overflow: clip; }
  & .apk-swim-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .apk-swim-list { position: relative; }
  & .apk-swim-card {
    user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;
    touch-action: manipulation; cursor: grab;
    &.is-src { display: none; }
  }
  & .apk-swim-card.is-ghost {
    position: absolute; left: 0; top: 0; margin: 0; z-index: 2; cursor: grabbing;
    scale: 1.04; will-change: translate, rotate;
    transition: scale .3s var(--apk-swim-spring), box-shadow .3s ease-out, opacity .2s;
    @starting-style { scale: 1; }
    &.is-over-zone { scale: .9; opacity: .8; }
  }
  & .apk-swim-card.is-flyer { z-index: 1; }
  & .apk-swim-ph { transition: opacity .18s ease-out; @starting-style { opacity: 0; } }
  &.is-dragging, &.is-dragging * { cursor: grabbing; }
  & .apk-swim-toast {
    position: absolute; z-index: 95; left: 50%; bottom: 16px; translate: -50% 140%;
    display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
    opacity: 0; pointer-events: none;
    transition: translate .45s var(--apk-swim-spring), opacity .2s ease-out;
    & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
    & [data-undo] { display: none; flex: none; }
    &.has-undo [data-undo] { display: inline-flex; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }
}

@keyframes apk-swim-in { from { opacity: 0; translate: 0 8px; } }
@keyframes apk-swim-new { 0% { opacity: 0; scale: .9; box-shadow: 0 0 0 6px color-mix(in oklch, var(--apk-swim-accent) 30%, transparent); } 70% { opacity: 1; scale: 1.01; } }
@keyframes apk-swim-over { 50% { opacity: .55; } }

.apk-swim {
  --apk-swim-paper: oklch(0.972 0.009 85);
  --apk-swim-ink: oklch(0.25 0.02 265);
  --apk-swim-accent: oklch(0.52 0.19 263);
  --apk-swim-hot: oklch(0.6 0.2 30);
  --apk-swim-card: oklch(0.996 0.003 85);
  --apk-swim-line: color-mix(in oklch, var(--apk-swim-ink) 11%, transparent);
  --apk-swim-line2: color-mix(in oklch, var(--apk-swim-ink) 20%, transparent);
  --apk-swim-mute: color-mix(in oklch, var(--apk-swim-ink) 60%, var(--apk-swim-paper));
  --apk-swim-faint: color-mix(in oklch, var(--apk-swim-ink) 38%, var(--apk-swim-paper));
  --apk-swim-tint: color-mix(in oklch, var(--apk-swim-accent) 7%, var(--apk-swim-paper));
  --apk-swim-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  --apk-swim-lw: 210px;
  background: var(--apk-swim-paper); color: var(--apk-swim-ink); color-scheme: light; accent-color: var(--apk-swim-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif;
