    'ORL-248': it('Audit who changed a job’s price', 'feat', 'api', null, 'ready', 'normal', 3, 'Record the user and the old and new price on every change.'),
    'ORL-227': it('Dark mode for the job sheet', 'feat', 'android', 'felix', 'ready', 'low', 2, 'Night shifts asked for it. Reuse the tokens from the iOS implementation.'),
    'ORL-243': it('Translate the job checklist into Spanish', 'chore', 'web', null, 'ready', 'low', 2, 'Strings are already extracted. Needs translation and a review pass.'),
    'ORL-240': it('Webhook retries with exponential backoff', 'chore', 'api', 'rafa', 'ship', 'normal', 3, 'Shipped in 3.1.4.'),
    'ORL-241': it('Job timer survives app restarts', 'feat', 'ios', 'hana', 'ship', 'high', 3, 'Shipped in 3.1.4.'),
    'ORL-244': it('Android 15 edge-to-edge insets', 'chore', 'android', 'felix', 'ship', 'normal', 2, 'Shipped in 3.1.4.'),
    'ORL-246': it('Keyboard shortcuts on the dispatch board', 'feat', 'web', 'odile', 'ship', 'low', 2, 'Shipped in 3.1.4.')
