};
data.order = Object.keys(data.items);

let group = 'who', q = '', types = new Set(), folded = new Set(), peekId = null, fresh = null, col = 0, dwell = null;
const grid = $('.apk-swim-grid'), scroller = $('.apk-swim-scroll'), peek = $('.apk-swim-peek'), tabs = $('.apk-swim-tabs');
const FIELD = { who: 'who', prio: 'prio', plat: 'plat' };
const NONE = '_none';
function lanes() {
  if (group === 'who') return Object.keys(PEOPLE).map(k => ({ v: k, name: PEOPLE[k][0], sub: PEOPLE[k][1], hue: PEOPLE[k][2] })).concat([{ v: NONE, name: 'Unassigned', sub: 'Needs an owner' }]);
  if (group === 'prio') return Object.keys(PRIOS).map(k => ({ v: k, name: PRIOS[k], icon: PRIOICON[k] }));
  return Object.keys(PLATS).map(k => ({ v: k, name: PLATS[k], icon: PICON[k] }));
}
const laneOf = id => { const v = data.items[id][FIELD[group]]; return v == null ? NONE : v; };
const initials = n => n.split(' ').map(s => s[0]).join('');
const sum = ids => ids.reduce((s, id) => s + data.items[id].pts, 0);
function visible(id) {
  const x = data.items[id];
  if (types.size && !types.has(x.type)) return false;
  if (q) { const s = (id + ' ' + x.title + ' ' + (x.who ? PEOPLE[x.who][0] : 'unassigned') + ' ' + PLATS[x.plat]).toLowerCase(); if (!q.split(/\s+/).every(w => s.includes(w))) return false; }
  return true;
}
$('.apk-swim-types').innerHTML = Object.keys(TYPES).map(k => '<button type="button" class="apk-swim-chip" data-type="' + k + '" aria-pressed="false" style="--c:' + TYPES[k][1] + '"><i></i>' + TYPES[k][0] + '</button>').join('');
tabs.innerHTML = ST.map((s, i) => '<button type="button" role="tab" data-ci="' + i + '" aria-selected="' + (i === 0) + '">' + s[1] + '<span></span></button>').join('');

let built = '';
function build() {
  const L = lanes(), key = group;
  if (key === built) return;
  built = key;
  grid.innerHTML = '<div class="apk-swim-head"><div class="apk-swim-corner">' + { who: 'Assignee', prio: 'Priority', plat: 'Platform' }[group] + '</div>' +
    ST.map(s => '<div class="apk-swim-colh" data-s="' + s[0] + '">' + s[1] + '<span></span></div>').join('') + '</div>' +
    L.map((l, r) => '<section class="apk-swim-lane" data-lane="' + l.v + '"' + (l.v === NONE ? ' data-none' : '') + ' style="--i:' + r + '" aria-label="' + l.name + '">' +
      '<header class="apk-swim-lanehead"><span class="apk-swim-lane-mark" style="' + (l.hue != null ? 'background:oklch(0.88 0.06 ' + l.hue + ');color:oklch(0.32 0.08 ' + l.hue + ')' : 'background:color-mix(in oklch, var(--apk-swim-ink) 7%, transparent)') + '">' + (l.icon || (l.v === NONE ? '?' : initials(l.name))) + '</span>' +
      '<span class="apk-swim-lname">' + l.name + '</span><button type="button" class="apk-swim-fold" data-fold="' + l.v + '" aria-expanded="' + !folded.has(group + l.v) + '" aria-label="Collapse ' + l.name + '"><svg viewBox="0 0 24 24"><path d="m6 9 6 6 6-6"/></svg></button>' +
      '<span class="apk-swim-lsub"></span>' + (group === 'who' && l.v !== NONE ? '<div class="apk-swim-cap"><i></i></div>' : '') + '</header>' +
      ST.map((s, c) => '<div class="apk-swim-col" data-c="' + c + '"><div class="apk-swim-list" role="list" aria-label="' + l.name + ', ' + s[1] + '" data-key="' + l.v + '|' + s[0] + '" data-row="' + r + '" data-col="' + c + '"></div>' +
        '<span class="apk-swim-count"></span><button type="button" class="apk-swim-add" data-add="' + l.v + '|' + s[0] + '" aria-label="Add to ' + l.name + ', ' + s[1] + '"><svg viewBox="0 0 24 24"><path d="M12 6v12M6 12h12"/></svg>Add</button></div>').join('') +
      '</section>').join('');
}

function cardNode(id) {
  const x = data.items[id];
  const pips = Array.from({ length: 5 }, (_, i) => '<i class="' + (i < x.pts ? 'on' : '') + '"></i>').join('');
  const html = '<div class="apk-swim-c-row"><span class="apk-swim-key">' + id + '</span><span class="apk-swim-type" style="--c:' + TYPES[x.type][1] + '">' + TYPES[x.type][0] + '</span>' +
    (group !== 'plat' ? '<span class="apk-swim-plat" title="' + PLATS[x.plat] + '">' + PICON[x.plat] + '</span>' : '') + '</div>' +
    '<p class="apk-swim-c-title">' + esc(x.title) + '</p>' +
    '<div class="apk-swim-c-foot"><span class="apk-swim-pips" title="' + x.pts + ' points">' + pips + '</span>' +
    (group !== 'prio' ? '<span class="apk-swim-pr" data-p="' + x.prio + '">' + PRIOS[x.prio] + '</span>' : '') +
    (group !== 'who' ? (x.who ? '<span class="apk-swim-av" style="background:oklch(0.88 0.06 ' + PEOPLE[x.who][2] + ');color:oklch(0.32 0.08 ' + PEOPLE[x.who][2] + ')" title="' + PEOPLE[x.who][0] + '">' + initials(PEOPLE[x.who][0]) + '</span>' : '<span class="apk-swim-av is-none" title="Unassigned"></span>') : '') + '</div>';
  const n = K.card(id, (fresh === id ? 'is-new' : '') + (peekId === id ? ' is-open' : ''), html,
    id + ', ' + x.title + ', ' + TYPES[x.type][0] + ', ' + x.pts + ' points, ' + (x.who ? PEOPLE[x.who][0] : 'unassigned') + ', ' + ST.find(s => s[0] === x.status)[1]);
  n.dataset.p = x.prio;
