}

function render() {
  build();
  root.dataset.c = col;
  $$('.apk-swim-group [data-g]').forEach(b => b.setAttribute('aria-checked', String(b.dataset.g === group)));
  $$('.apk-swim-chip').forEach(b => b.setAttribute('aria-pressed', String(types.has(b.dataset.type))));
  const vis = data.order.filter(visible);
  $$('.apk-swim-lane').forEach(lane => {
    const lv = lane.dataset.lane, collapsed = folded.has(group + lv);
    lane.classList.toggle('is-collapsed', collapsed);
    $('.apk-swim-fold', lane).setAttribute('aria-expanded', String(!collapsed));
    ST.forEach((s, c) => {
      const all = data.order.filter(id => laneOf(id) === lv && data.items[id].status === s[0]);
      const ids = vis.filter(id => laneOf(id) === lv && data.items[id].status === s[0]);
      const list = $('.apk-swim-list[data-key="' + lv + '|' + s[0] + '"]', lane);
      K.place(list, collapsed ? [] : ids.map(cardNode));
      $('.apk-swim-col[data-c="' + c + '"] .apk-swim-count', lane).innerHTML = all.length ? '<b>' + all.length + '</b>' + (all.length === 1 ? 'issue' : 'issues') + ' · ' + sum(all) + ' pts' : '—';
    });
    const mine = data.order.filter(id => laneOf(id) === lv);
    const active = sum(mine.filter(id => data.items[id].status === 'doing' || data.items[id].status === 'test'));
    $('.apk-swim-lsub', lane).textContent = group === 'who' && lv !== NONE ? active + ' / ' + CAP + ' pts in flight' : mine.length + ' issues · ' + sum(mine) + ' pts';
    const cap = $('.apk-swim-cap', lane);
    if (cap) { cap.style.setProperty('--f', active / CAP); cap.dataset.state = active > CAP ? 'over' : active === CAP ? 'full' : 'ok'; cap.title = active + ' of ' + CAP + ' points in progress'; }
  });
  ST.forEach((s, i) => {
    const ids = data.order.filter(id => data.items[id].status === s[0]);
    const h = $('.apk-swim-colh[data-s="' + s[0] + '"] span'); if (h) h.textContent = ids.length + ' · ' + sum(ids) + ' pts';
    $('[data-ci="' + i + '"] span', tabs).textContent = ids.length;
    $('[data-ci="' + i + '"]', tabs).setAttribute('aria-selected', String(i === col));
  });
  const all = data.order;
  $('[data-meta]').textContent = 'Oriel field app · ships Oct 21 · ' + all.length + ' issues · ' + sum(all.filter(id => data.items[id].status === 'ship')) + ' of ' + sum(all) + ' pts shipped';
  if (peekId) renderPeek();
}

/* ── moves change the grouping field and the status, and keep one global rank ── */
function move(id, key, beforeId) {
  const [lv, s] = key.split('|'), x = data.items[id];
  const before = JSON.stringify([x, data.order]);
  const f = FIELD[group];
  x[f] = lv === NONE ? null : lv; x.status = s;
  data.order.splice(data.order.indexOf(id), 1);
  if (beforeId) data.order.splice(data.order.indexOf(beforeId), 0, id);
  else {
    const cell = data.order.filter(o => laneOf(o) === lv && data.items[o].status === s);
    const last = cell[cell.length - 1];
    data.order.splice(last ? data.order.indexOf(last) + 1 : data.order.length, 0, id);
  }
  if (JSON.stringify([x, data.order]) === before) return false;
  const ln = lanes().find(l => l.v === lv).name, sn = ST.find(t => t[0] === s)[1];
  return id + ' → ' + ln + ' · ' + sn;
}
const name = id => id + ' ' + data.items[id].title;
const where = id => { const x = data.items[id], lv = laneOf(id); const cell = data.order.filter(o => visible(o) && laneOf(o) === lv && data.items[o].status === x.status); return lanes().find(l => l.v === lv).name + ' lane, ' + ST.find(t => t[0] === x.status)[1] + ', position ' + (cell.indexOf(id) + 1) + ' of ' + cell.length; };

/* ── regroup: every card gets a view-transition-name, so it flies to its new lane ── */
function regroup(g) {
  if (g === group) return;
  const go = () => { group = g; render(); };
  if (!doc.startViewTransition || RM.matches) { K.flip(go); return; }
  const tag = on => K.els.forEach((n, id) => { n.style.viewTransitionName = on && n.isConnected && n.offsetParent ? 'apk-swim-' + id.toLowerCase() : ''; });
  tag(true);
  const t = doc.startViewTransition(() => { go(); tag(true); });
  t.finished.finally(() => tag(false));
}

/* ── peek ── */
let peekSig = '';
function renderPeek() {
  const x = data.items[peekId]; if (!x) return;
  const sig = JSON.stringify([peekId, x]); if (sig === peekSig) return; peekSig = sig;
  const sel = (f, o, v, allowNone) => '<select data-f="' + f + '" aria-label="' + f + '">' + (allowNone ? '<option value="">Unassigned</option>' : '') + Object.keys(o).map(k => '<option value="' + k + '"' + (k === v ? ' selected' : '') + '>' + (Array.isArray(o[k]) ? o[k][0] : o[k]) + '</option>').join('') + '</select>';
  const focused = doc.activeElement && peek.contains(doc.activeElement) ? doc.activeElement.dataset.f : null;
  peek.innerHTML = '<div class="apk-swim-ph-head"><span class="apk-swim-key">' + peekId + '</span><span class="apk-swim-type" style="--c:' + TYPES[x.type][1] + '">' + TYPES[x.type][0] + '</span>' +
    '<button type="button" class="apk-swim-x" data-close aria-label="Close"><kbd>Esc</kbd><svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div>' +
    '<div class="apk-swim-pbody"><h3>' + esc(x.title) + '</h3><p>' + esc(x.desc) + '</p>' +
    '<dl class="apk-swim-fields"><dt>Status</dt><dd>' + sel('status', Object.fromEntries(ST), x.status) + '</dd>' +
    '<dt>Assignee</dt><dd>' + sel('who', PEOPLE, x.who || '', true) + '</dd>' +
    '<dt>Priority</dt><dd>' + sel('prio', PRIOS, x.prio) + '</dd>' +
    '<dt>Platform</dt><dd>' + sel('plat', PLATS, x.plat) + '</dd>' +
    '<dt>Estimate</dt><dd>' + sel('pts', { 1: '1 point', 2: '2 points', 3: '3 points', 5: '5 points' }, String(x.pts)) + '</dd></dl></div>';
