}
function openPeek(id) { peekId = id; peekSig = ''; render(); peek.classList.add('is-open'); const f = $('select', peek); if (f) f.focus({ preventScroll: true }); }
function closePeek() { const id = peekId; if (!id) return; peekId = null; peek.classList.remove('is-open'); render(); const n = K.els.get(id); if (n && n.isConnected) n.focus({ preventScroll: true }); else root.focus(); }
peek.addEventListener('click', e => { if (e.target.closest('[data-close]')) closePeek(); });
peek.addEventListener('change', e => {
  const f = e.target.dataset.f, v = e.target.value; if (!f) return;
  K.apply(() => {
    const x = data.items[peekId];
    if (f === 'pts') x.pts = +v; else if (f === 'who') x.who = v || null; else x[f] = v;
    const label = { status: () => ST.find(s => s[0] === v)[1], who: () => v ? PEOPLE[v][0] : 'Unassigned', prio: () => PRIOS[v], plat: () => PLATS[v], pts: () => v + ' pts' }[f]();
