/* ── compose in any cell ── */
function compose(key) {
  const [lv, s] = key.split('|');
  if (folded.has(group + lv)) { folded.delete(group + lv); render(); }
  $$('.apk-swim-composer').forEach(c => c.remove());
  const list = $('.apk-swim-list[data-key="' + key + '"]'); if (!list) return;
  col = ST.findIndex(t => t[0] === s); render();
  const f = doc.createElement('div'); f.className = 'apk-swim-composer';
  f.innerHTML = '<textarea rows="2" placeholder="What needs doing?" aria-label="New issue title"></textarea><small>Enter to add · Esc to cancel</small>';
  list.parentNode.insertBefore(f, list);
  const t = $('textarea', f); t.focus({ preventScroll: true }); K.reveal(f);
  t.addEventListener('keydown', e => {
    if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); f.remove(); root.focus(); }
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault(); const title = t.value.trim(); if (!title) return;
      K.apply(() => {
        const id = 'ORL-' + (++data.seq);
        const x = data.items[id] = it(title, 'feat', group === 'plat' && lv !== NONE ? lv : 'web', null, s, group === 'prio' && lv !== NONE ? lv : 'normal', 2, 'Added from the board.');
        if (group === 'who') x.who = lv === NONE ? null : lv;
        data.order.unshift(id); fresh = id; setTimeout(() => { fresh = null; }, 900);
        return 'Created ' + id;
