/* ── events ── */
function setCol(i) { col = i; root.dataset.c = i; $$('[role="tab"]', tabs).forEach((b, j) => b.setAttribute('aria-selected', String(j === i))); }
root.addEventListener('click', e => {
  const t = e.target;
  const g = t.closest('[data-g]'); if (g) return regroup(g.dataset.g);
  const ty = t.closest('[data-type]'); if (ty) { types.has(ty.dataset.type) ? types.delete(ty.dataset.type) : types.add(ty.dataset.type); return K.flip(render); }
  const fo = t.closest('[data-fold]'); if (fo) { const k = group + fo.dataset.fold; folded.has(k) ? folded.delete(k) : folded.add(k); K.flip(render); const b = $('[data-fold="' + fo.dataset.fold + '"]'); if (b) b.focus({ preventScroll: true }); return; }
  if (t.closest('[data-act="collapse"]')) { const ls = lanes(), all = ls.every(l => folded.has(group + l.v)); ls.forEach(l => all ? folded.delete(group + l.v) : folded.add(group + l.v)); $('[data-act="collapse"]').setAttribute('aria-pressed', String(!all)); $('[data-act="collapse"] span').textContent = all ? 'Collapse lanes' : 'Expand lanes'; return K.flip(render); }
  const ad = t.closest('[data-add]'); if (ad) return compose(ad.dataset.add);
  const tb = t.closest('[data-ci]'); if (tb) return setCol(+tb.dataset.ci);
  const c = t.closest('.apk-swim-card'); if (c && grid.contains(c)) return openPeek(c.dataset.id);
});
$('.apk-swim-group').addEventListener('keydown', e => {
  if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
  e.preventDefault(); e.stopPropagation();
  const gs = ['who', 'prio', 'plat'], i = (gs.indexOf(group) + (e.key === 'ArrowRight' ? 1 : 2)) % 3;
  regroup(gs[i]); $('[data-g="' + gs[i] + '"]').focus();
});
tabs.addEventListener('keydown', e => {
  if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
  e.preventDefault(); e.stopPropagation(); const i = (col + (e.key === 'ArrowRight' ? 1 : 3)) % 4; setCol(i); $('[data-ci="' + i + '"]', tabs).focus();
});
$('[data-q]').addEventListener('input', e => { q = e.target.value.trim().toLowerCase(); K.flip(render); });
$('[data-q]').addEventListener('keydown', e => { if (e.key === 'Escape') { e.stopPropagation(); e.target.value = ''; q = ''; K.flip(render); root.focus(); } });
function keys(e, typing) {
  if (e.key === 'Escape' && peekId) { e.preventDefault(); return closePeek(); }
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key.toLowerCase();
  if (k === 'g') { const gs = ['who', 'prio', 'plat']; regroup(gs[(gs.indexOf(group) + 1) % 3]); }
  else if (e.key === '/') { e.preventDefault(); $('[data-q]').focus(); }
  else if (k === 'n') { e.preventDefault(); const c = e.target.closest && e.target.closest('.apk-swim-card'); compose(c ? c.closest('.apk-swim-list').dataset.key : lanes()[0].v + '|' + ST[col][0]); }
}

const K = boardKit({
  get: () => data, set: d => { data = d; peekSig = ''; }, render, move, name, where, open: openPeek, keys, short: id => id,
  hscroll: () => scroller,
  show: l => { if (!l) return; const c = +l.dataset.col; if (c !== col && $('.apk-swim-tabs').offsetParent) setCol(c); },
  hover: (hit) => {
    const tb = hit && hit.closest('[data-ci]');
    if (!tb) { if (dwell) { clearTimeout(dwell.t); dwell.b.classList.remove('is-dwell'); dwell = null; } return; }
    if (dwell && dwell.b === tb) return;
    if (dwell) { clearTimeout(dwell.t); dwell.b.classList.remove('is-dwell'); }
    tb.classList.add('is-dwell');
    dwell = { b: tb, t: setTimeout(() => { setCol(+tb.dataset.ci); tb.classList.remove('is-dwell'); }, 420) };
  },
  dragEnd: () => { if (dwell) { clearTimeout(dwell.t); dwell.b.classList.remove('is-dwell'); dwell = null; } }
});
render();

css:
.apk-press {
  position: relative; width: 100%; height: var(--apk-press-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate;
  -webkit-tap-highlight-color: transparent; box-sizing: border-box;
  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & .apk-press-layer { position: absolute; inset: 0; z-index: 90; pointer-events: none; overflow: clip; }
  & .apk-press-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .apk-press-list { position: relative; }
  & .apk-press-card {
    user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;
    touch-action: manipulation; cursor: grab;
    &.is-src { display: none; }
  }
  & .apk-press-card.is-ghost {
    position: absolute; left: 0; top: 0; margin: 0; z-index: 2; cursor: grabbing;
    scale: 1.04; will-change: translate, rotate;
    transition: scale .3s var(--apk-press-spring), box-shadow .3s ease-out, opacity .2s;
    @starting-style { scale: 1; }
    &.is-over-zone { scale: .9; opacity: .8; }
  }
  & .apk-press-card.is-flyer { z-index: 1; }
  & .apk-press-ph { transition: opacity .18s ease-out; @starting-style { opacity: 0; } }
  &.is-dragging, &.is-dragging * { cursor: grabbing; }
  & .apk-press-toast {
    position: absolute; z-index: 95; left: 50%; bottom: 16px; translate: -50% 140%;
    display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
    opacity: 0; pointer-events: none;
    transition: translate .45s var(--apk-press-spring), opacity .2s ease-out;
    & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
    & [data-undo] { display: none; flex: none; }
    &.has-undo [data-undo] { display: inline-flex; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }
}

@property --apk-press-p { syntax: '<number>'; inherits: false; initial-value: 0; }
@keyframes apk-press-rise { from { opacity: 0; translate: 0 12px; } }
@keyframes apk-press-ink { from { clip-path: inset(0 100% 0 0); } }

.apk-press {
  --apk-press-paper: oklch(0.975 0.012 92);
  --apk-press-ink: oklch(0.22 0.015 60);
  --apk-press-accent: oklch(0.6 0.2 35);
  --apk-press-gold: oklch(0.8 0.14 80);
  --apk-press-card: oklch(0.993 0.006 92);
  --apk-press-line: color-mix(in oklch, var(--apk-press-ink) 12%, transparent);
  --apk-press-line2: color-mix(in oklch, var(--apk-press-ink) 22%, transparent);
  --apk-press-mute: color-mix(in oklch, var(--apk-press-ink) 58%, var(--apk-press-paper));
  --apk-press-faint: color-mix(in oklch, var(--apk-press-ink) 36%, var(--apk-press-paper));
  --apk-press-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --apk-press-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  background: var(--apk-press-paper); color: var(--apk-press-ink); color-scheme: light; accent-color: var(--apk-press-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif; border-radius: 6px;
  box-shadow: 0 0 0 1px var(--apk-press-line);

  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; border: 1px solid var(--apk-press-line2); border-radius: 3px; color: var(--apk-press-mute); margin-left: 6px; }
  & :focus-visible { outline: 2px solid var(--apk-press-accent); outline-offset: 2px; }
  & h3 { margin: 0; font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }

  & .apk-press-app { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); grid-template-columns: minmax(0, 1fr); }
  & .apk-press-mast {
    display: grid; grid-template-columns: auto 1fr; grid-template-areas: "name stats" "ctrl ctrl"; gap: 12px 24px;
    padding: 16px 20px 12px; border-bottom: 3px double var(--apk-press-line2);
  }
  & .apk-press-name { grid-area: name;
    & h2 { margin: 0; font: 700 clamp(22px, 1.6cqi + 10px, 30px)/1 var(--apk-press-serif); letter-spacing: -.02em; text-wrap: balance; animation: apk-press-ink .9s cubic-bezier(.7,0,.2,1) both; }
    & p { margin: 5px 0 0; font-size: 11px; letter-spacing: .1em; text-transform: uppercase; color: var(--apk-press-mute); }
  }
  & .apk-press-stats {
    grid-area: stats; justify-self: end; display: flex; gap: 0; margin: 0; align-self: center;
    & div { padding: 0 18px; border-left: 1px solid var(--apk-press-line); }
    & dt { font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--apk-press-mute); }
    & dd { margin: 3px 0 0; font: 600 20px/1 var(--apk-press-serif); font-variant-numeric: tabular-nums lining-nums; }
    & dd small { font: 500 11px system-ui; color: var(--apk-press-mute); margin-left: 3px; }
  }
  & .apk-press-ctrl { grid-area: ctrl; display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }
  & .apk-press-desks { display: flex; gap: 2px; flex-wrap: wrap; margin-right: auto; }
  & .apk-press-desk {
    border: 0; background: none; padding: 5px 9px; border-radius: 20px; font-size: 12px; font-weight: 600; color: var(--apk-press-mute);
    display: inline-flex; align-items: center; gap: 6px; transition: background .2s, color .2s;
    & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
    &:hover { background: color-mix(in oklch, var(--apk-press-ink) 6%, transparent); }
    &[aria-pressed="true"] { background: color-mix(in oklch, var(--c) 18%, var(--apk-press-paper)); color: var(--apk-press-ink); }
  }
  & .apk-press-search {
    display: flex; align-items: center; gap: 6px; border-bottom: 1px solid var(--apk-press-line2); padding: 4px 2px;
    & svg { width: 14px; height: 14px; fill: none; stroke: var(--apk-press-mute); stroke-width: 2.2; stroke-linecap: round; }
    & input { border: 0; outline: 0; background: none; width: 140px; min-width: 0; font-family: var(--apk-press-serif); font-size: 14px; font-style: italic; }
    &:focus-within { border-bottom-color: var(--apk-press-accent); }
  }
  & .apk-press-views {
    display: flex; border: 1px solid var(--apk-press-line2); border-radius: 6px; overflow: hidden;
    & button { display: inline-flex; align-items: center; gap: 6px; border: 0; background: none; padding: 6px 10px; font-size: 12px; font-weight: 600; color: var(--apk-press-mute); transition: background .2s, color .2s; }
    & button + button { border-left: 1px solid var(--apk-press-line2); }
    & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
    & [aria-selected="true"] { background: var(--apk-press-ink); color: var(--apk-press-paper); }
    & [aria-selected="true"] kbd { color: inherit; border-color: color-mix(in oklch, var(--apk-press-paper) 40%, transparent); }
  }
  & .apk-press-pitch { border: 0; border-radius: 6px; background: var(--apk-press-accent); color: oklch(0.99 0.01 35); font-weight: 700; padding: 7px 12px; font-size: 12.5px; transition: scale .2s var(--apk-press-spring); }
  & .apk-press-pitch kbd { color: inherit; border-color: color-mix(in oklch, white 45%, transparent); }
  & .apk-press-pitch:active { scale: .96; }
  & .apk-press-tabs { display: none; }

  & .apk-press-main { min-height: 0; position: relative; }
  & .apk-press-board { height: 100%; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(196px, 1fr); overflow-x: auto; scrollbar-width: thin; }
  & .apk-press-cal { display: none; height: 100%; grid-template-columns: 250px minmax(0, 1fr); }
  &[data-view="cal"] .apk-press-board { display: none; }
  &[data-view="cal"] .apk-press-cal { display: grid; }

  & .apk-press-stage { display: flex; flex-direction: column; min-height: 0; border-right: 1px solid var(--apk-press-line); }
  & .apk-press-stage:last-child { border-right: 0; }
  & .apk-press-stage > header {
    padding: 14px 14px 10px; display: flex; align-items: baseline; gap: 8px;
    & h3 { flex: 1; }
    & span { font: 600 18px/1 var(--apk-press-serif); font-variant-numeric: tabular-nums; color: var(--apk-press-faint); }
  }
  & .apk-press-stage > header::after { content: ""; position: absolute; }
  & .apk-press-stage[data-k="pub"] h3 { color: var(--apk-press-accent); }
  & .apk-press-stage .apk-press-list { flex: 1; min-height: 0; overflow-y: auto; padding: 2px 12px 14px; display: flex; flex-direction: column; gap: 10px; scrollbar-width: thin; }
  &.is-dragging .apk-press-stage:has(.apk-press-ph) { background: color-mix(in oklch, var(--apk-press-gold) 9%, transparent); }

  /* ── story cards ── */
  & .apk-press-card {
    position: relative; display: grid; gap: 8px; padding: 12px 12px 11px; background: var(--apk-press-card);
    border: 1px solid var(--apk-press-line); border-radius: 4px;
    box-shadow: 0 1px 0 var(--apk-press-line), 0 2px 0 -1px var(--apk-press-card), 0 3px 0 -1px var(--apk-press-line);
    transition: border-color .15s, translate .25s var(--apk-press-spring), box-shadow .2s;
    &:hover { border-color: var(--apk-press-line2); translate: 0 -2px; box-shadow: 0 1px 0 var(--apk-press-line), 0 10px 22px -14px color-mix(in oklch, var(--apk-press-ink) 50%, transparent); }
    &.is-open { border-color: var(--apk-press-ink); }
    &.is-new { animation: apk-press-rise .7s var(--apk-press-spring) both; }
    &.is-lifted { outline: 2px solid var(--apk-press-accent); outline-offset: 3px; translate: 0 -3px; }
    &.is-ghost { box-shadow: 0 28px 40px -20px color-mix(in oklch, var(--apk-press-ink) 55%, transparent), 0 0 0 1px var(--apk-press-ink); border-color: var(--apk-press-ink); }
    &.is-ghost.is-landing { box-shadow: none; }
  }
  &.is-mounting .apk-press-card { animation: apk-press-rise .6s var(--apk-press-spring) both; animation-delay: calc(var(--i, 0) * 30ms + 150ms); }
  & .apk-press-ph { border: 1.5px dashed var(--apk-press-accent); border-radius: 4px; background: color-mix(in oklch, var(--apk-press-accent) 6%, transparent); }
  & .apk-press-c-top { display: flex; align-items: center; gap: 6px; font-size: 10px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
  & .apk-press-dk { color: var(--c); display: inline-flex; align-items: center; gap: 5px; }
  & .apk-press-dk::before { content: ""; width: 6px; height: 6px; background: var(--c); border-radius: 1px; rotate: 45deg; }
  & .apk-press-fmt { color: var(--apk-press-faint); }
  & .apk-press-hl { margin: 0; font: 600 15px/1.25 var(--apk-press-serif); letter-spacing: -.005em; text-wrap: balance; }
  & .apk-press-c-foot { display: flex; align-items: center; gap: 8px; font-size: 11.5px; color: var(--apk-press-mute); }
  & .apk-press-by { font-style: italic; font-family: var(--apk-press-serif); font-size: 13px; color: var(--apk-press-mute); min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; margin-top: -4px; }
  & .apk-press-c-foot .apk-press-by { margin-top: 0; flex: 1; }
  & .apk-press-ring {
    --apk-press-p: var(--w, 0); margin-left: auto; flex: none; width: 22px; height: 22px; border-radius: 50%; position: relative;
    background: conic-gradient(var(--apk-press-ink) calc(var(--apk-press-p) * 1turn), color-mix(in oklch, var(--apk-press-ink) 12%, transparent) 0);
    transition: --apk-press-p 1.1s cubic-bezier(.3,.7,.2,1);
    @starting-style { --apk-press-p: 0; }
    &::after { content: ""; position: absolute; inset: 3px; border-radius: 50%; background: var(--apk-press-card); }
    &.is-full { background: conic-gradient(var(--apk-press-accent) 1turn, transparent 0); }
  }
  & .apk-press-c-foot .apk-press-wc { margin-left: auto; }
  & .apk-press-c-foot .apk-press-ring { margin-left: 0; }
  & .apk-press-wc { font: 600 11px ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--apk-press-mute); }
  & .apk-press-date { font-size: 11px; font-weight: 650; color: var(--apk-press-accent); }
  & .apk-press-checks { display: flex; gap: 3px; }
  & .apk-press-checks i { width: 14px; height: 3px; border-radius: 2px; background: color-mix(in oklch, var(--apk-press-ink) 14%, transparent); }
  & .apk-press-checks i.on { background: var(--apk-press-ink); }
  /* compact chip in the calendar */
  & .apk-press-card.is-chip { padding: 7px 8px; gap: 4px; border-left: 3px solid var(--c); border-radius: 3px; box-shadow: none; }
  & .apk-press-card.is-chip .apk-press-hl { font-size: 12.5px; line-height: 1.22; }
  & .apk-press-card.is-chip.is-pub { background: transparent; border-color: var(--apk-press-line); border-left-color: var(--c); cursor: default; }
  & .apk-press-card.is-chip.is-pub .apk-press-hl { color: var(--apk-press-mute); }

  /* ── calendar ── */
  & .apk-press-tray {
    display: flex; flex-direction: column; min-height: 0; border-right: 1px solid var(--apk-press-line);
    background: color-mix(in oklch, var(--apk-press-ink) 3%, var(--apk-press-paper));
    & header { padding: 14px 14px 8px; }
    & header p { margin: 3px 0 0; font: italic 13px var(--apk-press-serif); color: var(--apk-press-mute); }
    & .apk-press-list { flex: 1; min-height: 0; overflow-y: auto; padding: 4px 12px 14px; display: flex; flex-direction: column; gap: 10px; }
    & .apk-press-list:empty::after { content: "Nothing waiting. Move a story to Editing."; font: italic 13px var(--apk-press-serif); color: var(--apk-press-faint); padding: 8px 2px; }
  }
  & .apk-press-weeks { min-height: 0; overflow: auto; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)) repeat(2, minmax(0, .62fr)); grid-auto-rows: minmax(0, 1fr); scrollbar-width: thin; }
  & .apk-press-dow { display: contents; }
  & .apk-press-day {
    position: relative; display: flex; flex-direction: column; min-height: 140px; border-right: 1px solid var(--apk-press-line); border-bottom: 1px solid var(--apk-press-line); padding: 8px 7px; gap: 6px;
    transition: background .2s;
    & .apk-press-dn { display: flex; align-items: baseline; gap: 6px; font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--apk-press-mute); }
    & .apk-press-dn b { font: 600 17px/1 var(--apk-press-serif); letter-spacing: 0; color: var(--apk-press-ink); font-variant-numeric: tabular-nums lining-nums; }
    & .apk-press-list { flex: 1; display: flex; flex-direction: column; gap: 5px; min-height: 30px; }
  }
  & .apk-press-day:nth-child(7n) { border-right: 0; }
  & .apk-press-day.is-past { background: repeating-linear-gradient(135deg, transparent 0 7px, color-mix(in oklch, var(--apk-press-ink) 3.5%, transparent) 7px 8px); }
  & .apk-press-day.is-past .apk-press-dn b { color: var(--apk-press-faint); }
  & .apk-press-day.is-today { box-shadow: inset 0 3px var(--apk-press-accent); }
  & .apk-press-day.is-today .apk-press-dn { color: var(--apk-press-accent); }
  & .apk-press-day.is-wknd { background-color: color-mix(in oklch, var(--apk-press-ink) 2.5%, transparent); }
  &.is-dragging .apk-press-day:not(.is-past):has(.apk-press-ph) { background: color-mix(in oklch, var(--apk-press-gold) 16%, transparent); }
  &.is-dragging .apk-press-day.is-past { opacity: .55; }

  /* ── story sheet (drawer) ── */
  & .apk-press-sheet {
    position: absolute; z-index: 70; top: 0; right: 0; bottom: 0; width: min(440px, 100%);
    background: var(--apk-press-card); border-left: 1px solid var(--apk-press-line2);
    box-shadow: -24px 0 50px -30px color-mix(in oklch, var(--apk-press-ink) 60%, transparent);
    display: grid; grid-template-rows: auto minmax(0, 1fr); visibility: hidden;
    clip-path: inset(0 0 0 100%); transition: clip-path .55s cubic-bezier(.7,0,.2,1), visibility 0s .55s;
    &.is-open { clip-path: inset(0 0 0 0); visibility: visible; transition: clip-path .55s cubic-bezier(.7,0,.2,1), visibility 0s; }
  }
  & .apk-press-shead { display: flex; align-items: center; gap: 8px; padding: 12px 14px 10px 20px; border-bottom: 1px solid var(--apk-press-line); font-size: 10.5px; letter-spacing: .1em; text-transform: uppercase; color: var(--apk-press-mute); }
  & .apk-press-x { margin-left: auto; border: 0; background: none; display: inline-flex; align-items: center; padding: 4px; color: var(--apk-press-mute); }
  & .apk-press-x svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  & .apk-press-sbody { overflow-y: auto; padding: 18px 20px 28px; display: grid; gap: 18px; align-content: start; }
  & .apk-press-sheet.is-entering .apk-press-sbody > * { animation: apk-press-rise .55s var(--apk-press-spring) both; animation-delay: calc(var(--i, 0) * 45ms + 160ms); }
  & .apk-press-shl { width: 100%; border: 0; background: none; resize: none; font: 650 23px/1.18 var(--apk-press-serif); letter-spacing: -.015em; field-sizing: content; min-height: 2.4em; padding: 0; outline: none; }
  & .apk-press-shl:focus { box-shadow: 0 2px 0 var(--apk-press-accent); }
  & .apk-press-sdeck { margin: 0; font: italic 15px/1.5 var(--apk-press-serif); color: var(--apk-press-mute); text-wrap: pretty; }
  & .apk-press-meta { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px;
    & label { display: grid; gap: 4px; font-size: 10.5px; letter-spacing: .08em; text-transform: uppercase; color: var(--apk-press-mute); }
    & select, & input { font-size: 13px; letter-spacing: 0; text-transform: none; color: var(--apk-press-ink); padding: 6px 7px; border: 1px solid var(--apk-press-line2); border-radius: 4px; background: var(--apk-press-paper); min-width: 0; }
  }
  & .apk-press-wbig { display: flex; align-items: baseline; gap: 8px; margin-top: 8px;
    & b { font: 600 30px/1 var(--apk-press-serif); font-variant-numeric: tabular-nums lining-nums; }
    & span { color: var(--apk-press-mute); }
  }
  & .apk-press-wbar { height: 6px; border-radius: 3px; background: color-mix(in oklch, var(--apk-press-ink) 10%, transparent); margin-top: 10px; overflow: hidden; }
  & .apk-press-wbar i { display: block; height: 100%; width: calc(min(var(--f), 1) * 100%); background: var(--apk-press-ink); transition: width .7s var(--apk-press-spring); }
  & .apk-press-wbar.is-full i { background: var(--apk-press-accent); }
  & .apk-press-wslide { width: 100%; margin-top: 10px; }
  & .apk-press-list2 { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 2px;
    & label { display: flex; gap: 10px; align-items: center; padding: 7px 4px; border-bottom: 1px solid var(--apk-press-line); cursor: pointer; }
    & input { width: 16px; height: 16px; margin: 0; }
    & input:checked + span { color: var(--apk-press-mute); text-decoration: line-through; text-decoration-color: var(--apk-press-accent); }
  }

  /* ── new pitch ── */
  & .apk-press-new {
    position: absolute; z-index: 80; left: 50%; top: 84px; width: min(460px, calc(100% - 24px)); translate: -50% 0;
    background: var(--apk-press-card); border: 1px solid var(--apk-press-ink); border-radius: 6px; padding: 16px; display: none; gap: 12px;
    box-shadow: 0 30px 70px -20px color-mix(in oklch, var(--apk-press-ink) 50%, transparent), 8px 8px 0 color-mix(in oklch, var(--apk-press-gold) 70%, transparent);
    transition: opacity .25s, translate .45s var(--apk-press-spring);
    &.is-open { display: grid; @starting-style { opacity: 0; translate: -50% -12px; } }
    & textarea { border: 0; outline: 0; resize: none; background: none; font: 600 20px/1.25 var(--apk-press-serif); }
    & .apk-press-nrow { display: flex; gap: 8px; flex-wrap: wrap; }
    & select { padding: 5px 7px; border: 1px solid var(--apk-press-line2); border-radius: 4px; background: var(--apk-press-paper); font-size: 12.5px; }
    & .apk-press-nact { display: flex; gap: 8px; justify-content: flex-end; }
    & .apk-press-nact button { border: 1px solid var(--apk-press-line2); background: none; border-radius: 5px; padding: 6px 10px; font-weight: 600; font-size: 12.5px; }
    & .apk-press-nact [type="submit"] { background: var(--apk-press-ink); color: var(--apk-press-paper); border-color: var(--apk-press-ink); }
    & .apk-press-nact [type="submit"] kbd { color: inherit; }
  }

  & .apk-press-toast {
    padding: 10px 10px 10px 16px; border-radius: 4px; background: var(--apk-press-ink); color: var(--apk-press-paper); font-size: 12.5px;
    box-shadow: 6px 6px 0 var(--apk-press-gold);
    & [data-undo] { border: 0; background: none; color: var(--apk-press-gold); font-weight: 700; text-decoration: underline; text-underline-offset: 3px; padding: 2px 4px; }
  }
}

@container (width < 960px) {
  .apk-press .apk-press-mast { grid-template-columns: 1fr; grid-template-areas: "name" "stats" "ctrl"; }
  .apk-press .apk-press-stats { justify-self: start; }
  .apk-press .apk-press-stats div:first-child { padding-left: 0; border-left: 0; }
  .apk-press .apk-press-cal { grid-template-columns: 200px minmax(0, 1fr); }
}
@container (width < 760px) {
  .apk-press .apk-press-mast { padding: 14px 12px 0; gap: 10px; }
  .apk-press .apk-press-stats { display: none; }
  .apk-press .apk-press-desks { width: 100%; overflow-x: auto; flex-wrap: nowrap; scrollbar-width: none; }
  .apk-press .apk-press-search { flex: 1; }
  .apk-press .apk-press-search input { width: 100%; }
  .apk-press .apk-press-views kbd, .apk-press .apk-press-pitch kbd { display: none; }
  .apk-press[data-view="board"] .apk-press-tabs {
    display: flex; margin: 0 -12px; overflow-x: auto; scrollbar-width: none; border-top: 1px solid var(--apk-press-line);
    & button { flex: 1 0 auto; border: 0; background: none; padding: 10px 10px; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apk-press-mute); border-bottom: 2px solid transparent; }
    & button span { font: 600 13px var(--apk-press-serif); margin-left: 4px; }
    & button[aria-selected="true"] { color: var(--apk-press-ink); border-bottom-color: var(--apk-press-accent); }
  }
  .apk-press .apk-press-board { grid-auto-columns: 100%; scroll-snap-type: x mandatory; scrollbar-width: none; }
  .apk-press .apk-press-stage { scroll-snap-align: start; border-right: 0; }
  .apk-press .apk-press-stage > header { display: none; }
  .apk-press .apk-press-stage .apk-press-list { padding-top: 12px; }
  /* calendar becomes an agenda: the tray on top, days stacked */
  .apk-press .apk-press-cal { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .apk-press .apk-press-tray { border-right: 0; border-bottom: 1px solid var(--apk-press-line); max-height: 190px; }
  .apk-press .apk-press-tray .apk-press-list { flex-direction: row; overflow-x: auto; overflow-y: hidden; }
  .apk-press .apk-press-tray .apk-press-card { flex: 0 0 200px; }
