    }
    if (!ok) s.c.parentNode.insertBefore(s.ph, s.c);
    const pr = s.ph.getBoundingClientRect();
    g.classList.add('is-landing');
    g.animate([{}, { translate: (pr.left - rr.left) + 'px ' + (pr.top - rr.top) + 'px', rotate: '0deg', scale: '1' }], { duration: 340, easing: SPRING, fill: 'forwards' }).onfinish = done;
  }

  /* narrow layouts: the board becomes a snap pager driven by tabs */
  function pager(board, tabs) {
