/* ── moves ── */
function nextFreeDay() { return DAYS.find(d => d > TODAY && new Date(d + 'T12:00:00Z').getUTCDay() % 6 !== 0 && !data.cells.sched.some(id => data.items[id].date === d)) || DAYS[DAYS.length - 1]; }
function move(id, key, beforeId) {
  const x = data.items[id], from = stageOf(id), was = JSON.stringify([x.date, data.cells]);
  let to = key, date = x.date;
  if (key.startsWith('d:')) { date = key.slice(2); to = date <= TODAY && from === 'pub' ? 'pub' : 'sched'; }
  else if (key === 'tray') { to = 'edit'; date = null; }
  else if (to === 'sched' && (!date || from === 'pub')) date = nextFreeDay();
  else if (to === 'pub' && from !== 'pub') date = TODAY;
  else if (to !== 'sched' && to !== 'pub') date = null;
  data.cells[from].splice(data.cells[from].indexOf(id), 1);
  const arr = data.cells[to];
  let ni = beforeId ? arr.indexOf(beforeId) : -1;
  if (ni < 0) ni = arr.length;
  arr.splice(ni, 0, id); x.date = date;
  if (JSON.stringify([x.date, data.cells]) === was) return false;
  const short = '“' + (x.hl.length > 34 ? x.hl.slice(0, 32) + '…' : x.hl) + '”';
  if (to === 'sched') return short + ' scheduled for ' + fmtDay(date) + (ready(x) ? '' : ' · checks incomplete');
  if (to === 'pub' && from !== 'pub') return short + ' published';
  return short + ' → ' + stageName(to);
}
