  hscroll: () => view === 'board' ? boardEl : null,
  canDrag: id => !(view === 'cal' && stageOf(id) === 'pub'),
  lists: () => $$(view === 'board' ? '.apk-press-board .apk-press-list' : '.apk-press-cal .apk-press-list'),
  accept: (id, L) => { const k = L.dataset.key; return !(k.startsWith('d:') && k.slice(2) < TODAY); }
});
const syncTabs = K.pager(boardEl, tabs);
root.classList.add('is-mounting');
render();
setTimeout(() => root.classList.remove('is-mounting'), 1500);

css:
.apk-hire {
  position: relative; width: 100%; height: var(--apk-hire-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate;
  -webkit-tap-highlight-color: transparent; box-sizing: border-box;
  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & .apk-hire-layer { position: absolute; inset: 0; z-index: 90; pointer-events: none; overflow: clip; }
  & .apk-hire-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .apk-hire-list { position: relative; }
  & .apk-hire-card {
    user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;
    touch-action: manipulation; cursor: grab;
    &.is-src { display: none; }
  }
  & .apk-hire-card.is-ghost {
    position: absolute; left: 0; top: 0; margin: 0; z-index: 2; cursor: grabbing;
    scale: 1.04; will-change: translate, rotate;
    transition: scale .3s var(--apk-hire-spring), box-shadow .3s ease-out, opacity .2s;
    @starting-style { scale: 1; }
    &.is-over-zone { scale: .9; opacity: .8; }
  }
  & .apk-hire-card.is-flyer { z-index: 1; }
  & .apk-hire-ph { transition: opacity .18s ease-out; @starting-style { opacity: 0; } }
  &.is-dragging, &.is-dragging * { cursor: grabbing; }
  & .apk-hire-toast {
    position: absolute; z-index: 95; left: 50%; bottom: 16px; translate: -50% 140%;
    display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
    opacity: 0; pointer-events: none;
    transition: translate .45s var(--apk-hire-spring), opacity .2s ease-out;
    & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
    & [data-undo] { display: none; flex: none; }
    &.has-undo [data-undo] { display: inline-flex; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }
}

@property --apk-hire-n { syntax: '<integer>'; inherits: false; initial-value: 0; }
@property --apk-hire-c { syntax: '<integer>'; inherits: false; initial-value: 0; }
@keyframes apk-hire-ring { from { box-shadow: 0 0 0 0 color-mix(in oklch, var(--apk-hire-accent) 60%, transparent); } to { box-shadow: 0 0 0 14px transparent; } }
@keyframes apk-hire-in { from { opacity: 0; translate: 0 8px; } }
@keyframes apk-hire-note { from { opacity: 0; translate: 0 -6px; scale: .98; } }

.apk-hire {
  --apk-hire-bg: oklch(0.985 0.003 250);
  --apk-hire-ink: oklch(0.23 0.02 280);
  --apk-hire-accent: oklch(0.56 0.21 2);
  --apk-hire-ok: oklch(0.6 0.13 155);
  --apk-hire-warn: oklch(0.72 0.15 70);
  --apk-hire-panel: oklch(1 0 0);
  --apk-hire-sunk: color-mix(in oklch, var(--apk-hire-ink) 3.5%, var(--apk-hire-bg));
  --apk-hire-line: color-mix(in oklch, var(--apk-hire-ink) 10%, transparent);
  --apk-hire-line2: color-mix(in oklch, var(--apk-hire-ink) 18%, transparent);
  --apk-hire-mute: color-mix(in oklch, var(--apk-hire-ink) 58%, var(--apk-hire-bg));
  --apk-hire-faint: color-mix(in oklch, var(--apk-hire-ink) 38%, var(--apk-hire-bg));
  --apk-hire-soft: color-mix(in oklch, var(--apk-hire-accent) 9%, var(--apk-hire-bg));
  --apk-hire-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  --apk-hire-dw: 0px;
  background: var(--apk-hire-bg); color: var(--apk-hire-ink); color-scheme: light; accent-color: var(--apk-hire-accent);
  font: 13px/1.42 system-ui, -apple-system, "Segoe UI", sans-serif; border-radius: 18px; box-shadow: 0 0 0 1px var(--apk-hire-line);

  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 3px 5px 2px; border-radius: 5px; border: 1px solid var(--apk-hire-line2); background: var(--apk-hire-panel); color: var(--apk-hire-mute); }
  & :focus-visible { outline: 2px solid var(--apk-hire-accent); outline-offset: 2px; }
  & h3 { margin: 0; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apk-hire-faint); }

  & .apk-hire-app {
    height: 100%; display: grid;
    grid-template: "rail top top" auto "rail main detail" minmax(0, 1fr) / 214px minmax(0, 1fr) var(--apk-hire-dw);
    transition: grid-template-columns .5s var(--apk-hire-spring);
  }
  &:has(.apk-hire-detail.is-open) { --apk-hire-dw: 340px; }

  /* ── rail ── */
  & .apk-hire-rail { grid-area: rail; padding: 16px 12px; display: flex; flex-direction: column; gap: 10px; border-right: 1px solid var(--apk-hire-line); background: var(--apk-hire-sunk); border-radius: 18px 0 0 18px; overflow-y: auto; min-height: 0; }
  & .apk-hire-org { display: grid; grid-template-columns: auto 1fr; gap: 0 9px; align-items: center; padding: 0 4px 8px;
    & .apk-hire-mark { grid-row: span 2; width: 28px; height: 28px; border-radius: 8px; background: radial-gradient(circle at 30% 30%, color-mix(in oklch, var(--apk-hire-accent), white 25%), var(--apk-hire-accent)); }
    & b { font-size: 14px; letter-spacing: -.01em; } & small { color: var(--apk-hire-mute); font-size: 11.5px; }
  }
  & .apk-hire-rail h3 { padding: 6px 6px 0; }
  & .apk-hire-reqs { display: grid; gap: 2px; }
  & .apk-hire-reqbtn {
    display: grid; grid-template-columns: 1fr auto; gap: 2px 8px; text-align: left; border: 0; background: none; padding: 8px 9px; border-radius: 9px; transition: background .15s;
    & b { font-weight: 620; font-size: 12.5px; }
    & em { font-style: normal; font: 600 11px ui-monospace, Menlo, monospace; color: var(--apk-hire-mute); font-variant-numeric: tabular-nums; }
    & small { grid-column: 1 / -1; color: var(--apk-hire-mute); font-size: 11px; }
    &:hover { background: color-mix(in oklch, var(--apk-hire-ink) 5%, transparent); }
    &[aria-selected="true"] { background: var(--apk-hire-panel); box-shadow: 0 1px 2px var(--apk-hire-line2), 0 0 0 1px var(--apk-hire-line); }
    &[aria-selected="true"] b { color: var(--apk-hire-accent); }
  }
  & .apk-hire-arch-link {
    display: flex; align-items: center; gap: 8px; border: 0; background: none; padding: 8px 9px; border-radius: 9px; font-weight: 600; font-size: 12.5px; color: var(--apk-hire-mute);
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linejoin: round; stroke-linecap: round; }
    & em { margin-left: auto; font-style: normal; font: 600 11px ui-monospace, Menlo, monospace; }
    &:hover { background: color-mix(in oklch, var(--apk-hire-ink) 5%, transparent); }
    &[aria-pressed="true"] { background: var(--apk-hire-panel); color: var(--apk-hire-ink); box-shadow: 0 0 0 1px var(--apk-hire-line); }
  }
  & .apk-hire-keys { margin: auto 0 0; display: grid; gap: 6px; padding: 10px 6px 0; border-top: 1px solid var(--apk-hire-line);
    & div { display: flex; justify-content: space-between; gap: 8px; color: var(--apk-hire-mute); font-size: 11.5px; }
    & dt { white-space: nowrap; } & dd { margin: 0; }
  }

  /* ── header + funnel ── */
  & .apk-hire-top { grid-area: top; display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "req search" "funnel funnel" "tabs tabs"; gap: 12px 16px; padding: 16px 18px 12px; border-bottom: 1px solid var(--apk-hire-line); }
  & .apk-hire-req { grid-area: req; min-width: 0;
    & h2 { margin: 0; font-size: clamp(17px, 1.2cqi + 8px, 22px); font-weight: 720; letter-spacing: -.025em; text-wrap: balance; }
    & p { margin: 2px 0 0; color: var(--apk-hire-mute); font-size: 12px; }
  }
  & .apk-hire-reqsel { display: none; }
  & .apk-hire-search { grid-area: search; align-self: start; display: flex; align-items: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 17px; background: var(--apk-hire-panel); border: 1px solid var(--apk-hire-line2);
    & svg { width: 15px; height: 15px; fill: none; stroke: var(--apk-hire-mute); stroke-width: 2.1; stroke-linecap: round; }
    & input { border: 0; outline: 0; background: none; width: 150px; min-width: 0; }
    &:focus-within { border-color: var(--apk-hire-accent); box-shadow: 0 0 0 4px var(--apk-hire-soft); }
  }
  & .apk-hire-funnel { grid-area: funnel; list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; }
  & .apk-hire-fs {
    position: relative; padding: 9px 11px 10px; border-radius: 10px; background: var(--apk-hire-panel); box-shadow: 0 0 0 1px var(--apk-hire-line);
    & .apk-hire-fl { font-size: 11px; color: var(--apk-hire-mute); font-weight: 550; }
    & .apk-hire-fn { --apk-hire-n: 0; counter-reset: n var(--apk-hire-n); transition: --apk-hire-n .9s cubic-bezier(.3,.7,.2,1); font: 700 22px/1.1 system-ui; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
    & .apk-hire-fn::after { content: counter(n); }
    & .apk-hire-fbar { position: absolute; left: 11px; right: 11px; bottom: 6px; height: 3px; border-radius: 2px; background: var(--apk-hire-line); overflow: hidden; }
    & .apk-hire-fbar i { display: block; height: 100%; width: calc(var(--f) * 100%); background: var(--apk-hire-accent); border-radius: inherit; transition: width .8s var(--apk-hire-spring); }
    & .apk-hire-conv { --apk-hire-c: 0; counter-reset: c var(--apk-hire-c); transition: --apk-hire-c .9s cubic-bezier(.3,.7,.2,1); position: absolute; right: 10px; top: 10px; font: 600 10.5px ui-monospace, Menlo, monospace; color: var(--apk-hire-faint); }
    & .apk-hire-conv::after { content: counter(c) "%"; }
    & .apk-hire-conv::before { content: "\2192\00a0"; }
  }
  & .apk-hire-fs:first-child .apk-hire-conv { display: none; }
  & .apk-hire-tabs { grid-area: tabs; display: none; }

  /* ── board ── */
  & .apk-hire-main { grid-area: main; min-height: 0; position: relative; }
  & .apk-hire-board { height: 100%; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(184px, 1fr); gap: 10px; padding: 12px 14px 14px; overflow-x: auto; scrollbar-width: thin; }
  & .apk-hire-col { display: flex; flex-direction: column; min-height: 0; border-radius: 14px; background: var(--apk-hire-sunk); transition: background .2s, box-shadow .2s; }
  & .apk-hire-col > header { display: flex; align-items: center; gap: 8px; padding: 11px 12px 8px;
    & h3 { color: var(--apk-hire-ink); flex: 1; letter-spacing: .06em; }
    & span { font: 600 11px ui-monospace, Menlo, monospace; color: var(--apk-hire-mute); background: var(--apk-hire-panel); border-radius: 10px; padding: 2px 7px; box-shadow: 0 0 0 1px var(--apk-hire-line); }
  }
  & .apk-hire-col[data-k="hired"] > header h3 { color: var(--apk-hire-accent); }
  &.is-dragging .apk-hire-col:has(.apk-hire-ph) { background: var(--apk-hire-soft); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--apk-hire-accent) 35%, transparent); }
  & .apk-hire-list { flex: 1; min-height: 0; overflow-y: auto; padding: 2px 8px 12px; display: flex; flex-direction: column; gap: 8px; scrollbar-width: thin;
    &:empty::after { content: "No one here yet"; color: var(--apk-hire-faint); font-size: 12px; text-align: center; padding: 18px 0; border: 1.5px dashed var(--apk-hire-line2); border-radius: 11px; }
  }

  & .apk-hire-card {
    display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 2px 10px; padding: 10px; border-radius: 12px; background: var(--apk-hire-panel);
    box-shadow: 0 0 0 1px var(--apk-hire-line), 0 1px 2px var(--apk-hire-line);
    transition: box-shadow .2s, translate .25s var(--apk-hire-spring);
    &:hover { box-shadow: 0 0 0 1px var(--apk-hire-line2), 0 8px 18px -12px color-mix(in oklch, var(--apk-hire-ink) 45%, transparent); translate: 0 -1px; }
    &.is-sel { box-shadow: 0 0 0 2px var(--apk-hire-accent), 0 8px 20px -12px color-mix(in oklch, var(--apk-hire-accent) 60%, transparent); }
    &.is-lifted { outline: 2px dashed var(--apk-hire-accent); outline-offset: 3px; translate: 0 -3px; }
    &.is-ghost { box-shadow: 0 0 0 1.5px var(--apk-hire-accent), 0 26px 46px -18px color-mix(in oklch, var(--apk-hire-ink) 50%, transparent); }
    &.is-ghost.is-landing { box-shadow: 0 0 0 1px var(--apk-hire-line); }
    &.is-ghost.is-over-zone { opacity: .6; filter: grayscale(1); }
    &.is-hired { animation: apk-hire-ring 1.1s ease-out 2; }
  }
  &.is-mounting .apk-hire-card { animation: apk-hire-in .5s var(--apk-hire-spring) both; animation-delay: calc(var(--i, 0) * 28ms); }
  & .apk-hire-ph { border-radius: 12px; background: var(--apk-hire-soft); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--apk-hire-accent) 45%, transparent); }
  & .apk-hire-av { grid-row: span 2; width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; font-size: 11.5px; font-weight: 750; color: oklch(0.3 0.08 var(--h)); background: linear-gradient(140deg, oklch(0.93 0.05 var(--h)), oklch(0.84 0.09 calc(var(--h) + 40))); position: relative; }
  & .apk-hire-age { position: absolute; right: -1px; bottom: -1px; width: 10px; height: 10px; border-radius: 50%; border: 2px solid var(--apk-hire-panel); background: var(--apk-hire-faint); }
  & .apk-hire-age[data-a="warn"] { background: var(--apk-hire-warn); }
  & .apk-hire-age[data-a="stale"] { background: var(--apk-hire-accent); }
  & .apk-hire-nm { font-weight: 650; font-size: 13px; letter-spacing: -.005em; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; align-self: end; }
  & .apk-hire-was { color: var(--apk-hire-mute); font-size: 11.5px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .apk-hire-cfoot { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; margin-top: 8px; padding-top: 8px; border-top: 1px dashed var(--apk-hire-line); font-size: 11px; color: var(--apk-hire-mute); }
  & .apk-hire-src { padding: 1px 6px; border-radius: 5px; background: color-mix(in oklch, var(--apk-hire-ink) 6%, transparent); font-weight: 600; }
  & .apk-hire-src[data-s="Referral"] { background: color-mix(in oklch, var(--apk-hire-ok) 16%, transparent); color: oklch(0.42 0.1 155); }
  & .apk-hire-score { display: inline-flex; gap: 2px; margin-left: auto; }
  & .apk-hire-score i { width: 6px; height: 6px; border-radius: 50%; background: var(--c); }
  & .apk-hire-days { font-variant-numeric: tabular-nums; }
  & .apk-hire-next { grid-column: 1 / -1; margin-top: 6px; display: flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 600; color: var(--apk-hire-accent); }
  & .apk-hire-next svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }

  /* ── archive zone: slides up only while a card is in the air ── */
  & .apk-hire-zone {
    position: absolute; left: 14px; right: 14px; bottom: 12px; height: 64px; z-index: 5; border-radius: 14px;
    display: flex; align-items: center; justify-content: center; gap: 10px; font-weight: 600; color: var(--apk-hire-mute);
    background: color-mix(in oklch, var(--apk-hire-panel) 88%, transparent); backdrop-filter: blur(8px);
    border: 1.5px dashed var(--apk-hire-line2); translate: 0 140%; opacity: 0;
    transition: translate .45s var(--apk-hire-spring), opacity .2s, background .2s, color .2s, border-color .2s, scale .3s var(--apk-hire-spring);
    & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; transition: rotate .3s var(--apk-hire-spring); }
  }
  &.is-dragging .apk-hire-zone { translate: 0 0; opacity: 1; }
  & .apk-hire-zone.is-over { background: var(--apk-hire-soft); color: var(--apk-hire-accent); border-color: var(--apk-hire-accent); scale: 1.02; }
  & .apk-hire-zone.is-over svg { rotate: -12deg; }

  /* ── reason menu ── */
  & .apk-hire-menu {
    position: absolute; z-index: 85; left: 50%; top: 50%; translate: -50% -50%; width: min(300px, calc(100% - 32px));
    background: var(--apk-hire-panel); border-radius: 14px; padding: 6px; display: none;
    box-shadow: 0 0 0 1px var(--apk-hire-line2), 0 30px 60px -20px color-mix(in oklch, var(--apk-hire-ink) 45%, transparent);
    transition: opacity .2s, scale .35s var(--apk-hire-spring);
    &.is-open { display: grid; @starting-style { opacity: 0; scale: .94; } }
    & p { margin: 6px 10px 8px; font-size: 12px; color: var(--apk-hire-mute); }
    & p b { color: var(--apk-hire-ink); }
    & button { text-align: left; border: 0; background: none; padding: 9px 10px; border-radius: 9px; font-weight: 550; display: flex; justify-content: space-between; }
    & button:hover, & button:focus-visible { background: var(--apk-hire-soft); color: var(--apk-hire-accent); outline: none; }
    & button kbd { font-size: 10px; }
  }

  /* ── archived list ── */
  & .apk-hire-archive { position: absolute; inset: 0; overflow-y: auto; padding: 14px 18px; background: var(--apk-hire-bg); }
  & .apk-hire-archive[hidden] { display: none; }
  & .apk-hire-arow { display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; gap: 4px 12px; align-items: center; padding: 10px 4px; border-bottom: 1px solid var(--apk-hire-line); animation: apk-hire-in .45s var(--apk-hire-spring) both; animation-delay: calc(var(--i) * 40ms); }
  & .apk-hire-arow .apk-hire-av { grid-row: auto; width: 30px; height: 30px; font-size: 10.5px; filter: grayscale(.6); }
  & .apk-hire-arow b { font-weight: 620; } & .apk-hire-arow small { display: block; color: var(--apk-hire-mute); }
  & .apk-hire-reason { font-size: 11.5px; padding: 2px 8px; border-radius: 6px; background: color-mix(in oklch, var(--apk-hire-ink) 6%, transparent); color: var(--apk-hire-mute); }
  & .apk-hire-restore { border: 1px solid var(--apk-hire-line2); background: var(--apk-hire-panel); border-radius: 8px; padding: 5px 10px; font-weight: 600; font-size: 12px; }
  & .apk-hire-restore:hover { border-color: var(--apk-hire-accent); color: var(--apk-hire-accent); }

  /* ── detail pane ── */
  & .apk-hire-detail { grid-area: detail; min-width: 0; min-height: 0; overflow: hidden; border-left: 1px solid var(--apk-hire-line); background: var(--apk-hire-panel); border-radius: 0 18px 18px 0; }
  & .apk-hire-dwrap { width: 340px; height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; }
  & .apk-hire-dhead { padding: 16px 16px 12px; display: grid; grid-template-columns: auto 1fr auto; gap: 2px 12px; align-items: center; border-bottom: 1px solid var(--apk-hire-line);
    & .apk-hire-av { width: 44px; height: 44px; font-size: 14px; }
    & h2 { margin: 0; font-size: 16px; font-weight: 720; letter-spacing: -.02em; }
    & p { margin: 0; color: var(--apk-hire-mute); font-size: 12px; grid-column: 2; }
    & .apk-hire-x { grid-row: 1; grid-column: 3; border: 0; background: none; padding: 4px; border-radius: 7px; color: var(--apk-hire-mute); display: inline-flex; }
    & .apk-hire-x:hover { background: color-mix(in oklch, var(--apk-hire-ink) 6%, transparent); }
    & .apk-hire-x svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  }
  & .apk-hire-steps { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(5, 1fr); gap: 4px; margin-top: 12px;
    & i { height: 4px; border-radius: 2px; background: var(--apk-hire-line); transition: background .4s; }
    & i.on { background: var(--apk-hire-accent); }
  }
  & .apk-hire-stepl { grid-column: 1 / -1; display: flex; justify-content: space-between; font-size: 11px; color: var(--apk-hire-mute); margin-top: 4px; }
  & .apk-hire-dbody { overflow-y: auto; padding: 14px 16px; display: grid; gap: 18px; align-content: start; }
  & .apk-hire-dbody > * { animation: apk-hire-in .45s var(--apk-hire-spring) both; animation-delay: calc(var(--i, 0) * 40ms); }
  & .apk-hire-acts { display: flex; gap: 8px; }
  & .apk-hire-adv { flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px; border: 0; border-radius: 10px; background: var(--apk-hire-accent); color: white; font-weight: 650; padding: 9px 12px; transition: scale .2s var(--apk-hire-spring), filter .2s; }
  & .apk-hire-adv:hover { filter: brightness(1.06); } & .apk-hire-adv:active { scale: .97; }
  & .apk-hire-adv kbd, & .apk-hire-arc kbd { background: none; color: inherit; border-color: color-mix(in oklch, currentColor 35%, transparent); }
  & .apk-hire-adv[disabled] { opacity: .45; cursor: default; }
  & .apk-hire-arc { border: 1px solid var(--apk-hire-line2); background: none; border-radius: 10px; padding: 9px 12px; font-weight: 600; display: inline-flex; align-items: center; gap: 6px; }
  & .apk-hire-sc { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 8px; }
