        if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); cancelLift(); return; }
        return;
      }
      if (e.key === ' ') { e.preventDefault(); pick(n); return; }
      if (arrow) { e.preventDefault(); nav(n, e.key); return; }
      if (e.key === 'Enter' && o.open) { e.preventDefault(); o.open(n.dataset.id); return; }
    }
    if (o.keys) o.keys(e, typing);
  });

  /* pointer drag: lifted ghost in the overlay, live placeholder, FLIP siblings,
