    if (!st || e.pointerId !== st.pid) return;
    clearTimeout(st.timer);
    if (st.live) finish(true); else st = null;
  });
  root.addEventListener('pointercancel', e => {
    if (!st || e.pointerId !== st.pid) return;
    clearTimeout(st.timer);
    if (st.live) finish(false); else st = null;
  });
  root.addEventListener('lostpointercapture', e => { if (e.target === root && st && st.live && e.pointerId === st.pid) finish(true); });
  root.addEventListener('touchmove', e => { if (st && st.live) e.preventDefault(); }, { passive: false });
