    const ph = mk('apk-hire-ph'); ph.style.height = r.height + 'px'; ph.setAttribute('aria-hidden', 'true');
    c.parentNode.insertBefore(ph, c); c.classList.add('is-src'); st.ph = ph;
    const g = c.cloneNode(true);
    ['data-id', 'tabindex', 'id', 'aria-describedby'].forEach(k => g.removeAttribute(k));
    g.classList.add('is-ghost'); g.classList.remove('is-lifted', 'is-src');
    Object.assign(g.style, { width: r.width + 'px', height: r.height + 'px', translate: (r.left - rr.left) + 'px ' + (r.top - rr.top) + 'px' });
