  x.stage = key;
  if (JSON.stringify([x.stage, data.order]) === was) return false;
  if (from !== key) { x.days = 0; x.next = key === 'hired' ? 'Offer accepted' : key === 'offer' ? 'Draft offer' : ''; }
  if (key === 'hired' && from !== 'hired') { hiredFx = id; setTimeout(() => { hiredFx = null; }, 2400); }
  return from === key ? 'Reordered ' + x.name : x.name + ' → ' + STAGES[stageIdx(key)][1];
}
function advance(id) {
  if (!id) return; const x = data.c[id], nxt = STAGES[stageIdx(x.stage) + 1]; if (!nxt) return;
  K.apply(() => move(id, nxt[0], null));
  const n = K.els.get(id); if (n) { K.reveal(n); }
}
const name = id => data.c[id].name;
const where = id => { const x = data.c[id]; const col = data.order.filter(o => data.c[o].stage === x.stage && visible(o)); return STAGES[stageIdx(x.stage)][1] + ', ' + (col.indexOf(id) + 1) + ' of ' + col.length; };

/* ── archive with a reason (zone drop or E) ── */
function openMenu(id) {
  menuFor = id;
  menu.innerHTML = '<p>Archive <b>' + esc(data.c[id].name) + '</b> because…</p>' + REASONS.map((r, i) => '<button type="button" role="menuitem" data-reason="' + i + '">' + r + '<kbd>' + (i + 1) + '</kbd></button>').join('');
  menu.classList.add('is-open');
  $('button', menu).focus();
}
function closeMenu(restore) { menu.classList.remove('is-open'); const id = menuFor; menuFor = null; if (restore) { const n = K.els.get(id); if (n && n.isConnected) n.focus({ preventScroll: true }); else root.focus(); } }
function archive(id, reason) {
  closeMenu(false);
  K.apply(() => { data.archived.push({ id, reason, when: 'Oct 2' }); if (sel === id) { sel = null; detail.classList.remove('is-open', 'was-open'); } return data.c[id].name + ' archived · ' + reason; });
  root.focus({ preventScroll: true });
}
menu.addEventListener('click', e => { const b = e.target.closest('[data-reason]'); if (b) archive(menuFor, REASONS[+b.dataset.reason]); });
menu.addEventListener('keydown', e => {
  const items = $$('[data-reason]', menu), i = items.indexOf(doc.activeElement);
  if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); e.stopPropagation(); items[(i + (e.key === 'ArrowDown' ? 1 : items.length - 1)) % items.length].focus(); }
  else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); closeMenu(true); }
  else if (/^[1-5]$/.test(e.key)) { e.preventDefault(); e.stopPropagation(); archive(menuFor, REASONS[+e.key - 1]); }
  else if (e.key === 'Tab') { e.preventDefault(); items[(i + (e.shiftKey ? items.length - 1 : 1)) % items.length].focus(); }
});

/* ── events ── */
function setReq(k) {
  if (k === req && view === 'board') return;
  const go = () => { req = k; view = 'board'; sel = null; detail.classList.remove('is-open', 'was-open'); render(); };
  if (doc.startViewTransition && !RM.matches) doc.startViewTransition(go); else go();
}
root.addEventListener('click', e => {
  const t = e.target;
  const r = t.closest('[data-req]'); if (r) return setReq(r.dataset.req);
  if (t.closest('[data-act="archived"]')) { view = view === 'archived' ? 'board' : 'archived'; return render(); }
  const rs = t.closest('[data-restore]'); if (rs) { const id = rs.dataset.restore; return K.apply(() => { data.archived = data.archived.filter(a => a.id !== id); if (!data.order.includes(id)) data.order.push(id); req = data.c[id].req; return data.c[id].name + ' restored to ' + STAGES[stageIdx(data.c[id].stage)][1]; }); }
  const c = t.closest('.apk-hire-card'); if (c && boardEl.contains(c)) return select(c.dataset.id);
});
$('[data-reqsel]').addEventListener('change', e => setReq(e.target.value));
$('[data-q]').addEventListener('input', e => { q = e.target.value.trim().toLowerCase(); K.flip(render); });
$('[data-q]').addEventListener('keydown', e => { if (e.key === 'Escape') { e.stopPropagation(); e.target.value = ''; q = ''; K.flip(render); root.focus(); } });
function keys(e, typing) {
  if (e.key === 'Escape') { if (menuFor) return closeMenu(true); if (sel) { e.preventDefault(); return closeDetail(); } if (view === 'archived') { view = 'board'; return render(); } return; }
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key.toLowerCase();
  const focused = e.target.closest && e.target.closest('.apk-hire-card');
  const target = focused ? focused.dataset.id : sel;
  if (e.key === '/') { e.preventDefault(); $('[data-q]').focus(); }
  else if (/^[1-3]$/.test(e.key)) setReq(Object.keys(REQS)[+e.key - 1]);
  else if (k === 'a' && target) { e.preventDefault(); advance(target); }
  else if (k === 'e' && target) { e.preventDefault(); openMenu(target); }
}

const K = boardKit({
  get: () => data, set: d => { data = d; detailSig = ''; if (sel && archivedIds().includes(sel)) { sel = null; detail.classList.remove('is-open', 'was-open'); } }, render, move, name, where, open: select, keys,
  hscroll: () => boardEl, zone: '[data-zone]', zoneDrop: id => openMenu(id)
});
const syncTabs = K.pager(boardEl, tabs);
root.classList.add('is-mounting');
render();
setTimeout(() => root.classList.remove('is-mounting'), 1300);

css:
.apk-triage {
  position: relative; width: 100%; height: var(--apk-triage-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate;
  -webkit-tap-highlight-color: transparent; box-sizing: border-box;
  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & .apk-triage-layer { position: absolute; inset: 0; z-index: 90; pointer-events: none; overflow: clip; }
  & .apk-triage-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .apk-triage-list { position: relative; }
  & .apk-triage-card {
    user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;
    touch-action: manipulation; cursor: grab;
    &.is-src { display: none; }
  }
  & .apk-triage-card.is-ghost {
    position: absolute; left: 0; top: 0; margin: 0; z-index: 2; cursor: grabbing;
    scale: 1.04; will-change: translate, rotate;
    transition: scale .3s var(--apk-triage-spring), box-shadow .3s ease-out, opacity .2s;
    @starting-style { scale: 1; }
    &.is-over-zone { scale: .9; opacity: .8; }
  }
  & .apk-triage-card.is-flyer { z-index: 1; }
  & .apk-triage-ph { transition: opacity .18s ease-out; @starting-style { opacity: 0; } }
  &.is-dragging, &.is-dragging * { cursor: grabbing; }
  & .apk-triage-toast {
    position: absolute; z-index: 95; left: 50%; bottom: 16px; translate: -50% 140%;
    display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
    opacity: 0; pointer-events: none;
    transition: translate .45s var(--apk-triage-spring), opacity .2s ease-out;
    & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
    & [data-undo] { display: none; flex: none; }
    &.has-undo [data-undo] { display: inline-flex; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }
}

@keyframes apk-triage-arrive { 0% { opacity: 0; translate: 0 -14px; clip-path: inset(0 0 100% 0); } 60% { opacity: 1; clip-path: inset(0); } }
@keyframes apk-triage-glow { from { box-shadow: inset 3px 0 var(--apk-triage-focus), 0 0 0 1px color-mix(in oklch, var(--apk-triage-focus) 60%, transparent), 0 0 24px -4px color-mix(in oklch, var(--apk-triage-focus) 50%, transparent); } }
@keyframes apk-triage-blink { 50% { opacity: .25; } }
@keyframes apk-triage-breach { 50% { background: color-mix(in oklch, var(--apk-triage-p0) 30%, transparent); } }
@keyframes apk-triage-in { from { opacity: 0; translate: 0 6px; } }

.apk-triage {
  --apk-triage-bg: oklch(0.165 0.006 70);
  --apk-triage-ink: oklch(0.93 0.012 85);
  --apk-triage-focus: oklch(0.88 0.18 125);
  --apk-triage-p0: oklch(0.66 0.21 25);
  --apk-triage-p1: oklch(0.8 0.15 72);
  --apk-triage-p2: oklch(0.75 0.07 240);
  --apk-triage-wf: oklch(0.6 0.01 80);
  --apk-triage-panel: color-mix(in oklch, var(--apk-triage-bg), white 3%);
  --apk-triage-raise: color-mix(in oklch, var(--apk-triage-bg), white 6.5%);
  --apk-triage-line: color-mix(in oklch, var(--apk-triage-ink) 10%, transparent);
  --apk-triage-line2: color-mix(in oklch, var(--apk-triage-ink) 18%, transparent);
  --apk-triage-mute: color-mix(in oklch, var(--apk-triage-ink) 55%, var(--apk-triage-bg));
  --apk-triage-faint: color-mix(in oklch, var(--apk-triage-ink) 33%, var(--apk-triage-bg));
  --apk-triage-mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
  --apk-triage-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  background: var(--apk-triage-bg); color: var(--apk-triage-ink); color-scheme: dark; accent-color: var(--apk-triage-focus);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif; border-radius: 10px;
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--apk-triage-ink) 8%, transparent);

  & kbd { font: 600 10px/1 var(--apk-triage-mono); padding: 3px 5px 2px; border-radius: 4px; background: color-mix(in oklch, var(--apk-triage-ink) 7%, transparent); color: var(--apk-triage-ink); box-shadow: inset 0 -1px var(--apk-triage-line2); }
  & :focus-visible { outline: 1.5px solid var(--apk-triage-focus); outline-offset: 2px; }

  & .apk-triage-app { height: 100%; display: grid; grid-template: "head head" auto "board insp" minmax(0, 1fr) "keys keys" auto / minmax(0, 1fr) 330px; }
  &[data-mode="focus"] .apk-triage-app { grid-template-columns: minmax(250px, 340px) minmax(0, 1fr); }

  /* ── header ── */
  & .apk-triage-head { grid-area: head; display: flex; align-items: center; flex-wrap: wrap; gap: 10px 18px; padding: 11px 14px; border-bottom: 1px solid var(--apk-triage-line); font-family: var(--apk-triage-mono); font-size: 12px; }
  & .apk-triage-prod { display: flex; align-items: center; gap: 8px;
    & .apk-triage-glyph { width: 18px; height: 18px; border-radius: 4px; background: conic-gradient(from 45deg, var(--apk-triage-p0), var(--apk-triage-p1), var(--apk-triage-focus), var(--apk-triage-p2), var(--apk-triage-p0)); mask: radial-gradient(circle at 50% 50%, transparent 4px, #000 4.5px); }
    & b { font-size: 14px; letter-spacing: -.02em; } & span { color: var(--apk-triage-mute); }
  }
  & .apk-triage-live { display: flex; align-items: center; gap: 6px; color: var(--apk-triage-focus); font-variant-numeric: tabular-nums;
    & i { width: 7px; height: 7px; border-radius: 50%; background: var(--apk-triage-focus); box-shadow: 0 0 10px var(--apk-triage-focus); animation: apk-triage-blink 1.6s steps(2, jump-none) infinite; }
    & .apk-triage-dim { color: var(--apk-triage-faint); }
  }
  & .apk-triage-plats { display: flex; gap: 4px; margin-left: auto; }
  & .apk-triage-plat { border: 1px solid var(--apk-triage-line2); background: none; border-radius: 5px; padding: 4px 8px; font: 600 11px var(--apk-triage-mono); color: var(--apk-triage-mute); transition: color .15s, border-color .15s, background .15s;
    &[aria-pressed="true"] { color: var(--apk-triage-bg); background: var(--apk-triage-ink); border-color: var(--apk-triage-ink); }
  }
  & .apk-triage-search { display: flex; align-items: center; gap: 6px; padding: 4px 6px 4px 9px; border-radius: 6px; background: color-mix(in oklch, var(--apk-triage-ink) 5%, transparent); border: 1px solid var(--apk-triage-line);
    & span { color: var(--apk-triage-focus); font-weight: 700; }
    & input { border: 0; outline: 0; background: none; font: 12px var(--apk-triage-mono); width: 120px; min-width: 0; }
    &:focus-within { border-color: color-mix(in oklch, var(--apk-triage-focus) 55%, transparent); }
  }
  & .apk-triage-mode { border: 1px solid var(--apk-triage-line2); background: none; border-radius: 6px; padding: 5px 8px; font: 600 11px var(--apk-triage-mono); display: inline-flex; gap: 6px; align-items: center; }
  & .apk-triage-mode[aria-pressed="true"] { border-color: var(--apk-triage-focus); color: var(--apk-triage-focus); }
  & .apk-triage-tabs { display: none; }

  /* ── buckets ── */
  & .apk-triage-board { grid-area: board; min-height: 0; display: grid; grid-template-columns: minmax(220px, 1.35fr) repeat(4, minmax(118px, 1fr)); overflow-x: auto; scrollbar-width: thin; }
  &[data-mode="focus"] .apk-triage-board { grid-template-columns: minmax(0, 1fr); }
  &[data-mode="focus"] .apk-triage-col:not([data-k="inbox"]) { display: none; }
  & .apk-triage-col { display: flex; flex-direction: column; min-height: 0; border-right: 1px solid var(--apk-triage-line); --c: var(--apk-triage-ink); }
  & .apk-triage-col[data-k="p0"] { --c: var(--apk-triage-p0); } & .apk-triage-col[data-k="p1"] { --c: var(--apk-triage-p1); } & .apk-triage-col[data-k="p2"] { --c: var(--apk-triage-p2); } & .apk-triage-col[data-k="wf"] { --c: var(--apk-triage-wf); }
  & .apk-triage-col > header { padding: 10px 10px 8px; display: grid; grid-template-columns: 1fr auto; gap: 1px 6px; font-family: var(--apk-triage-mono); border-top: 2px solid color-mix(in oklch, var(--c) 80%, transparent);
    & b { font-size: 12px; color: var(--c); letter-spacing: .02em; }
    & span { font-size: 11px; color: var(--apk-triage-mute); font-variant-numeric: tabular-nums; }
    & small { grid-column: 1 / -1; font-size: 10.5px; color: var(--apk-triage-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  & .apk-triage-col[data-k="inbox"] > header { border-top-color: var(--apk-triage-focus); } & .apk-triage-col[data-k="inbox"] > header b { color: var(--apk-triage-focus); }
  &.is-dragging .apk-triage-col:has(.apk-triage-ph) { background: color-mix(in oklch, var(--c) 6%, transparent); }
  & .apk-triage-list { flex: 1; min-height: 0; overflow-y: auto; padding: 2px 6px 12px; display: flex; flex-direction: column; gap: 4px; scrollbar-width: thin; }
  & .apk-triage-col[data-k="inbox"] .apk-triage-list:empty::after { content: "inbox zero. nice."; font: 12px var(--apk-triage-mono); color: var(--apk-triage-focus); text-align: center; padding: 30px 0; }

  & .apk-triage-card {
    position: relative; padding: 8px 9px 8px 11px; border-radius: 6px; background: var(--apk-triage-panel); display: grid; gap: 4px;
    box-shadow: inset 2px 0 color-mix(in oklch, var(--c) 70%, transparent);
    transition: background .12s, box-shadow .2s;
    &:hover { background: var(--apk-triage-raise); }
    &.is-sel { background: var(--apk-triage-raise); box-shadow: inset 3px 0 var(--apk-triage-focus), 0 0 0 1px color-mix(in oklch, var(--apk-triage-focus) 40%, transparent); }
    &.is-new { animation: apk-triage-arrive .6s var(--apk-triage-spring) both, apk-triage-glow 2.4s ease-out both; }
    &.is-lifted { box-shadow: inset 3px 0 var(--apk-triage-focus), 0 0 0 1.5px var(--apk-triage-focus), 0 10px 26px -8px rgb(0 0 0 / .7); translate: 0 -2px; }
    &.is-ghost { background: var(--apk-triage-raise); box-shadow: inset 3px 0 var(--apk-triage-focus), 0 0 0 1px var(--apk-triage-focus), 0 24px 40px -12px rgb(0 0 0 / .8); }
    &.is-ghost.is-landing { box-shadow: inset 2px 0 var(--c); }
  }
  & .apk-triage-ph { border-radius: 6px; border: 1px dashed var(--c, var(--apk-triage-focus)); background: color-mix(in oklch, var(--c, var(--apk-triage-focus)) 8%, transparent); }
  & .apk-triage-k1 { display: flex; align-items: center; gap: 8px; font: 600 10.5px var(--apk-triage-mono); color: var(--apk-triage-mute); font-variant-numeric: tabular-nums; }
  & .apk-triage-k1 .apk-triage-cnt { margin-left: auto; color: var(--apk-triage-faint); }
  & .apk-triage-k1 svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linejoin: round; }
  & .apk-triage-tt { margin: 0; font-size: 12.5px; line-height: 1.35; font-weight: 500; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; text-wrap: pretty; }
  & .apk-triage-col:not([data-k="inbox"]) .apk-triage-tt { font-size: 12px; }
  & .apk-triage-sla { font: 700 10.5px var(--apk-triage-mono); color: var(--apk-triage-p0); font-variant-numeric: tabular-nums; display: flex; gap: 6px; align-items: center; }
  & .apk-triage-sla.is-hot { animation: apk-triage-blink 1s steps(2, jump-none) infinite; }
  & .apk-triage-sla.is-breach { padding: 1px 5px; border-radius: 4px; animation: apk-triage-breach 1.4s ease-in-out infinite; }
  & .apk-triage-sla.is-ack { color: var(--apk-triage-focus); }

  /* ── inspector ── */
  & .apk-triage-insp { grid-area: insp; min-height: 0; overflow-y: auto; border-left: 1px solid var(--apk-triage-line); padding: 14px 16px 18px; display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; align-content: start; scrollbar-width: thin; }
  & .apk-triage-insp > * { animation: apk-triage-in .35s var(--apk-triage-spring) both; animation-delay: calc(var(--i, 0) * 30ms); }
  & .apk-triage-insp.is-quiet > * { animation: none; }
  & .apk-triage-ikey { display: flex; align-items: center; gap: 8px; font: 600 11px var(--apk-triage-mono); color: var(--apk-triage-mute); }
  & .apk-triage-sev { padding: 2px 6px; border-radius: 4px; font-weight: 700; color: var(--apk-triage-bg); background: var(--c); }
  & .apk-triage-ititle { margin: 0; font-size: clamp(15px, 1cqi + 6px, 19px); line-height: 1.3; font-weight: 650; letter-spacing: -.01em; text-wrap: balance; }
  &[data-mode="focus"] .apk-triage-ititle { font-size: clamp(18px, 1.6cqi + 6px, 26px); }
  & .apk-triage-env { display: flex; flex-wrap: wrap; gap: 5px; font: 11px var(--apk-triage-mono); }
  & .apk-triage-env span { padding: 2px 6px; border-radius: 4px; background: color-mix(in oklch, var(--apk-triage-ink) 7%, transparent); color: var(--apk-triage-mute); }
  & .apk-triage-impact { display: grid; grid-template-columns: auto 1fr; gap: 2px 14px; align-items: end;
    & b { font: 650 24px/1 var(--apk-triage-mono); font-variant-numeric: tabular-nums; letter-spacing: -.03em; }
    & small { grid-row: 2; color: var(--apk-triage-mute); font-size: 11px; }
    & svg { grid-row: 1 / span 2; grid-column: 2; width: 100%; height: 44px; }
    & rect { fill: color-mix(in oklch, var(--apk-triage-ink) 22%, transparent); }
    & rect.hot { fill: var(--apk-triage-focus); }
  }
  & .apk-triage-trace { margin: 0; padding: 10px 12px; border-radius: 6px; background: oklch(0.13 0.005 70); font: 11px/1.65 var(--apk-triage-mono); color: var(--apk-triage-mute); overflow-x: auto; white-space: pre; box-shadow: inset 0 0 0 1px var(--apk-triage-line); }
  & .apk-triage-trace b { color: var(--apk-triage-p1); font-weight: 600; }
  & .apk-triage-trace em { color: var(--apk-triage-faint); font-style: normal; }
  & .apk-triage-acts { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
  & .apk-triage-acts button { display: grid; justify-items: start; gap: 4px; padding: 8px 9px; border-radius: 6px; border: 1px solid var(--apk-triage-line2); background: none; font: 600 11px var(--apk-triage-mono); text-align: left; transition: border-color .15s, background .15s, translate .2s var(--apk-triage-spring); }
  & .apk-triage-acts button:hover { border-color: var(--c); background: color-mix(in oklch, var(--c) 10%, transparent); }
  & .apk-triage-acts button:active { translate: 0 1px; }
  & .apk-triage-acts button[aria-pressed="true"] { border-color: var(--c); color: var(--c); }
  & .apk-triage-acts span { color: var(--c); font-size: 13px; }
  & .apk-triage-ack { justify-self: start; border: 1px solid var(--apk-triage-p0); color: var(--apk-triage-p0); background: color-mix(in oklch, var(--apk-triage-p0) 10%, transparent); border-radius: 6px; padding: 7px 11px; font: 700 11.5px var(--apk-triage-mono); display: inline-flex; gap: 8px; align-items: center; }
  & .apk-triage-ilbl { font: 600 10.5px var(--apk-triage-mono); color: var(--apk-triage-faint); text-transform: uppercase; letter-spacing: .08em; margin: 0 0 6px; }
  & .apk-triage-empty { color: var(--apk-triage-faint); font: 12px var(--apk-triage-mono); padding-top: 40px; text-align: center; }

  & .apk-triage-keys { grid-area: keys; display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 7px 14px; border-top: 1px solid var(--apk-triage-line); font: 11px var(--apk-triage-mono); color: var(--apk-triage-mute);
    & span { display: inline-flex; gap: 4px; align-items: center; }
  }
  & .apk-triage-toast { padding: 8px 8px 8px 12px; border-radius: 7px; background: var(--apk-triage-ink); color: var(--apk-triage-bg); font: 600 12px var(--apk-triage-mono);
    & [data-undo] { border: 0; border-radius: 5px; padding: 4px 8px; background: var(--apk-triage-bg); color: var(--apk-triage-focus); font: 700 11px var(--apk-triage-mono); }
  }
