.apk-flow {
  position: relative; width: 100%; height: var(--apk-flow-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate;
  -webkit-tap-highlight-color: transparent; box-sizing: border-box;
  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & .apk-flow-layer { position: absolute; inset: 0; z-index: 90; pointer-events: none; overflow: clip; }
  & .apk-flow-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .apk-flow-list { position: relative; }
  & .apk-flow-card {
    user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;
    touch-action: manipulation; cursor: grab;
    &.is-src { display: none; }
  }
  & .apk-flow-card.is-ghost {
    position: absolute; left: 0; top: 0; margin: 0; z-index: 2; cursor: grabbing;
    scale: 1.04; will-change: translate, rotate;
    transition: scale .3s var(--apk-flow-spring), box-shadow .3s ease-out, opacity .2s;
    @starting-style { scale: 1; }
    &.is-over-zone { scale: .9; opacity: .8; }
  }
  & .apk-flow-card.is-flyer { z-index: 1; }
  & .apk-flow-ph { transition: opacity .18s ease-out; @starting-style { opacity: 0; } }
  &.is-dragging, &.is-dragging * { cursor: grabbing; }
  & .apk-flow-toast {
    position: absolute; z-index: 95; left: 50%; bottom: 16px; translate: -50% 140%;
    display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
    opacity: 0; pointer-events: none;
    transition: translate .45s var(--apk-flow-spring), opacity .2s ease-out;
    & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
    & [data-undo] { display: none; flex: none; }
    &.has-undo [data-undo] { display: inline-flex; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }
}

@property --apk-flow-v { syntax: '<integer>'; inherits: false; initial-value: 0; }
@keyframes apk-flow-in { from { opacity: 0; translate: 0 10px; } }
@keyframes apk-flow-risk { 0%, 100% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--apk-flow-risk) 70%, transparent); } 70% { box-shadow: 0 0 0 6px transparent; } }

.apk-flow {
  --apk-flow-bg: oklch(0.2 0.014 55);
  --apk-flow-ink: oklch(0.94 0.015 80);
  --apk-flow-accent: oklch(0.82 0.12 78);
  --apk-flow-risk: oklch(0.68 0.18 32);
  --apk-flow-b0: oklch(0.87 0.05 85);
  --apk-flow-b1: oklch(0.77 0.12 72);
  --apk-flow-b2: oklch(0.66 0.13 45);
  --apk-flow-b3: oklch(0.67 0.09 125);
  --apk-flow-b4: oklch(0.47 0.05 140);
  --apk-flow-panel: color-mix(in oklch, var(--apk-flow-bg), white 4%);
  --apk-flow-raise: color-mix(in oklch, var(--apk-flow-bg), white 8%);
  --apk-flow-line: color-mix(in oklch, var(--apk-flow-ink) 10%, transparent);
  --apk-flow-line2: color-mix(in oklch, var(--apk-flow-ink) 18%, transparent);
  --apk-flow-mute: color-mix(in oklch, var(--apk-flow-ink) 58%, var(--apk-flow-bg));
  --apk-flow-faint: color-mix(in oklch, var(--apk-flow-ink) 36%, var(--apk-flow-bg));
  --apk-flow-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  background: var(--apk-flow-bg); color: var(--apk-flow-ink); color-scheme: dark; accent-color: var(--apk-flow-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif; border-radius: 14px;

  & :focus-visible { outline: 2px solid var(--apk-flow-accent); outline-offset: 2px; }
  & .apk-flow-app { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr) 236px; grid-template-columns: minmax(0, 1fr); }
  &[data-view="board"] .apk-flow-app { grid-template-rows: auto minmax(0, 1fr) 0; }
  &[data-view="board"] .apk-flow-ins { display: none; }
  &[data-view="charts"] .apk-flow-app { grid-template-rows: auto 0 minmax(0, 1fr); }
  &[data-view="charts"] .apk-flow-board { display: none; }

  & .apk-flow-head { display: grid; grid-template-columns: auto 1fr; grid-template-areas: "team kpis" "tools tools" "tabs tabs"; gap: 10px 20px; padding: 14px 16px 10px; border-bottom: 1px solid var(--apk-flow-line); }
  & .apk-flow-team { grid-area: team; display: grid; align-content: center;
    & b { font-size: 16px; font-weight: 720; letter-spacing: -.02em; } & span { color: var(--apk-flow-mute); font-size: 12px; }
  }
  & .apk-flow-kpis { grid-area: kpis; justify-self: end; display: flex; margin: 0; gap: 4px;
    & div { padding: 6px 12px; border-radius: 10px; background: var(--apk-flow-panel); min-width: 92px; }
    & dt { font-size: 11px; color: var(--apk-flow-mute); } & dt small { color: var(--apk-flow-faint); }
    & dd { margin: 0; font: 700 21px/1.15 system-ui; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
    & dd small { font-size: 12px; color: var(--apk-flow-mute); font-weight: 500; margin-left: 1px; }
  }
  & .apk-flow-num { --apk-flow-v: 0; counter-reset: v var(--apk-flow-v); transition: --apk-flow-v .8s cubic-bezier(.3,.7,.2,1); }
  & .apk-flow-num::after { content: counter(v); }
  & .apk-flow-num.is-risk { color: var(--apk-flow-risk); }
  & .apk-flow-tools { grid-area: tools; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
  & .apk-flow-cos { display: flex; gap: 4px; flex-wrap: wrap; margin-right: auto; }
  & .apk-flow-cbtn { display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--apk-flow-line2); background: none; border-radius: 8px; padding: 4px 9px; font-size: 12px; font-weight: 600; color: var(--apk-flow-mute); transition: background .15s, color .15s, border-color .15s;
    & i { width: 9px; height: 9px; border-radius: 2px; background: var(--c); }
    & em { font-style: normal; font-variant-numeric: tabular-nums; color: var(--apk-flow-faint); }
    &[aria-pressed="true"] { color: var(--apk-flow-ink); border-color: var(--c); background: color-mix(in oklch, var(--c) 14%, transparent); }
  }
  & .apk-flow-search { display: flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 8px; background: var(--apk-flow-panel); border: 1px solid var(--apk-flow-line);
    & svg { width: 14px; height: 14px; fill: none; stroke: var(--apk-flow-mute); stroke-width: 2.2; stroke-linecap: round; }
    & input { border: 0; outline: 0; background: none; width: 120px; min-width: 0; }
    &:focus-within { border-color: var(--apk-flow-accent); }
  }
  & .apk-flow-seg { display: flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--apk-flow-panel);
    & button { border: 0; background: none; padding: 4px 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--apk-flow-mute); }
    & [aria-selected="true"] { background: var(--apk-flow-accent); color: var(--apk-flow-bg); }
  }
  & .apk-flow-tabs { grid-area: tabs; display: none; }

  /* ── board ── */
  & .apk-flow-board { min-height: 0; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(176px, 1fr); gap: 8px; padding: 10px 12px; overflow-x: auto; scrollbar-width: thin; }
  & .apk-flow-col { display: flex; flex-direction: column; min-height: 0; border-radius: 12px; background: color-mix(in oklch, var(--apk-flow-bg), black 12%); position: relative; overflow: hidden; }
  & .apk-flow-col::before { content: ""; position: absolute; inset: 0 0 auto; height: 3px; background: var(--c); }
  & .apk-flow-col > header { display: flex; align-items: baseline; gap: 6px; padding: 11px 11px 6px;
    & h3 { margin: 0; font-size: 12px; font-weight: 700; flex: 1; }
    & span { font: 600 11px ui-monospace, Menlo, monospace; color: var(--apk-flow-mute); font-variant-numeric: tabular-nums; }
    & small { font-size: 10.5px; color: var(--apk-flow-faint); }
  }
  & .apk-flow-col[data-over] > header span { color: var(--apk-flow-risk); }
  & .apk-flow-col[data-over]::before { background: repeating-linear-gradient(90deg, var(--apk-flow-risk) 0 6px, transparent 6px 10px); }
  &.is-dragging .apk-flow-col:has(.apk-flow-ph) { background: color-mix(in oklch, var(--c) 9%, color-mix(in oklch, var(--apk-flow-bg), black 12%)); }
  & .apk-flow-list { flex: 1; min-height: 0; overflow-y: auto; padding: 2px 7px 10px; display: flex; flex-direction: column; gap: 6px; scrollbar-width: thin; }

  & .apk-flow-card {
    display: grid; gap: 6px; padding: 9px 10px 9px 12px; border-radius: 9px; background: var(--apk-flow-panel); position: relative;
    box-shadow: inset 3px 0 var(--k), 0 1px 0 rgb(255 255 255 / .03) inset;
    transition: background .15s, translate .25s var(--apk-flow-spring), box-shadow .2s;
    &:hover { background: var(--apk-flow-raise); translate: 0 -1px; }
    &.is-open { box-shadow: inset 3px 0 var(--k), 0 0 0 1.5px var(--apk-flow-accent); }
    &.is-lifted { box-shadow: inset 3px 0 var(--k), 0 0 0 2px var(--apk-flow-accent), 0 14px 26px -12px rgb(0 0 0 / .7); translate: 0 -3px; }
    &.is-ghost { box-shadow: inset 3px 0 var(--k), 0 0 0 1px var(--apk-flow-accent), 0 26px 44px -16px rgb(0 0 0 / .75); background: var(--apk-flow-raise); }
    &.is-ghost.is-landing { box-shadow: inset 3px 0 var(--k); }
    &.is-blocked { background: repeating-linear-gradient(-45deg, var(--apk-flow-panel) 0 7px, color-mix(in oklch, var(--apk-flow-risk) 9%, var(--apk-flow-panel)) 7px 14px); }
  }
  &.is-mounting .apk-flow-card { animation: apk-flow-in .5s var(--apk-flow-spring) both; animation-delay: calc(var(--i, 0) * 30ms); }
  & .apk-flow-ph { border-radius: 9px; border: 1.5px dashed color-mix(in oklch, var(--c) 70%, transparent); background: color-mix(in oklch, var(--c) 10%, transparent); }
  & .apk-flow-c1 { display: flex; align-items: center; gap: 6px; font: 600 10.5px ui-monospace, Menlo, monospace; color: var(--apk-flow-mute); }
  & .apk-flow-c1 .apk-flow-cls { margin-left: auto; font: 650 9.5px system-ui; letter-spacing: .06em; text-transform: uppercase; color: var(--k); }
  & .apk-flow-ct { margin: 0; font-size: 12.5px; font-weight: 520; line-height: 1.35; text-wrap: pretty; }
  & .apk-flow-age { display: grid; grid-template-columns: auto 1fr; gap: 8px; align-items: center; font: 600 10.5px ui-monospace, Menlo, monospace; color: var(--apk-flow-mute); font-variant-numeric: tabular-nums; }
  & .apk-flow-bar { position: relative; height: 4px; border-radius: 2px; background: var(--apk-flow-line); }
  & .apk-flow-bar i { position: absolute; inset: 0 auto 0 0; width: calc(min(var(--f), 1) * 100%); border-radius: inherit; background: var(--apk-flow-b3); transition: width .6s var(--apk-flow-spring), background .3s; }
  & .apk-flow-bar[data-z="warn"] i { background: var(--apk-flow-b1); }
  & .apk-flow-bar[data-z="risk"] i { background: var(--apk-flow-risk); }
  & .apk-flow-bar b { position: absolute; top: -3px; bottom: -3px; width: 2px; left: calc(var(--s) * 100%); background: var(--apk-flow-ink); opacity: .5; border-radius: 1px; }
  & .apk-flow-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--apk-flow-risk); animation: apk-flow-risk 1.8s ease-out infinite; }

  /* ── insights ── */
  & .apk-flow-ins { min-height: 0; display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr); gap: 10px; padding: 0 12px 12px; }
  & figure { margin: 0; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); background: var(--apk-flow-panel); border-radius: 12px; padding: 10px 12px 8px; }
  & figcaption { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; margin-bottom: 6px;
    & b { font-size: 12px; font-weight: 700; } & span { font-size: 11px; color: var(--apk-flow-faint); }
  }
  & .apk-flow-legend { list-style: none; margin: 0 0 0 auto; padding: 0; display: flex; gap: 10px; font-size: 11px; color: var(--apk-flow-mute);
    & li { display: inline-flex; align-items: center; gap: 5px; font-variant-numeric: tabular-nums; }
    & i { width: 9px; height: 9px; border-radius: 2px; background: var(--c); }
    & b { font-weight: 650; color: var(--apk-flow-ink); }
  }
  & .apk-flow-cv { position: relative; min-height: 0; }
  & .apk-flow-cv canvas { position: absolute; inset: 0; width: 100%; height: 100%; cursor: crosshair; }
  & .apk-flow-aging svg { width: 100%; height: 100%; overflow: visible; }
  & .apk-flow-aging text { font: 600 9px ui-monospace, Menlo, monospace; fill: var(--apk-flow-faint); }
  & .apk-flow-aging .apk-flow-band { fill: color-mix(in oklch, var(--apk-flow-ink) 3%, transparent); }
  & .apk-flow-aging .apk-flow-sle { stroke: var(--apk-flow-risk); stroke-dasharray: 3 3; stroke-width: 1.2; vector-effect: non-scaling-stroke; }
  & .apk-flow-aging circle { stroke: var(--apk-flow-bg); stroke-width: 1.5; cursor: pointer; transition: translate .7s var(--apk-flow-spring), fill .3s, opacity .3s; vector-effect: non-scaling-stroke; }
  & .apk-flow-aging circle:hover { stroke: var(--apk-flow-ink); }

  /* ── peek ── */
  & .apk-flow-peek { position: absolute; z-index: 60; right: 12px; top: 64px; width: min(320px, calc(100% - 24px)); max-height: calc(100% - 76px); overflow-y: auto; padding: 14px; border-radius: 14px;
    background: color-mix(in oklch, var(--apk-flow-bg), white 9%); box-shadow: 0 0 0 1px var(--apk-flow-line2), 0 30px 60px -20px rgb(0 0 0 / .7);
    display: none; gap: 12px; transition: opacity .2s, translate .4s var(--apk-flow-spring);
    &.is-open { display: grid; @starting-style { opacity: 0; translate: 0 -8px; } }
    & h4 { margin: 0; font-size: 15px; font-weight: 700; letter-spacing: -.01em; text-wrap: balance; }
    & .apk-flow-x { position: absolute; right: 10px; top: 10px; border: 0; background: none; color: var(--apk-flow-mute); padding: 4px; border-radius: 6px; }
    & .apk-flow-x svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; display: block; }
    & label { display: grid; gap: 4px; font-size: 11px; color: var(--apk-flow-mute); }
    & select { padding: 5px 7px; border-radius: 7px; border: 1px solid var(--apk-flow-line2); background: var(--apk-flow-panel); font-size: 12.5px; }
    & .apk-flow-tog { display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: var(--apk-flow-ink); }
    & ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; font-size: 12px; color: var(--apk-flow-mute); }
    & ol li { display: grid; grid-template-columns: 10px 1fr auto; gap: 8px; align-items: center; }
    & ol i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  }
  & .apk-flow-toast { padding: 9px 9px 9px 14px; border-radius: 10px; background: var(--apk-flow-accent); color: var(--apk-flow-bg); font-weight: 600; font-size: 12.5px; box-shadow: 0 16px 36px -14px rgb(0 0 0 / .7);
    & [data-undo] { border: 0; border-radius: 7px; padding: 4px 9px; background: var(--apk-flow-bg); color: var(--apk-flow-accent); font-weight: 700; }
  }
}

@container (width < 960px) {
  .apk-flow .apk-flow-head { grid-template-columns: minmax(0, 1fr); grid-template-areas: "team" "kpis" "tools" "tabs"; }
  .apk-flow .apk-flow-kpis { justify-self: stretch; } .apk-flow .apk-flow-kpis div { flex: 1; min-width: 0; }
  .apk-flow .apk-flow-app { grid-template-rows: auto minmax(0, 1fr) 210px; }
}
@container (width < 760px) {
  .apk-flow .apk-flow-head { padding: 12px 12px 0; gap: 8px; }
  .apk-flow .apk-flow-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .apk-flow .apk-flow-kpis dd { font-size: 17px; } .apk-flow .apk-flow-kpis div { padding: 5px 8px; }
  .apk-flow .apk-flow-kpis dt { font-size: 10.5px; line-height: 1.25; }
  .apk-flow .apk-flow-cos { width: 100%; overflow-x: auto; flex-wrap: nowrap; scrollbar-width: none; }
  .apk-flow .apk-flow-search { flex: 1; } .apk-flow .apk-flow-search input { width: 100%; }
  .apk-flow .apk-flow-seg [data-v="split"] { display: none; }
  .apk-flow[data-view="split"] .apk-flow-app, .apk-flow[data-view="board"] .apk-flow-app { grid-template-rows: auto minmax(0, 1fr) 0; }
  .apk-flow[data-view="split"] .apk-flow-ins { display: none; }
  .apk-flow[data-view="charts"] .apk-flow-app { grid-template-rows: auto 0 minmax(0, 1fr); }
  .apk-flow:not([data-view="charts"]) .apk-flow-tabs { display: flex; margin: 0 -12px; overflow-x: auto; scrollbar-width: none; border-top: 1px solid var(--apk-flow-line);
    & button { flex: 1 0 auto; border: 0; background: none; padding: 9px 8px; font-size: 12px; font-weight: 650; color: var(--apk-flow-mute); border-bottom: 2px solid transparent; }
    & button span { font: 600 11px ui-monospace, Menlo, monospace; margin-left: 4px; color: var(--apk-flow-faint); }
    & button[aria-selected="true"] { color: var(--apk-flow-ink); border-bottom-color: var(--apk-flow-accent); }
  }
  .apk-flow .apk-flow-board { grid-auto-columns: 100%; gap: 0; padding: 0; scroll-snap-type: x mandatory; scrollbar-width: none; }
  .apk-flow .apk-flow-col { scroll-snap-align: start; border-radius: 0; background: none; }
  .apk-flow .apk-flow-col > header { display: none; }
  .apk-flow .apk-flow-list { padding: 10px 12px 24px; }
  .apk-flow .apk-flow-ins { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1.4fr) minmax(0, 1fr); padding-top: 12px; }
  .apk-flow .apk-flow-legend { margin-left: 0; flex-wrap: wrap; }
}

@media (prefers-reduced-motion: reduce) {
  .apk-flow *, .apk-flow *::before, .apk-flow *::after {
    animation-duration: .01ms !important; animation-iteration-count: 1 !important;
    animation-delay: 0s !important; transition-duration: .01ms !important;
    transition-delay: 0s !important; scroll-behavior: auto !important;
  }
  .apk-flow .apk-flow-card.is-ghost { scale: 1; rotate: 0deg !important; }
}

