  return h;
})();
const CYCLES = [3, 3, 4, 4, 5, 5, 6, 6, 6, 7, 8, 9, 11]; /* cycle times (days) of items finished in the last 14 days */

let view = 'split', q = '', cls = new Set(), openId = null, peekSig = '', hover = -1;
const boardEl = $('.apk-flow-board'), tabs = $('.apk-flow-tabs'), peek = $('.apk-flow-peek');
const colOf = id => COLS.find(c => data.cells[c[0]].includes(id))[0];
const cname = k => COLS.find(c => c[0] === k)[1];
/* resolve theme tokens (which may be color-mix()) to concrete colours the canvas can paint */
const probe = root.appendChild(Object.assign(doc.createElement('i'), { hidden: true }));
const css = v => { probe.style.color = 'var(' + v + ')'; return getComputedStyle(probe).color; };
function visible(id) {
  const x = data.items[id];
  if (cls.size && !cls.has(x.cls)) return false;
  if (q) { const s = (id + ' ' + x.title + ' ' + CLS[x.cls][0]).toLowerCase(); if (!q.split(/\s+/).every(w => s.includes(w))) return false; }
  return true;
}
function today() { const o = {}; COLS.forEach(c => { o[c[0]] = data.cells[c[0]].length; }); o.done = HIST.done[19] + data.doneToday.length; return o; }
function metrics() {
  const t = today(), wip = t.build + t.verify + t.release;
  const tp = t.done - HIST.done[6];
  const cyc = CYCLES.concat(data.doneToday.map(id => data.items[id].age)).sort((a, b) => a - b);
  const p85 = cyc[Math.min(cyc.length - 1, Math.ceil(cyc.length * .85) - 1)];
  const risk = ['build', 'verify', 'release'].reduce((s, k) => s + data.cells[k].filter(id => data.items[id].age > COLS.find(c => c[0] === k)[3]).length, 0);
  return { wip, tp, p85, risk };
}

boardEl.innerHTML = COLS.map((c, i) => '<section class="apk-flow-col" data-k="' + c[0] + '" style="--c:var(--apk-flow-b' + i + ')" aria-label="' + c[1] + '"><header><h3>' + c[1] + '</h3><span></span>' + (c[3] ? '<small>SLE ' + c[3] + 'd</small>' : '') + '</header><div class="apk-flow-list" role="list" data-key="' + c[0] + '" data-col="' + i + '" aria-label="' + c[1] + '"></div></section>').join('');
tabs.innerHTML = COLS.map(c => '<button type="button" role="tab" data-k="' + c[0] + '">' + c[1] + '<span></span></button>').join('');
$('.apk-flow-legend').innerHTML = COLS.map((c, i) => '<li style="--c:var(--apk-flow-b' + i + ')"><i></i>' + c[1] + ' <b data-lg="' + c[0] + '"></b></li>').join('');

function cardNode(id, k, i) {
  const x = data.items[id], c = COLS.find(cc => cc[0] === k), sle = c[3];
  let age;
  if (k === 'ready') age = '<div class="apk-flow-age"><span>queued ' + x.age + 'd</span></div>';
  else if (k === 'done') age = '<div class="apk-flow-age"><span>cycle ' + x.age + 'd' + (data.doneToday.includes(id) ? ' · today' : '') + '</span></div>';
  else {
    const f = x.age / (sle * 1.5), z = x.age > sle ? 'risk' : x.age > sle * .6 ? 'warn' : 'ok';
    age = '<div class="apk-flow-age"><span>' + x.age + 'd</span><span class="apk-flow-bar" data-z="' + z + '" style="--f:' + f.toFixed(3) + ';--s:' + (1 / 1.5).toFixed(3) + '" title="' + x.age + ' days in progress; 85% of items leave ' + c[1] + ' by day ' + sle + '"><i></i><b></b></span></div>';
  }
  const html = '<div class="apk-flow-c1"><span>' + id + '</span>' + (x.age > (sle || 99) && k !== 'done' && k !== 'ready' ? '<span class="apk-flow-dot" title="Older than the service level expectation"></span>' : '') +
    '<span class="apk-flow-cls">' + CLS[x.cls][0] + (x.due ? ' · ' + x.due : '') + '</span></div><p class="apk-flow-ct">' + esc(x.title) + '</p>' + age;
  const n = K.card(id, (x.blocked ? 'is-blocked' : '') + (openId === id ? ' is-open' : ''), html, id + ', ' + x.title + ', ' + CLS[x.cls][0] + ', ' + cname(k) + ', ' + x.age + ' days' + (x.blocked ? ', blocked' : ''));
  n.style.setProperty('--k', CLS[x.cls][1]); n.style.setProperty('--i', i);
