}

function render() {
  root.dataset.view = view;
  $$('.apk-flow-seg [data-v]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.v === view)));
  let i = 0;
  COLS.forEach(c => {
    const all = data.cells[c[0]], ids = all.filter(visible);
    K.place($('.apk-flow-list[data-key="' + c[0] + '"]', boardEl), ids.map(id => cardNode(id, c[0], i++)));
    const col = $('.apk-flow-col[data-k="' + c[0] + '"]', boardEl);
    $('header span', col).textContent = c[2] ? all.length + '/' + c[2] : all.length;
    col.toggleAttribute('data-over', !!(c[2] && all.length > c[2]));
    $('[data-k="' + c[0] + '"] span', tabs).textContent = all.length;
  });
  $('.apk-flow-cos').innerHTML = Object.keys(CLS).map(k => '<button type="button" class="apk-flow-cbtn" data-cls="' + k + '" aria-pressed="' + cls.has(k) + '" style="--c:' + CLS[k][1] + '"><i></i>' + CLS[k][0] + '<em>' + Object.keys(data.items).filter(id => data.items[id].cls === k && colOf(id) !== 'done').length + '</em></button>').join('');
  const m = metrics();
  [['tp', m.tp], ['wip', m.wip], ['ct', m.p85], ['risk', m.risk]].forEach(([k, v]) => $('[data-kpi="' + k + '"]').style.setProperty('--apk-flow-v', v));
  syncTabs();
  target = today(); kick();
  aging();
  if (openId) renderPeek();
}

/* ── cumulative flow on a DPR-aware canvas; today's slice springs to the new totals ── */
const cv = $('canvas', root), ctx = cv.getContext('2d'), wrap = $('.apk-flow-cv');
let Wd = 0, Ht = 0, shown = null, target = null, raf = 0;
function size() { const dpr = Math.min(2, devicePixelRatio || 1), r = wrap.getBoundingClientRect(); Wd = r.width; Ht = r.height; cv.width = Math.max(1, Math.round(Wd * dpr)); cv.height = Math.max(1, Math.round(Ht * dpr)); ctx.setTransform(dpr, 0, 0, dpr, 0, 0); }
function series(t) { return t === 20 ? shown : { ready: HIST.ready[t], build: HIST.build[t], verify: HIST.verify[t], release: HIST.release[t], done: HIST.done[t] }; }
function draw() {
  if (!Wd || !Ht || !shown) return;
  ctx.clearRect(0, 0, Wd, Ht);
  const order = ['done', 'release', 'verify', 'build', 'ready'];
  const tot = t => order.reduce((s, k) => s + series(t)[k], 0);
  let max = 0; for (let t = 0; t <= 20; t++) max = Math.max(max, tot(t));
  const minY = HIST.done[0] - 4, pad = 18, top = 6;
  const X = t => t / 20 * (Wd - 2) + 1, Y = v => Ht - pad - (v - minY) / (max * 1.04 - minY) * (Ht - pad - top);
  ctx.strokeStyle = css('--apk-flow-line'); ctx.lineWidth = 1;
  for (let g = 0; g < 4; g++) { const y = top + g * (Ht - pad - top) / 4; ctx.beginPath(); ctx.moveTo(0, y + .5); ctx.lineTo(Wd, y + .5); ctx.stroke(); }
  let lower = Array(21).fill(minY);
  order.forEach((k, j) => {
    const upper = lower.map((v, t) => v + series(t)[k] - (k === 'done' ? minY : 0));
    ctx.beginPath();
    for (let t = 0; t <= 20; t++) ctx[t ? 'lineTo' : 'moveTo'](X(t), Y(upper[t]));
    for (let t = 20; t >= 0; t--) ctx.lineTo(X(t), Y(lower[t]));
    ctx.closePath(); ctx.fillStyle = css('--apk-flow-b' + (4 - j)); ctx.globalAlpha = hover >= 0 ? .85 : 1; ctx.fill(); ctx.globalAlpha = 1;
    lower = upper;
  });
  ctx.fillStyle = css('--apk-flow-faint'); ctx.font = '600 9px ui-monospace, Menlo, monospace'; ctx.textBaseline = 'alphabetic';
  [0, 5, 10, 15, 20].forEach(t => { ctx.textAlign = t === 0 ? 'left' : t === 20 ? 'right' : 'center'; ctx.fillText(t === 20 ? 'today' : DATES[t], X(t), Ht - 4); });
  if (hover >= 0) { ctx.strokeStyle = css('--apk-flow-ink'); ctx.globalAlpha = .8; ctx.beginPath(); ctx.moveTo(X(hover) + .5, top); ctx.lineTo(X(hover) + .5, Ht - pad); ctx.stroke(); ctx.globalAlpha = 1; }
  const s = series(hover >= 0 ? hover : 20);
  COLS.forEach(c => { const el = $('[data-lg="' + c[0] + '"]'); const v = c[0] === 'done' ? Math.round(s.done) : Math.round(s[c[0]]); if (el.textContent !== String(v)) el.textContent = v; });
}
function kick() {
  if (!shown) shown = Object.assign({}, target);
  if (RM.matches) { shown = Object.assign({}, target); draw(); return; }
  if (!raf) raf = requestAnimationFrame(tween);
}
function tween() {
  if (!root.isConnected) return;
  raf = 0;
  let moving = false;
  for (const k in target) { const d = target[k] - shown[k]; if (Math.abs(d) > .01) { shown[k] += d * .16; moving = true; } else shown[k] = target[k]; }
