const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } size(); draw(); });
ro.observe(wrap);
cv.addEventListener('pointermove', e => { const r = cv.getBoundingClientRect(); const t = Math.max(0, Math.min(20, Math.round((e.clientX - r.left) / r.width * 20))); if (t !== hover) { hover = t; draw(); $('.apk-flow-cfd figcaption span').textContent = t === 20 ? 'Today, live from the board' : DATES[t]; } });
cv.addEventListener('pointerleave', () => { hover = -1; draw(); $('.apk-flow-cfd figcaption span').textContent = 'Sep 12 – today · hover to inspect a day'; });

/* ── aging WIP: keyed dots glide when work moves or ages ── */
const agSvg = $('.apk-flow-aging svg'), dots = new Map();
const AG = ['build', 'verify', 'release'];
agSvg.innerHTML = AG.map((k, i) => { const sle = COLS.find(c => c[0] === k)[3], x0 = 24 + i * 92, y = 130 - sle / 14 * 120;
  return '<rect class="apk-flow-band" x="' + x0 + '" y="10" width="84" height="120" rx="4"/><line class="apk-flow-sle" x1="' + x0 + '" x2="' + (x0 + 84) + '" y1="' + y + '" y2="' + y + '"/><text x="' + (x0 + 42) + '" y="145" text-anchor="middle">' + cname(k) + '</text>'; }).join('') +
  [0, 7, 14].map(d => '<text x="18" y="' + (133 - d / 14 * 120) + '" text-anchor="end">' + d + 'd</text>').join('') + '<g data-dots></g>';
const dotG = $('[data-dots]', agSvg);
function aging() {
  const seen = new Set();
  AG.forEach((k, i) => {
    const ids = data.cells[k];
    ids.forEach((id, j) => {
      const x = data.items[id], sle = COLS.find(c => c[0] === k)[3];
      let d = dots.get(id);
      if (!d) { d = doc.createElementNS('http://www.w3.org/2000/svg', 'circle'); d.setAttribute('r', '4.5'); d.dataset.id = id; d.appendChild(doc.createElementNS('http://www.w3.org/2000/svg', 'title')); dotG.appendChild(d); dots.set(id, d); }
      const cx = 24 + i * 92 + 14 + (j % 5) * 14 + (j > 4 ? 7 : 0), cy = 130 - Math.min(x.age, 14) / 14 * 120;
      d.style.translate = cx + 'px ' + cy + 'px';
      d.style.fill = x.age > sle ? css('--apk-flow-risk') : CLS[x.cls][1];
      d.style.opacity = visible(id) ? 1 : .2;
      d.firstChild.textContent = id + ' · ' + x.title + ' · ' + x.age + 'd in progress';
      seen.add(id);
    });
  });
  dots.forEach((d, id) => { if (!seen.has(id)) { d.remove(); dots.delete(id); } });
}
agSvg.addEventListener('click', e => { const d = e.target.closest('circle'); if (d) openPeek(d.dataset.id); });

/* ── moves ── */
function move(id, key, beforeId) {
  const from = colOf(id), was = JSON.stringify(data.cells), x = data.items[id];
  data.cells[from].splice(data.cells[from].indexOf(id), 1);
  const a = data.cells[key]; let i = beforeId ? a.indexOf(beforeId) : a.length; if (i < 0) i = a.length;
  a.splice(i, 0, id);
  if (JSON.stringify(data.cells) === was) return false;
  if (from !== key) {
    x.hist.push([cname(key), 'Oct 2']);
    if (from === 'ready' && key !== 'done') x.age = 0;
    if (key === 'done') { if (!data.doneToday.includes(id)) data.doneToday.push(id); } else data.doneToday = data.doneToday.filter(d => d !== id);
  }
  const lim = COLS.find(c => c[0] === key)[2];
  return from === key ? 'Reordered ' + id : id + ' → ' + cname(key) + (lim && a.length > lim ? ' · WIP ' + a.length + '/' + lim : '') + (key === 'done' && from !== 'done' ? ' · cycle ' + x.age + 'd' : '');
}
const name = id => id + ' ' + data.items[id].title;
const where = id => { const k = colOf(id), l = data.cells[k].filter(visible); return cname(k) + ', ' + (l.indexOf(id) + 1) + ' of ' + l.length; };

/* ── peek ── */
function renderPeek() {
  const x = data.items[openId]; if (!x) return;
  const k = colOf(openId), sig = JSON.stringify([openId, x, k]); if (sig === peekSig) return; peekSig = sig;
  peek.innerHTML = '<button type="button" class="apk-flow-x" data-close aria-label="Close"><svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6 6 18"/></svg></button>' +
    '<div class="apk-flow-c1"><span>' + openId + '</span><span class="apk-flow-cls" style="--k:' + CLS[x.cls][1] + '">' + CLS[x.cls][0] + '</span></div><h4>' + esc(x.title) + '</h4>' +
    '<label>Class of service<select data-f="cls">' + Object.keys(CLS).map(c => '<option value="' + c + '"' + (c === x.cls ? ' selected' : '') + '>' + CLS[c][0] + '</option>').join('') + '</select></label>' +
    '<label class="apk-flow-tog"><input type="checkbox" data-f="blocked"' + (x.blocked ? ' checked' : '') + '> Blocked</label>' +
    '<ol>' + [['In ' + cname(k), x.age + 'd']].concat(x.hist.slice().reverse()).map((h, i) => '<li style="--c:' + (i ? 'var(--apk-flow-faint)' : 'var(--apk-flow-accent)') + '"><i></i>' + h[0] + '<span>' + h[1] + '</span></li>').join('') + '</ol>';
}
function openPeek(id) { openId = id; peekSig = ''; render(); peek.classList.add('is-open'); const s = $('select', peek); if (s) s.focus({ preventScroll: true }); }
function closePeek() { const id = openId; if (!id) return; openId = null; peek.classList.remove('is-open'); render(); const n = K.els.get(id); if (n && n.isConnected) n.focus({ preventScroll: true }); else root.focus(); }
peek.addEventListener('click', e => { if (e.target.closest('[data-close]')) closePeek(); });
peek.addEventListener('change', e => {
  const f = e.target.dataset.f;
  K.apply(() => { const x = data.items[openId]; if (f === 'cls') { x.cls = e.target.value; return openId + ' is now ' + CLS[x.cls][0]; } if (f === 'blocked') { x.blocked = e.target.checked; return openId + (x.blocked ? ' blocked' : ' unblocked'); } return false; });
});

/* ── events ── */
function setView(v) { if (v === view) return; const go = () => { view = v; render(); size(); draw(); }; if (doc.startViewTransition && !RM.matches) doc.startViewTransition(go); else go(); }
root.addEventListener('click', e => {
  const t = e.target;
  const v = t.closest('[data-v]'); if (v) return setView(v.dataset.v);
  const c = t.closest('[data-cls]'); if (c && c.closest('.apk-flow-cos')) { cls.has(c.dataset.cls) ? cls.delete(c.dataset.cls) : cls.add(c.dataset.cls); return K.flip(render); }
  const card = t.closest('.apk-flow-card'); if (card && boardEl.contains(card)) return openPeek(card.dataset.id);
});
$('[data-q]').addEventListener('input', e => { q = e.target.value.trim().toLowerCase(); K.flip(render); });
$('[data-q]').addEventListener('keydown', e => { if (e.key === 'Escape') { e.stopPropagation(); e.target.value = ''; q = ''; K.flip(render); root.focus(); } });
function keys(e, typing) {
  if (e.key === 'Escape' && openId) { e.preventDefault(); return closePeek(); }
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key === '/') { e.preventDefault(); $('[data-q]').focus(); }
  else if (e.key.toLowerCase() === 'i') setView(view === 'split' ? 'board' : 'split');
  else if (e.key.toLowerCase() === 'c') setView('charts');
}
const K = boardKit({ get: () => data, set: d => { data = d; peekSig = ''; }, render, move, name, where, open: openPeek, keys, hscroll: () => boardEl, short: id => id });
const syncTabs = K.pager(boardEl, tabs);
root.classList.add('is-mounting');
size();
render();
setTimeout(() => root.classList.remove('is-mounting'), 1300);

css:
.apk-kds {
  position: relative; width: 100%; height: var(--apk-kds-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate;
  -webkit-tap-highlight-color: transparent; box-sizing: border-box;
  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & .apk-kds-layer { position: absolute; inset: 0; z-index: 90; pointer-events: none; overflow: clip; }
  & .apk-kds-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .apk-kds-list { position: relative; }
  & .apk-kds-card {
    user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;
    touch-action: manipulation; cursor: grab;
    &.is-src { display: none; }
  }
  & .apk-kds-card.is-ghost {
    position: absolute; left: 0; top: 0; margin: 0; z-index: 2; cursor: grabbing;
    scale: 1.04; will-change: translate, rotate;
    transition: scale .3s var(--apk-kds-spring), box-shadow .3s ease-out, opacity .2s;
    @starting-style { scale: 1; }
    &.is-over-zone { scale: .9; opacity: .8; }
  }
  & .apk-kds-card.is-flyer { z-index: 1; }
  & .apk-kds-ph { transition: opacity .18s ease-out; @starting-style { opacity: 0; } }
  &.is-dragging, &.is-dragging * { cursor: grabbing; }
  & .apk-kds-toast {
    position: absolute; z-index: 95; left: 50%; bottom: 16px; translate: -50% 140%;
    display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
    opacity: 0; pointer-events: none;
    transition: translate .45s var(--apk-kds-spring), opacity .2s ease-out;
    & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
    & [data-undo] { display: none; flex: none; }
    &.has-undo [data-undo] { display: inline-flex; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }
}

@keyframes apk-kds-print { from { clip-path: inset(0 0 100% 0); translate: 0 -10px; } to { clip-path: inset(0 0 -20px 0); translate: 0 0; } }
@keyframes apk-kds-flash { 0%, 100% { background: var(--hd); } 30% { background: var(--apk-kds-new); } }
@keyframes apk-kds-late { 50% { filter: brightness(1.25); } }
@keyframes apk-kds-in { from { opacity: 0; translate: 0 10px; } }

.apk-kds {
  --apk-kds-steel: oklch(0.25 0.012 240);
  --apk-kds-paper: oklch(0.97 0.012 90);
  --apk-kds-ink: oklch(0.21 0.005 90);
  --apk-kds-new: oklch(0.82 0.13 200);
  --apk-kds-warn: oklch(0.8 0.15 75);
  --apk-kds-late: oklch(0.63 0.21 27);
  --apk-kds-fg: oklch(0.94 0.008 240);
  --apk-kds-line: color-mix(in oklch, var(--apk-kds-fg) 12%, transparent);
  --apk-kds-mute: color-mix(in oklch, var(--apk-kds-fg) 58%, var(--apk-kds-steel));
  --apk-kds-pline: color-mix(in oklch, var(--apk-kds-ink) 16%, transparent);
  --apk-kds-pmute: color-mix(in oklch, var(--apk-kds-ink) 55%, var(--apk-kds-paper));
  --apk-kds-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --apk-kds-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  background:
    repeating-linear-gradient(90deg, rgb(255 255 255 / .012) 0 1px, transparent 1px 3px),
    linear-gradient(180deg, color-mix(in oklch, var(--apk-kds-steel), white 4%), var(--apk-kds-steel));
  color: var(--apk-kds-fg); color-scheme: dark; accent-color: var(--apk-kds-warn);
  font: 13px/1.35 system-ui, -apple-system, "Segoe UI", sans-serif; border-radius: 12px;

  & kbd { font: 700 10px/1 var(--apk-kds-mono); padding: 3px 5px 2px; border-radius: 4px; background: color-mix(in oklch, var(--apk-kds-fg) 10%, transparent); color: var(--apk-kds-fg); box-shadow: inset 0 -1px rgb(0 0 0 / .4); }
  & :focus-visible { outline: 2px solid var(--apk-kds-warn); outline-offset: 3px; }
  & .apk-kds-app { height: 100%; display: grid; grid-template: "head head" auto "rail ad" minmax(0, 1fr) "bar bar" auto / minmax(0, 1fr) 232px; }

  & .apk-kds-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px; padding: 12px 16px; border-bottom: 1px solid var(--apk-kds-line); }
  & .apk-kds-venue { display: grid;
    & b { font-size: 16px; font-weight: 760; letter-spacing: -.01em; } & span { font-size: 12px; color: var(--apk-kds-mute); font-variant-numeric: tabular-nums; }
  }
  & .apk-kds-stats { display: flex; gap: 18px; margin: 0;
    & dt { font-size: 10.5px; text-transform: uppercase; letter-spacing: .08em; color: var(--apk-kds-mute); }
    & dd { margin: 0; font: 700 18px/1.15 var(--apk-kds-mono); font-variant-numeric: tabular-nums; }
    & dd[data-hot] { color: var(--apk-kds-late); }
  }
  & .apk-kds-stations { display: flex; gap: 3px; margin-left: auto; padding: 3px; border-radius: 9px; background: rgb(0 0 0 / .25);
