  if (!n || !n.isConnected || RM.matches) { go(); return; }
  /* tear the ticket off the rail: a clone lifts and fades in the overlay layer while the data changes */
  const r = n.getBoundingClientRect(), rr = root.getBoundingClientRect(), c = n.cloneNode(true);
  ['data-id', 'tabindex', 'aria-describedby'].forEach(a => c.removeAttribute(a));
  Object.assign(c.style, { position: 'absolute', margin: 0, left: (r.left - rr.left) + 'px', top: (r.top - rr.top) + 'px', width: r.width + 'px' });
  $('.apk-kds-layer').append(c);
  go();
  c.animate([{ transform: 'none', opacity: 1, clipPath: 'inset(0)' }, { transform: 'translateY(-26px) rotate(-4deg)', opacity: .9, clipPath: 'inset(0 0 0 0)', offset: .35 }, { transform: 'translateY(-90px) rotate(-9deg) scale(.96)', opacity: 0, clipPath: 'inset(0 0 60% 0)' }], { duration: 650, easing: 'cubic-bezier(.4,0,.2,1)' }).onfinish = () => c.remove();
}
function recall() {
  if (!data.served.length) return;
  K.apply(() => { const id = data.served.pop(); data.times.pop(); data.cells.ready.unshift(id); return data.t[id].label + ' recalled to the window'; });
}
const name = id => 'Ticket ' + data.t[id].label;
const where = id => { const k = colOf(id); return COLS.find(c => c[0] === k)[1] + ', ' + (data.cells[k].indexOf(id) + 1) + ' of ' + data.cells[k].length; };

/* ── events ── */
root.addEventListener('click', e => {
  const t = e.target;
  const it = t.closest('[data-it]');
  if (it) { const id = it.closest('.apk-kds-card').dataset.id, i = +it.dataset.it; return K.apply(() => { const x = data.t[id].items[i]; x.st = !x.st; return data.t[id].label + ' · ' + MENU[x.m][0] + (x.st ? ' up' : ' back on'); }); }
  const s = t.closest('[data-stn]'); if (s) { station = s.dataset.stn; return render(); }
  const h = t.closest('[data-hl]'); if (h) { hl = hl === h.dataset.hl ? null : h.dataset.hl; return render(); }
  const v = t.closest('[data-v]'); if (v) { view = v.dataset.v; return render(); }
  if (t.closest('[data-act="recall"]')) return recall();
  const c = t.closest('.apk-kds-card'); if (c && rail.contains(c)) { sel = c.dataset.id; render(); }
});
function keys(e, typing) {
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key.toLowerCase();
  if (/^[1-9]$/.test(e.key)) { const id = order()[+e.key - 1]; if (id) { sel = id; render(); K.focusCard(K.els.get(id)); } }
  else if (k === 'r') recall();
  else if (k === 's') { const all = ['all'].concat(Object.keys(STN)); station = all[(all.indexOf(station) + 1) % all.length]; render(); }
  else if (e.key === 'Escape') { hl = null; sel = null; render(); }
  else if (e.key === 'Enter' && sel) bump(sel);
}

const K = boardKit({ get: () => data, set: d => { data = d; }, render, move, name, where, open: bump, keys, hscroll: () => rail });
const syncTabs = K.pager(rail, tabs);

/* ── service clock: timers tick every second, a new ticket prints every ~16 s; paused off screen ── */
const io = new IntersectionObserver(es => { onScreen = es[es.length - 1].isIntersecting; });
io.observe(root);
const timer = setInterval(() => {
  if (!root.isConnected) return void (clearInterval(timer), io.disconnect());
  if (!onScreen || doc.hidden) return;
  K.els.forEach((n, id) => {
    const t = data.t[id]; if (!t || !n.isConnected) return;
    const e = $('[data-t0]', n); if (e) e.textContent = mmss(el(t));
    const s = stateOf(t); if (n.dataset.state !== s) n.dataset.state = s;
  });
  stats();
  if (++tick % 16 || K.busy() || !POOL.length) return;
  const p = POOL.shift(), id = 'k' + (++seq), t0 = Date.now();
  K.amend(d => { d.t[id] = { label: p[0], cov: p[1], server: p[2], type: p[3], t0, items: p[4].map(i => ({ m: i[0], q: i[1], mod: i[2] || '', st: false })) }; d.cells.new.push(id); });
  fresh.add(id); setTimeout(() => fresh.delete(id), 1800);
  K.flip(render); K.toast('New ticket ' + p[0] + ' · ' + p[3]);
}, 1000);
render();

css:
.apk-deals {
  position: relative; width: 100%; height: var(--apk-deals-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate;
  -webkit-tap-highlight-color: transparent; box-sizing: border-box;
  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & .apk-deals-layer { position: absolute; inset: 0; z-index: 90; pointer-events: none; overflow: clip; }
  & .apk-deals-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .apk-deals-list { position: relative; }
  & .apk-deals-card {
    user-select: none; -webkit-user-select: none; -webkit-touch-callout: none;
    touch-action: manipulation; cursor: grab;
    &.is-src { display: none; }
  }
  & .apk-deals-card.is-ghost {
    position: absolute; left: 0; top: 0; margin: 0; z-index: 2; cursor: grabbing;
    scale: 1.04; will-change: translate, rotate;
    transition: scale .3s var(--apk-deals-spring), box-shadow .3s ease-out, opacity .2s;
    @starting-style { scale: 1; }
    &.is-over-zone { scale: .9; opacity: .8; }
  }
  & .apk-deals-card.is-flyer { z-index: 1; }
  & .apk-deals-ph { transition: opacity .18s ease-out; @starting-style { opacity: 0; } }
  &.is-dragging, &.is-dragging * { cursor: grabbing; }
  & .apk-deals-toast {
    position: absolute; z-index: 95; left: 50%; bottom: 16px; translate: -50% 140%;
    display: flex; align-items: center; gap: 12px; max-width: calc(100% - 32px);
    opacity: 0; pointer-events: none;
    transition: translate .45s var(--apk-deals-spring), opacity .2s ease-out;
    & [data-msg] { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }
    & [data-undo] { display: none; flex: none; }
    &.has-undo [data-undo] { display: inline-flex; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }
}

@property --apk-deals-v { syntax: '<integer>'; inherits: false; initial-value: 0; }
@keyframes apk-deals-in { from { opacity: 0; translate: 0 10px; } }
@keyframes apk-deals-star { 0% { scale: 1; } 40% { scale: 1.45; rotate: 18deg; } 100% { scale: 1; rotate: 0deg; } }
@keyframes apk-deals-won { 0% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--apk-deals-gold) 70%, transparent); } 100% { box-shadow: 0 0 0 16px transparent; } }

.apk-deals {
  --apk-deals-bg: oklch(0.968 0.006 80);
  --apk-deals-ink: oklch(0.23 0.025 165);
  --apk-deals-accent: oklch(0.5 0.11 162);
  --apk-deals-gold: oklch(0.78 0.13 85);
  --apk-deals-lost: oklch(0.57 0.15 25);
  --apk-deals-card: oklch(0.995 0.003 80);
  --apk-deals-line: color-mix(in oklch, var(--apk-deals-ink) 10%, transparent);
  --apk-deals-line2: color-mix(in oklch, var(--apk-deals-ink) 18%, transparent);
  --apk-deals-mute: color-mix(in oklch, var(--apk-deals-ink) 58%, var(--apk-deals-bg));
  --apk-deals-faint: color-mix(in oklch, var(--apk-deals-ink) 38%, var(--apk-deals-bg));
  --apk-deals-tint: color-mix(in oklch, var(--apk-deals-accent) 8%, var(--apk-deals-bg));
  --apk-deals-spring: linear(0, 0.06 3%, 0.24 7%, 0.52 12%, 0.8 18%, 0.95 23%, 1.03 28%, 1.06 32%, 1.05 37%, 1.02 45%, 1 55%, 0.996 66%, 1);
  background: var(--apk-deals-bg); color: var(--apk-deals-ink); color-scheme: light; accent-color: var(--apk-deals-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", sans-serif; border-radius: 16px; box-shadow: 0 0 0 1px var(--apk-deals-line);
  font-variant-numeric: tabular-nums;

  & kbd { font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--apk-deals-line2); color: var(--apk-deals-mute); background: var(--apk-deals-card); }
  & :focus-visible { outline: 2px solid var(--apk-deals-accent); outline-offset: 2px; }
  & .apk-deals-app { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); grid-template-columns: minmax(0, 1fr); }

  /* ── header + forecast ── */
  & .apk-deals-head { display: grid; grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "title fc" "tools tools" "tabs tabs"; gap: 12px 28px; padding: 16px 18px 12px; border-bottom: 1px solid var(--apk-deals-line); }
  & .apk-deals-title { grid-area: title;
    & h2 { margin: 0; font-size: clamp(17px, 1.2cqi + 8px, 22px); font-weight: 760; letter-spacing: -.03em; text-wrap: balance; }
    & p { margin: 3px 0 0; color: var(--apk-deals-mute); font-size: 12px; }
  }
  & .apk-deals-fc { grid-area: fc; align-self: center; display: grid; gap: 7px; }
  & .apk-deals-fcnums { display: flex; flex-wrap: wrap; gap: 4px 16px; font-size: 12px; color: var(--apk-deals-mute);
    & span { display: inline-flex; align-items: center; gap: 6px; }
    & b { color: var(--apk-deals-ink); font-weight: 720; font-size: 13px; }
    & .apk-deals-gap { margin-left: auto; } & .apk-deals-gap b { color: var(--apk-deals-lost); }
  }
  & .apk-deals-k { --apk-deals-v: 0; counter-reset: v var(--apk-deals-v); transition: --apk-deals-v .9s cubic-bezier(.3,.7,.2,1); }
  & .apk-deals-k::after { content: "$" counter(v) "k"; }
  & .apk-deals-sw { width: 9px; height: 9px; border-radius: 3px; }
  & [data-c="won"] { background: var(--apk-deals-accent); }
  & [data-c="commit"] { background: color-mix(in oklch, var(--apk-deals-accent) 55%, var(--apk-deals-gold)); }
  & [data-c="best"] { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--apk-deals-accent) 45%, transparent) 0 3px, transparent 3px 6px); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apk-deals-accent) 40%, transparent); }
  & .apk-deals-fcbar { position: relative; display: flex; height: 12px; border-radius: 6px; background: color-mix(in oklch, var(--apk-deals-ink) 7%, transparent); overflow: visible;
    & i { height: 100%; width: calc(var(--w, 0) * 100%); transition: width .8s var(--apk-deals-spring); }
    & [data-seg="won"] { background: var(--apk-deals-accent); border-radius: 6px 0 0 6px; }
    & [data-seg="commit"] { background: color-mix(in oklch, var(--apk-deals-accent) 55%, var(--apk-deals-gold)); }
    & [data-seg="best"] { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--apk-deals-accent) 45%, transparent) 0 4px, transparent 4px 8px); }
  }
  & .apk-deals-quota { position: absolute; top: -4px; bottom: -4px; left: calc(var(--q) * 100%); width: 2px; background: var(--apk-deals-ink); border-radius: 1px;
    & span { position: absolute; right: 6px; top: -1px; font: 600 10.5px system-ui; font-style: normal; white-space: nowrap; color: var(--apk-deals-mute); translate: 0 -100%; }
  }
  & .apk-deals-tools { grid-area: tools; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; }
  & .apk-deals-owners { display: flex; gap: 2px; margin-right: auto; }
  & .apk-deals-ow { display: inline-flex; align-items: center; gap: 6px; border: 0; background: none; padding: 3px 9px 3px 3px; border-radius: 16px; font-size: 12px; font-weight: 600; color: var(--apk-deals-mute); transition: background .15s, color .15s;
    &:hover { background: color-mix(in oklch, var(--apk-deals-ink) 6%, transparent); }
    &[aria-pressed="true"] { background: var(--apk-deals-ink); color: var(--apk-deals-bg); }
  }
  & .apk-deals-av { width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; font-size: 9px; font-weight: 760; color: oklch(0.3 0.07 var(--h)); background: oklch(0.88 0.07 var(--h)); flex: none; }
  & .apk-deals-search { display: flex; align-items: center; gap: 6px; height: 30px; padding: 0 6px 0 10px; border-radius: 8px; background: var(--apk-deals-card); border: 1px solid var(--apk-deals-line2);
    & svg { width: 14px; height: 14px; fill: none; stroke: var(--apk-deals-mute); stroke-width: 2.2; stroke-linecap: round; }
    & input { border: 0; outline: 0; background: none; width: 130px; min-width: 0; }
    &:focus-within { border-color: var(--apk-deals-accent); box-shadow: 0 0 0 3px var(--apk-deals-tint); }
  }
  & .apk-deals-sort { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--apk-deals-mute);
    & select { border: 1px solid var(--apk-deals-line2); border-radius: 7px; background: var(--apk-deals-card); padding: 4px 6px; font-size: 12px; }
  }
  & .apk-deals-seg { display: flex; padding: 3px; border-radius: 9px; background: color-mix(in oklch, var(--apk-deals-ink) 6%, transparent);
    & button { border: 0; background: none; padding: 4px 10px; border-radius: 6px; font-size: 12px; font-weight: 650; color: var(--apk-deals-mute); }
    & [aria-selected="true"] { background: var(--apk-deals-card); color: var(--apk-deals-ink); box-shadow: 0 1px 2px var(--apk-deals-line2); }
  }
  & .apk-deals-new { border: 0; border-radius: 8px; background: var(--apk-deals-accent); color: oklch(0.99 0.01 162); font-weight: 700; padding: 7px 10px; font-size: 12.5px; display: inline-flex; gap: 6px; align-items: center; }
  & .apk-deals-new kbd { background: none; color: inherit; border-color: color-mix(in oklch, white 40%, transparent); }
  & .apk-deals-tabs { grid-area: tabs; display: none; }

  /* ── board ── */
  & .apk-deals-main { min-height: 0; position: relative; }
  & .apk-deals-board { height: 100%; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(196px, 1fr); gap: 10px; padding: 12px 14px 14px; overflow-x: auto; scrollbar-width: thin; }
  &[data-view="table"] .apk-deals-board { display: none; }
  & .apk-deals-col { display: flex; flex-direction: column; min-height: 0; border-radius: 13px; background: color-mix(in oklch, var(--apk-deals-ink) 3.5%, var(--apk-deals-bg)); transition: background .2s, box-shadow .2s; }
  & .apk-deals-col > header { padding: 11px 12px 9px; display: grid; grid-template-columns: 1fr auto; gap: 1px 8px;
    & h3 { margin: 0; font-size: 12.5px; font-weight: 720; }
    & .apk-deals-pr { font: 650 10.5px ui-monospace, Menlo, monospace; color: var(--apk-deals-accent); background: var(--apk-deals-tint); border-radius: 5px; padding: 2px 5px; }
    & .apk-deals-sum { grid-column: 1 / -1; display: flex; justify-content: space-between; font-size: 11.5px; color: var(--apk-deals-mute); }
    & .apk-deals-sum b { color: var(--apk-deals-ink); font-weight: 700; }
  }
  & .apk-deals-col[data-k="won"] { background: color-mix(in oklch, var(--apk-deals-gold) 13%, var(--apk-deals-bg)); }
  & .apk-deals-col[data-k="won"] .apk-deals-pr { background: var(--apk-deals-gold); color: oklch(0.3 0.06 85); }
  &.is-dragging .apk-deals-col:has(.apk-deals-ph) { background: var(--apk-deals-tint); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--apk-deals-accent) 40%, transparent); }
  & .apk-deals-list { flex: 1; min-height: 0; overflow-y: auto; padding: 0 8px 12px; display: flex; flex-direction: column; gap: 8px; scrollbar-width: thin; }

  & .apk-deals-card {
    position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 8px; padding: 11px 11px 10px; border-radius: 11px; background: var(--apk-deals-card);
    box-shadow: 0 0 0 1px var(--apk-deals-line), 0 1px 2px var(--apk-deals-line);
    transition: box-shadow .2s, translate .25s var(--apk-deals-spring);
    &:hover { box-shadow: 0 0 0 1px var(--apk-deals-line2), 0 10px 22px -14px color-mix(in oklch, var(--apk-deals-ink) 50%, transparent); translate: 0 -1px; }
    &.is-open { box-shadow: 0 0 0 2px var(--apk-deals-accent); }
    &.is-commit { box-shadow: 0 0 0 1px color-mix(in oklch, var(--apk-deals-gold) 70%, transparent), 0 1px 2px var(--apk-deals-line); }
    &.is-won { animation: apk-deals-won 1s ease-out 2; }
    &.is-lifted { outline: 2px dashed var(--apk-deals-accent); outline-offset: 3px; translate: 0 -3px; }
    &.is-ghost { box-shadow: 0 0 0 1.5px var(--apk-deals-accent), 0 28px 44px -18px color-mix(in oklch, var(--apk-deals-ink) 50%, transparent); }
    &.is-ghost.is-landing { box-shadow: 0 0 0 1px var(--apk-deals-line); }
    &.is-ghost.is-over-zone { filter: saturate(0); }
  }
  &.is-mounting .apk-deals-card { animation: apk-deals-in .5s var(--apk-deals-spring) both; animation-delay: calc(var(--i, 0) * 26ms); }
  & .apk-deals-ph { border-radius: 11px; background: var(--apk-deals-tint); box-shadow: inset 0 0 0 1.5px color-mix(in oklch, var(--apk-deals-accent) 45%, transparent); }
  & .apk-deals-acct, & .apk-deals-opp { grid-column: 1; }
  & .apk-deals-acct { font-weight: 700; font-size: 13px; letter-spacing: -.01em; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .apk-deals-star { grid-row: 1 / span 2; grid-column: 2; align-self: start; border: 0; background: none; padding: 2px; margin: -3px -3px 0 0; color: var(--apk-deals-faint); border-radius: 6px; display: inline-flex; transition: color .2s; }
  & .apk-deals-star svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linejoin: round; }
  & .apk-deals-star:hover { color: var(--apk-deals-gold); }
  & .apk-deals-star[aria-pressed="true"] { color: var(--apk-deals-gold); }
  & .apk-deals-star[aria-pressed="true"] svg { fill: currentColor; animation: apk-deals-star .5s var(--apk-deals-spring); }
  & .apk-deals-opp { color: var(--apk-deals-mute); font-size: 11.5px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & .apk-deals-val { grid-column: 1 / -1; display: flex; align-items: baseline; gap: 8px; margin-top: 6px;
    & b { font-size: 18px; font-weight: 760; letter-spacing: -.03em; }
    & small { font-size: 11px; color: var(--apk-deals-faint); }
  }
  & .apk-deals-vbar { grid-column: 1 / -1; height: 3px; border-radius: 2px; background: color-mix(in oklch, var(--apk-deals-ink) 7%, transparent); overflow: hidden; }
  & .apk-deals-vbar i { display: block; height: 100%; width: calc(var(--f) * 100%); background: var(--apk-deals-accent); border-radius: inherit; transition: width .6s var(--apk-deals-spring); }
  & .apk-deals-meta { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; margin-top: 6px; font-size: 11.5px; color: var(--apk-deals-mute); }
  & .apk-deals-meta .apk-deals-av { width: 20px; height: 20px; font-size: 8.5px; }
  & .apk-deals-hl { width: 7px; height: 7px; border-radius: 50%; background: var(--apk-deals-accent); margin-left: auto; }
  & .apk-deals-hl[data-h="warn"] { background: var(--apk-deals-gold); }
  & .apk-deals-hl[data-h="cold"] { background: var(--apk-deals-lost); }

  & .apk-deals-lost {
    position: absolute; left: 14px; right: 14px; bottom: 12px; height: 58px; z-index: 5; border-radius: 13px; display: flex; align-items: center; justify-content: center; gap: 10px;
    color: var(--apk-deals-lost); background: color-mix(in oklch, var(--apk-deals-card) 90%, transparent); backdrop-filter: blur(6px); border: 1.5px dashed color-mix(in oklch, var(--apk-deals-lost) 50%, transparent);
    translate: 0 150%; opacity: 0; transition: translate .45s var(--apk-deals-spring), opacity .2s, background .2s, scale .3s var(--apk-deals-spring);
    & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
  }
  &.is-dragging .apk-deals-lost { translate: 0 0; opacity: 1; }
  & .apk-deals-lost.is-over { background: color-mix(in oklch, var(--apk-deals-lost) 12%, var(--apk-deals-card)); scale: 1.02; }

  /* ── forecast table ── */
  & .apk-deals-table { position: absolute; inset: 0; overflow: auto; padding: 14px 18px; }
  & .apk-deals-table[hidden] { display: none; }
  & .apk-deals-table table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; animation: apk-deals-in .4s var(--apk-deals-spring) both; }
  & .apk-deals-table th { text-align: right; font-size: 10.5px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--apk-deals-mute); padding: 8px 10px; border-bottom: 1px solid var(--apk-deals-line2); }
  & .apk-deals-table th:first-child, & .apk-deals-table td:first-child { text-align: left; }
  & .apk-deals-table td { text-align: right; padding: 11px 10px; border-bottom: 1px solid var(--apk-deals-line); }
